window.trendingPapers = {
    "today": [{"paper": {"id": "2609.39601", "authors": [{"_id": "6abf173c5ff0ac8de3b84ab6", "name": "Qize Yu", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84ab7", "name": "Lianrui Fan", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84ab8", "name": "Boyu Chen", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84ab9", "name": "Jiaqi Liang", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84aba", "name": "Xini Ding", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84abb", "name": "Yue Chen", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84abc", "name": "Zetian Song", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84abd", "name": "Yuran Wang", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84abe", "name": "Yi Zou", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84abf", "name": "Kaixuan Wang", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84ac0", "name": "Tianxing Chen", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84ac1", "name": "Wenxuan Song", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84ac2", "name": "Bohan Zhou", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84ac3", "name": "Mingleyang Li", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84ac4", "name": "Siqiao Huang", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84ac5", "name": "Yuqi Ye", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84ac6", "name": "Caigao Jiang", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84ac7", "name": "Wei Wei", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84ac8", "name": "Ruihai Wu", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84ac9", "name": "Hang Zhang", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84aca", "name": "Yixiao Ge", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84acb", "name": "Shuchang Zhou", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84acc", "name": "Shilong Liu", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84acd", "name": "Xianming Liu", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84ace", "name": "Ping Luo", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84acf", "name": "Shiyu Huang", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/692fa5d17ff1da99eb783dfb/TDAG8fc3WnRWLeebJe2xD.mp4", "https://cdn-uploads.huggingface.co/production/uploads/692fa5d17ff1da99eb783dfb/MkqgBIRZBtPC9vva4I_H6.jpeg"], "publishedAt": "2026-09-30T00:00:00.000Z", "submittedOnDailyAt": "2026-10-13T00:00:00.000Z", "title": "GroundingPI: A Grounding Foundation Model towards Physical Intelligence with Visual Primitives", "submittedOnDailyBy": {"_id": "692fa5d17ff1da99eb783dfb", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/692fa5d17ff1da99eb783dfb/GZ2TD9ua-pigxz5kEHRYX.jpeg", "isPro": false, "fullname": "Qize Yu", "user": "Skywalker0410", "type": "user", "name": "Skywalker0410"}, "summary": "Precise grounding matters. It specifies which object is the target and where that object is, even in clutter and for tiny objects, and it has to be fast enough for closed-loop control. Yet vision-language-action (VLA) and world-action models (WAMs) take perception from general-purpose vision-language and video-generation backbones, which still fail in these settings. We introduce GroundingPI, a 4B grounding foundation model that generates points and boxes as quantized coordinates in a shared vocabulary. Training combines multimodal and spatial pretraining, supervised fine-tuning, and reinforcement learning with GRPO, using supervision from public datasets and dedicated data engines. Against 44 baselines across 34 grounding benchmarks spanning 11 perceptual capabilities, GroundingPI establishes a new state of the art, averaging 73.68%, above the larger GPT-6 Astra (71.54%). As a downstream visual backbone, GroundingPI improves performance on robotic manipulation and autonomous driving. On RoboTwin 2.0, it outperforms every mainstream backbone we evaluate in all four out-of-distribution settings, by up to 24.8% relative to the strongest backbone. On RoboCasa-GR1, GroundingPI trained with 50% of the demonstrations outperforms those baselines trained with 75%. On nuScenes, used as the visual backbone, GroundingPI attains an average open-loop L2 error of 0.296 m. We systematically analyze GroundingPI's pretraining in scale and data composition. Downstream autonomous driving and robotic manipulation improve as the pretraining is scaled. Analyzing the data recipe across these 11 perceptual capabilities shows dense grounding's substantial benefits for both, and OCR's potential as a catalyst for perceptual learning. These results support grounding as a perceptual foundation, and dedicated perceptual pretraining as a promising direction for foundation models of physical intelligence.", "upvotes": 37, "discussionId": "6abf173d5ff0ac8de3b84ae6", "projectPage": "https://groundingpi.github.io/", "githubRepo": "https://github.com/groundingpi/GroundingPI", "githubRepoAddedBy": "user", "githubStars": 19, "organization": {"_id": "6aa24a85fc727b9188a95572", "name": "XPENG-AI", "fullname": "XPENG AI", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/6406db5cd684369027166986/DAJtDU_HssW_R7WIw0USp.jpeg"}, "summary_zh": "<ul>\n    <li>GroundingPI \u662f\u4e00\u4e2a\u65b0\u7684\u57fa\u7840\u6a21\u578b\uff0c\u80fd\u5feb\u901f\u51c6\u786e\u5730\u8bc6\u522b\u548c\u5b9a\u4f4d\u7269\u4f53\uff0c\u9002\u7528\u4e8e\u590d\u6742\u548c\u5c0f\u578b\u7269\u4f53\u3002</li>\n    <li>\u8be5\u6a21\u578b\u7ed3\u5408\u4e86\u591a\u6a21\u6001\u548c\u7a7a\u95f4\u9884\u8bad\u7ec3\u3001\u76d1\u7763\u5fae\u8c03\u548c\u5f3a\u5316\u5b66\u4e60\uff0c\u6548\u679c\u4f18\u4e8e\u73b0\u6709\u768444\u4e2a\u57fa\u7ebf\u6a21\u578b\u3002</li>\n    <li>\u5728\u591a\u4e2a\u6d4b\u8bd5\u57fa\u51c6\u4e2d\uff0cGroundingPI \u7684\u5e73\u5747\u5f97\u5206\u4e3a73.68%\uff0c\u8d85\u8fc7\u4e86\u66f4\u5927\u7684 GPT-6 Astra \u6a21\u578b\u3002</li>\n    <li>\u4f5c\u4e3a\u89c6\u89c9\u57fa\u7840\uff0cGroundingPI \u5728\u673a\u5668\u4eba\u64cd\u4f5c\u548c\u81ea\u52a8\u9a7e\u9a76\u65b9\u9762\u8868\u73b0\u51fa\u8272\uff0c\u5c24\u5176\u5728 RoboTwin 2.0 \u548c RoboCasa-GR1 \u6d4b\u8bd5\u4e2d\u3002</li>\n    <li>\u9884\u8bad\u7ec3\u7684\u89c4\u6a21\u548c\u6570\u636e\u7ec4\u6210\u5bf9\u6a21\u578b\u6027\u80fd\u6709\u663e\u8457\u5f71\u54cd\uff0c\u652f\u6301\u5c06\u57fa\u7840\u6a21\u578b\u7684\u611f\u77e5\u80fd\u529b\u4f5c\u4e3a\u672a\u6765\u7814\u7a76\u7684\u65b9\u5411\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>GroundingPI is a new model designed to accurately identify and locate objects quickly, even in cluttered environments.</li>\n    <li>It is trained using a combination of different techniques, including multimodal training and reinforcement learning, to improve its performance.</li>\n    <li>In tests against 44 other models, GroundingPI achieved the highest average score of 73.68%, outperforming the larger GPT-6 Astra model.</li>\n    <li>GroundingPI enhances tasks in robotic manipulation and autonomous driving, showing significant improvements on various benchmarks.</li>\n    <li>Research indicates that better pretraining strategies and data composition lead to better performance in these applications.</li>\n</ul>"}, "publishedAt": "2026-09-29T20:00:00.000Z", "title": "GroundingPI: A Grounding Foundation Model towards Physical Intelligence with Visual Primitives", "summary": "Precise grounding matters. It specifies which object is the target and where that object is, even in clutter and for tiny objects, and it has to be fast enough for closed-loop control. Yet vision-language-action (VLA) and world-action models (WAMs) take perception from general-purpose vision-language and video-generation backbones, which still fail in these settings. We introduce GroundingPI, a 4B grounding foundation model that generates points and boxes as quantized coordinates in a shared vocabulary. Training combines multimodal and spatial pretraining, supervised fine-tuning, and reinforcement learning with GRPO, using supervision from public datasets and dedicated data engines. Against 44 baselines across 34 grounding benchmarks spanning 11 perceptual capabilities, GroundingPI establishes a new state of the art, averaging 73.68%, above the larger GPT-6 Astra (71.54%). As a downstream visual backbone, GroundingPI improves performance on robotic manipulation and autonomous driving. On RoboTwin 2.0, it outperforms every mainstream backbone we evaluate in all four out-of-distribution settings, by up to 24.8% relative to the strongest backbone. On RoboCasa-GR1, GroundingPI trained with 50% of the demonstrations outperforms those baselines trained with 75%. On nuScenes, used as the visual backbone, GroundingPI attains an average open-loop L2 error of 0.296 m. We systematically analyze GroundingPI's pretraining in scale and data composition. Downstream autonomous driving and robotic manipulation improve as the pretraining is scaled. Analyzing the data recipe across these 11 perceptual capabilities shows dense grounding's substantial benefits for both, and OCR's potential as a catalyst for perceptual learning. These results support grounding as a perceptual foundation, and dedicated perceptual pretraining as a promising direction for foundation models of physical intelligence.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/692fa5d17ff1da99eb783dfb/TDAG8fc3WnRWLeebJe2xD.mp4", "https://cdn-uploads.huggingface.co/production/uploads/692fa5d17ff1da99eb783dfb/MkqgBIRZBtPC9vva4I_H6.jpeg"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2609.39601.png", "numComments": 1, "submittedBy": {"_id": "692fa5d17ff1da99eb783dfb", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/692fa5d17ff1da99eb783dfb/GZ2TD9ua-pigxz5kEHRYX.jpeg", "fullname": "Qize Yu", "name": "Skywalker0410", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 5, "isUserFollowing": false}, "organization": {"_id": "6aa24a85fc727b9188a95572", "name": "XPENG-AI", "fullname": "XPENG AI", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/6406db5cd684369027166986/DAJtDU_HssW_R7WIw0USp.jpeg"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.13166", "authors": [{"_id": "6acc50ce0ee6ff34004fde8d", "user": {"_id": "6901b520f8f20b9d7015a38d", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/6901b520f8f20b9d7015a38d/HIlNYBWGOI_XhI9aUJoAl.jpeg", "isPro": false, "fullname": "Shun Zou", "user": "shunzou05", "type": "user", "name": "shunzou05"}, "name": "Shun Zou", "status": "claimed_verified", "statusLastChangedAt": "2026-10-12T08:45:06.115Z", "hidden": false}, {"_id": "6acc50ce0ee6ff34004fde8e", "name": "Ziyu Ma", "hidden": false}, {"_id": "6acc50ce0ee6ff34004fde8f", "name": "Yi Zou", "hidden": false}, {"_id": "6acc50ce0ee6ff34004fde90", "name": "Yong Wang", "hidden": false}, {"_id": "6acc50ce0ee6ff34004fde91", "name": "Lin Chen", "hidden": false}, {"_id": "6acc50ce0ee6ff34004fde92", "name": "Zehui Chen", "hidden": false}, {"_id": "6acc50ce0ee6ff34004fde93", "name": "Guanhua Chen", "hidden": false}, {"_id": "6acc50ce0ee6ff34004fde94", "name": "Xiangxiang Chu", "hidden": false}, {"_id": "6acc50ce0ee6ff34004fde95", "name": "Feng Zhao", "hidden": false}], "publishedAt": "2026-10-09T00:00:00.000Z", "submittedOnDailyAt": "2026-10-13T00:00:00.000Z", "title": "Scaling Agentic Data for Long-Horizon Terminal Intelligence", "submittedOnDailyBy": {"_id": "64d1dc5273174cecdffc97d3", "avatarUrl": "/avatars/6564e6b68fee9673f75b6366adf39a3b.svg", "isPro": false, "fullname": "Wang Yong", "user": "seashell11", "type": "user", "name": "seashell11"}, "summary": "Terminal agents are moving beyond local operations toward completing real-world professional tasks. Short trajectories can demonstrate commands and tool calls, but they do not fully show how agents accumulate evidence through exploration, use it to inform judgments, continually adjust strategies based on feedback, and turn intermediate results into final deliverables. High-quality long-horizon trajectories capture these agentic behavioral patterns and their connections within a single problem-solving process, providing richer experience for sustained autonomous work. However, environment synthesis may complete or simplify the key work underlying these patterns in advance and thus remove the need for exploration, implementation, and verification that the agent was meant to perform. To address this, we introduce TerminalHorizon, a fully automated data synthesis engine for long-horizon terminal agents. Starting from real-world professional work, it uses independent execution to identify key work omitted during construction and uses the resulting evidence to guide environment reconstruction. To extend these patterns across stages, it progressively expands tasks under the same goal, introducing new requirements that build on prior results and call for further exploration and improvement. Using this engine, we construct 1.5K task environments and perform supervised fine-tuning of Qwen3.5-27B on the resulting dataset to obtain TerminalHorizon-27B. We achieve substantial performance gains on all 12 benchmarks spanning coding-agent tasks, agentic tasks in real-world production settings, and general reasoning. Multiple RSI case studies, each with a 12-hour research budget, further demonstrate the model's ability to continue experimenting beyond an initial solution, improve its methods based on feedback, and retain effective improvements in its final deliverables.", "upvotes": 31, "discussionId": "6acc50ce0ee6ff34004fde96", "projectPage": "https://zs1314.github.io/TerminalHorizon", "organization": {"_id": "68be41370a3fcebdcad6516a", "name": "alibabagroup", "fullname": "alibaba", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/68be3ab7e52df040b2cf80dc/li4G29u_EGswyTN1Sm_Kq.png"}, "summary_zh": "<ul>\n    <li>\u7ec8\u7aef\u4ee3\u7406\u6b63\u5728\u5411\u5b8c\u6210\u771f\u5b9e\u4e13\u4e1a\u4efb\u52a1\u53d1\u5c55\uff0c\u800c\u4e0d\u4ec5\u9650\u4e8e\u672c\u5730\u64cd\u4f5c\u3002</li>\n    <li>\u77ed\u671f\u8f68\u8ff9\u65e0\u6cd5\u5145\u5206\u5c55\u793a\u4ee3\u7406\u5982\u4f55\u901a\u8fc7\u63a2\u7d22\u79ef\u7d2f\u8bc1\u636e\u3001\u8c03\u6574\u7b56\u7565\u5e76\u8f6c\u5316\u4e2d\u95f4\u7ed3\u679c\u3002</li>\n    <li>TerminalHorizon\u662f\u4e00\u4e2a\u81ea\u52a8\u5316\u6570\u636e\u5408\u6210\u5f15\u64ce\uff0c\u65e8\u5728\u751f\u6210\u957f\u65f6\u95f4\u8303\u56f4\u7684\u4efb\u52a1\u73af\u5883\u3002</li>\n    <li>\u8be5\u5f15\u64ce\u901a\u8fc7\u72ec\u7acb\u6267\u884c\u8bc6\u522b\u5173\u952e\u5de5\u4f5c\uff0c\u5e76\u9010\u6b65\u6269\u5c55\u4efb\u52a1\u4ee5\u4fc3\u8fdb\u66f4\u6df1\u5165\u7684\u63a2\u7d22\u548c\u6539\u8fdb\u3002</li>\n    <li>\u4f7f\u7528TerminalHorizon\uff0c\u6784\u5efa\u4e861500\u4e2a\u4efb\u52a1\u73af\u5883\uff0c\u5e76\u5728\u591a\u4e2a\u57fa\u51c6\u6d4b\u8bd5\u4e2d\u663e\u8457\u63d0\u9ad8\u4e86\u6027\u80fd\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Terminal agents are evolving to handle complex real-world tasks beyond simple commands and tool usage.</li>\n    <li>Long-term task tracking is important for capturing how these agents gather evidence, adjust strategies, and produce final results.</li>\n    <li>Environment synthesis can sometimes oversimplify tasks, reducing the need for important exploration and verification by the agent.</li>\n    <li>TerminalHorizon is a new automated tool that helps create realistic long-term tasks for agents by identifying missing elements and guiding task development.</li>\n    <li>The use of TerminalHorizon significantly improved performance in various coding and reasoning tasks, showcasing the agent's ability to adapt and enhance its solutions over time.</li>\n</ul>"}, "publishedAt": "2026-10-08T20:00:00.000Z", "title": "Scaling Agentic Data for Long-Horizon Terminal Intelligence", "summary": "Terminal agents are moving beyond local operations toward completing real-world professional tasks. Short trajectories can demonstrate commands and tool calls, but they do not fully show how agents accumulate evidence through exploration, use it to inform judgments, continually adjust strategies based on feedback, and turn intermediate results into final deliverables. High-quality long-horizon trajectories capture these agentic behavioral patterns and their connections within a single problem-solving process, providing richer experience for sustained autonomous work. However, environment synthesis may complete or simplify the key work underlying these patterns in advance and thus remove the need for exploration, implementation, and verification that the agent was meant to perform. To address this, we introduce TerminalHorizon, a fully automated data synthesis engine for long-horizon terminal agents. Starting from real-world professional work, it uses independent execution to identify key work omitted during construction and uses the resulting evidence to guide environment reconstruction. To extend these patterns across stages, it progressively expands tasks under the same goal, introducing new requirements that build on prior results and call for further exploration and improvement. Using this engine, we construct 1.5K task environments and perform supervised fine-tuning of Qwen3.5-27B on the resulting dataset to obtain TerminalHorizon-27B. We achieve substantial performance gains on all 12 benchmarks spanning coding-agent tasks, agentic tasks in real-world production settings, and general reasoning. Multiple RSI case studies, each with a 12-hour research budget, further demonstrate the model's ability to continue experimenting beyond an initial solution, improve its methods based on feedback, and retain effective improvements in its final deliverables.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.13166.png", "numComments": 1, "submittedBy": {"_id": "64d1dc5273174cecdffc97d3", "avatarUrl": "/avatars/6564e6b68fee9673f75b6366adf39a3b.svg", "fullname": "Wang Yong", "name": "seashell11", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 1, "isUserFollowing": false}, "organization": {"_id": "68be41370a3fcebdcad6516a", "name": "alibabagroup", "fullname": "alibaba", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/68be3ab7e52df040b2cf80dc/li4G29u_EGswyTN1Sm_Kq.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.13630", "authors": [{"_id": "6acd8959ead72e0d3c44fd25", "name": "Xiaohan Qin", "hidden": false}, {"_id": "6acd8959ead72e0d3c44fd26", "name": "Xiangdong Zhang", "hidden": false}, {"_id": "6acd8959ead72e0d3c44fd27", "name": "Tuo Dai", "hidden": false}, {"_id": "6acd8959ead72e0d3c44fd28", "name": "Sunan Zou", "hidden": false}, {"_id": "6acd8959ead72e0d3c44fd29", "name": "Huaijin Wu", "hidden": false}, {"_id": "6acd8959ead72e0d3c44fd2a", "name": "Yebin Yang", "hidden": false}, {"_id": "6acd8959ead72e0d3c44fd2b", "name": "Zhuo Xia", "hidden": false}, {"_id": "6acd8959ead72e0d3c44fd2c", "name": "Lin Yao", "hidden": false}, {"_id": "6acd8959ead72e0d3c44fd2d", "name": "Yuliang Liu", "hidden": false}, {"_id": "6acd8959ead72e0d3c44fd2e", "name": "Junchi Yan", "hidden": false}], "publishedAt": "2026-10-09T00:00:00.000Z", "submittedOnDailyAt": "2026-10-13T00:00:00.000Z", "title": "Multi-Stream Attention Residuals", "submittedOnDailyBy": {"_id": "64452110e1fd8d65b2790bfc", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/64452110e1fd8d65b2790bfc/3NIsQFV9X44X88aLXR6eE.jpeg", "isPro": false, "fullname": "Xiaohan Qin (SJTU) & (SII)", "user": "galaxy-1", "type": "user", "name": "galaxy-1"}, "summary": "Attention Residuals (AttnRes) enables content-dependent retrieval over network depth, which can be viewed as single-stream softmax attention along the depth axis. Inspired by the success of multi-head attention along the sequence axis, we introduce Multi-Stream Attention Residuals (MSAR), an extension of AttnRes that generalizes this mechanism to multi-head depth attention, yielding substantial performance gains with minimal additional overhead. MSAR draws stream diversity from sequence context through multi-scale causal convolutions, allowing different heads to retrieve historical representations through distinct contextual views while preserving the integrity of the hidden representation. The retrieved streams are combined through lightweight adaptive mixing to generate the single-stream layer input. By retaining single-stream sources and expanding them on demand, MSAR supports multi-stream computation without requiring persistent multi-stream storage or communication. Across all 12 downstream benchmarks at the 18B and 28B MoE scales, MSAR consistently outperforms prior residual variants, including standard residual connections, manifold-constrained Hyper-Connections (mHC), and AttnRes. Scaling-law experiments yield an iso-loss compute speedup of 1.58times over the standard residual baseline, compared with 1.35times for AttnRes and 1.30times for mHC. These results make MSAR a promising residual architecture for large-scale pre-training.", "upvotes": 30, "discussionId": "6acd8959ead72e0d3c44fd2f", "githubRepo": "https://github.com/jianke0604/MSAR", "githubRepoAddedBy": "user", "githubStars": 2, "organization": {"_id": "63e5ef7bf2e9a8f22c515654", "name": "SJTU", "fullname": "Shanghai Jiao Tong University", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/1676013394657-63e5ee22b6a40bf941da0928.png"}, "summary_zh": "<ul>\n    <li>Attention Residuals (AttnRes) \u5141\u8bb8\u6839\u636e\u5185\u5bb9\u5728\u7f51\u7edc\u6df1\u5ea6\u4e0a\u8fdb\u884c\u68c0\u7d22\uff0c\u7c7b\u4f3c\u4e8e\u6cbf\u6df1\u5ea6\u8f74\u7684\u5355\u6d41\u8f6f\u6700\u5927\u6ce8\u610f\u529b\u3002</li>\n    <li>\u591a\u6d41\u6ce8\u610f\u529b\u6b8b\u5dee\uff08MSAR\uff09\u662f\u5bf9 AttnRes \u7684\u6269\u5c55\uff0c\u589e\u5f3a\u4e86\u591a\u5934\u6df1\u5ea6\u6ce8\u610f\u529b\u7684\u673a\u5236\uff0c\u6027\u80fd\u63d0\u5347\u663e\u8457\uff0c\u989d\u5916\u5f00\u9500\u5f88\u5c0f\u3002</li>\n    <li>MSAR \u901a\u8fc7\u591a\u5c3a\u5ea6\u56e0\u679c\u5377\u79ef\u5f15\u5165\u6d41\u7684\u591a\u6837\u6027\uff0c\u4f7f\u4e0d\u540c\u7684\u5934\u80fd\u591f\u901a\u8fc7\u4e0d\u540c\u7684\u4e0a\u4e0b\u6587\u89c6\u89d2\u68c0\u7d22\u5386\u53f2\u8868\u793a\u3002</li>\n    <li>\u68c0\u7d22\u7684\u6d41\u901a\u8fc7\u8f7b\u91cf\u7ea7\u81ea\u9002\u5e94\u6df7\u5408\u7ec4\u5408\uff0c\u751f\u6210\u5355\u6d41\u5c42\u8f93\u5165\uff0c\u652f\u6301\u591a\u6d41\u8ba1\u7b97\u800c\u65e0\u9700\u6301\u7eed\u5b58\u50a8\u6216\u901a\u4fe1\u3002</li>\n    <li>\u5728\u6240\u6709 12 \u4e2a\u4e0b\u6e38\u57fa\u51c6\u6d4b\u8bd5\u4e2d\uff0cMSAR \u7684\u8868\u73b0\u4f18\u4e8e\u4e4b\u524d\u7684\u6b8b\u5dee\u53d8\u4f53\uff0c\u5e76\u5728\u8ba1\u7b97\u901f\u5ea6\u4e0a\u5b9e\u73b0\u4e86\u663e\u8457\u52a0\u901f\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Attention Residuals (AttnRes) allows for flexible data retrieval in neural networks by using a single-stream softmax attention method.</li>\n    <li>Multi-Stream Attention Residuals (MSAR) is an advanced version that improves on AttnRes by using multi-head attention for deeper network layers.</li>\n    <li>MSAR uses multi-scale causal convolutions to ensure different attention heads can access various historical data while maintaining the original data's integrity.</li>\n    <li>It combines these different data streams efficiently without needing extra storage or complex communication between them.</li>\n    <li>MSAR shows better performance on multiple benchmarks, offering faster computation speeds compared to other residual connection methods.</li>\n</ul>"}, "publishedAt": "2026-10-08T20:00:00.000Z", "title": "Multi-Stream Attention Residuals", "summary": "Attention Residuals (AttnRes) enables content-dependent retrieval over network depth, which can be viewed as single-stream softmax attention along the depth axis. Inspired by the success of multi-head attention along the sequence axis, we introduce Multi-Stream Attention Residuals (MSAR), an extension of AttnRes that generalizes this mechanism to multi-head depth attention, yielding substantial performance gains with minimal additional overhead. MSAR draws stream diversity from sequence context through multi-scale causal convolutions, allowing different heads to retrieve historical representations through distinct contextual views while preserving the integrity of the hidden representation. The retrieved streams are combined through lightweight adaptive mixing to generate the single-stream layer input. By retaining single-stream sources and expanding them on demand, MSAR supports multi-stream computation without requiring persistent multi-stream storage or communication. Across all 12 downstream benchmarks at the 18B and 28B MoE scales, MSAR consistently outperforms prior residual variants, including standard residual connections, manifold-constrained Hyper-Connections (mHC), and AttnRes. Scaling-law experiments yield an iso-loss compute speedup of 1.58times over the standard residual baseline, compared with 1.35times for AttnRes and 1.30times for mHC. These results make MSAR a promising residual architecture for large-scale pre-training.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.13630.png", "numComments": 1, "submittedBy": {"_id": "64452110e1fd8d65b2790bfc", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/64452110e1fd8d65b2790bfc/3NIsQFV9X44X88aLXR6eE.jpeg", "fullname": "Xiaohan Qin (SJTU) & (SII)", "name": "galaxy-1", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 3, "isUserFollowing": false}, "organization": {"_id": "63e5ef7bf2e9a8f22c515654", "name": "SJTU", "fullname": "Shanghai Jiao Tong University", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/1676013394657-63e5ee22b6a40bf941da0928.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.13361", "authors": [{"_id": "6accd8fa0ee6ff34004fe25c", "name": "Jiahao Wang", "hidden": false}, {"_id": "6accd8fa0ee6ff34004fe25d", "name": "Hongjin Qian", "hidden": false}, {"_id": "6accd8fa0ee6ff34004fe25e", "name": "Yuyang Hu", "hidden": false}, {"_id": "6accd8fa0ee6ff34004fe25f", "name": "Jiajun Zhang", "hidden": false}, {"_id": "6accd8fa0ee6ff34004fe260", "name": "Zheng Liu", "hidden": false}], "publishedAt": "2026-10-09T00:00:00.000Z", "submittedOnDailyAt": "2026-10-13T00:00:00.000Z", "title": "AgentSWE: Can Coding Agents Build the Agent You Actually Want?", "submittedOnDailyBy": {"_id": "64a627232944e255ef574dda", "avatarUrl": "/avatars/4c2fd5bf922013fe691c6a3e3fa138a2.svg", "isPro": false, "fullname": "Hongjin Qian", "user": "TommyChien", "type": "user", "name": "TommyChien"}, "summary": "As the production of software passes into the hands of software itself, coding agents are increasingly commissioned to build agents fitted to their users' own workflows. This delegation carries a quiet assumption, that the delivered agent will faithfully serve the requirement it was built for, rather than merely appear to. No existing benchmark tests that assumption. We introduce AgentSWE, a benchmark for agent software engineering spanning three stages of the agent development lifecycle: Creation of a complete agent from a natural-language requirement, Editing of production agent codebases, and Optimization toward a measurable target. Each of its 25 tasks is framed as a commission rather than an exam: the builder iterates against a handful of illustrative cases, while acceptance exercises the frozen submission on held-out cases designed to span the full requirement, grading behavior against requirement-derived rubrics under hard pass/fail gates or, for Optimization, against the source benchmark's own objective. Evaluating a range of coding agents across models and harnesses, we find that none comes close to delivering what a requirement asks for: the gap between what a builder demonstrates and what it delivers is the norm, not the corner case. An accompanying empirical analysis of the failure trajectories identifies recurring failure modes, among them overfitting to the visible cases, hollow runtimes behind code that looks complete, and unsupported claims of completion, each a signal by which coding agents can learn to build the agents they are asked for.", "upvotes": 20, "discussionId": "6accd8fb0ee6ff34004fe261", "summary_zh": "<ul>\n    <li>\u8f6f\u4ef6\u5f00\u53d1\u9010\u6e10\u7531\u8f6f\u4ef6\u81ea\u5df1\u627f\u62c5\uff0c\u7f16\u7801\u4ee3\u7406\u88ab\u59d4\u6258\u6765\u6784\u5efa\u7b26\u5408\u7528\u6237\u5de5\u4f5c\u6d41\u7a0b\u7684\u4ee3\u7406\u3002</li>\n    <li>\u8fd9\u79cd\u59d4\u6258\u5047\u8bbe\u4ea4\u4ed8\u7684\u4ee3\u7406\u4f1a\u5fe0\u5b9e\u6ee1\u8db3\u9700\u6c42\uff0c\u4f46\u76ee\u524d\u6ca1\u6709\u6d4b\u8bd5\u8fd9\u79cd\u5047\u8bbe\u7684\u6807\u51c6\u3002</li>\n    <li>\u6211\u4eec\u63d0\u51fa\u4e86AgentSWE\uff0c\u4e00\u4e2a\u6db5\u76d6\u4ee3\u7406\u5f00\u53d1\u751f\u547d\u5468\u671f\u7684\u57fa\u51c6\uff0c\u5305\u542b\u4e09\u4e2a\u9636\u6bb5\uff1a\u4ece\u81ea\u7136\u8bed\u8a00\u9700\u6c42\u521b\u5efa\u5b8c\u6574\u4ee3\u7406\u3001\u7f16\u8f91\u73b0\u6709\u4ee3\u7406\u4ee3\u7801\u3001\u4ee5\u53ca\u4f18\u5316\u8fbe\u5230\u53ef\u8861\u91cf\u76ee\u6807\u3002</li>\n    <li>AgentSWE\u768425\u4e2a\u4efb\u52a1\u4ee5\u59d4\u6258\u7684\u5f62\u5f0f\u8fdb\u884c\uff0c\u4e0d\u662f\u8003\u8bd5\uff0c\u8bc4\u4f30\u57fa\u4e8e\u9700\u6c42\u7684\u6807\u51c6\u3002</li>\n    <li>\u5bf9\u591a\u79cd\u7f16\u7801\u4ee3\u7406\u7684\u8bc4\u4f30\u663e\u793a\uff0c\u5f53\u524d\u4ee3\u7406\u666e\u904d\u65e0\u6cd5\u6ee1\u8db3\u9700\u6c42\uff0c\u5e38\u89c1\u7684\u5931\u8d25\u6a21\u5f0f\u5305\u62ec\u8fc7\u62df\u5408\u3001\u4ee3\u7801\u8868\u9762\u5b8c\u6574\u4f46\u8fd0\u884c\u65f6\u4e3a\u7a7a\u3001\u4ee5\u53ca\u672a\u80fd\u5b8c\u6210\u7684\u58f0\u660e\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Software development is increasingly being done by automated coding agents designed to fit users' workflows.</li>\n    <li>There is an assumption that these agents will meet requirements accurately, but this assumption has not been tested.</li>\n    <li>AgentSWE is a new benchmark for evaluating the performance of coding agents through three development stages: creation, editing, and optimization.</li>\n    <li>The benchmark includes 25 tasks that assess an agent's ability to meet specified requirements through practical commissions rather than exams.</li>\n    <li>Results show that most coding agents fail to meet requirements, often overfitting to specific cases or making unsupported claims about their capabilities.</li>\n</ul>"}, "publishedAt": "2026-10-08T20:00:00.000Z", "title": "AgentSWE: Can Coding Agents Build the Agent You Actually Want?", "summary": "As the production of software passes into the hands of software itself, coding agents are increasingly commissioned to build agents fitted to their users' own workflows. This delegation carries a quiet assumption, that the delivered agent will faithfully serve the requirement it was built for, rather than merely appear to. No existing benchmark tests that assumption. We introduce AgentSWE, a benchmark for agent software engineering spanning three stages of the agent development lifecycle: Creation of a complete agent from a natural-language requirement, Editing of production agent codebases, and Optimization toward a measurable target. Each of its 25 tasks is framed as a commission rather than an exam: the builder iterates against a handful of illustrative cases, while acceptance exercises the frozen submission on held-out cases designed to span the full requirement, grading behavior against requirement-derived rubrics under hard pass/fail gates or, for Optimization, against the source benchmark's own objective. Evaluating a range of coding agents across models and harnesses, we find that none comes close to delivering what a requirement asks for: the gap between what a builder demonstrates and what it delivers is the norm, not the corner case. An accompanying empirical analysis of the failure trajectories identifies recurring failure modes, among them overfitting to the visible cases, hollow runtimes behind code that looks complete, and unsupported claims of completion, each a signal by which coding agents can learn to build the agents they are asked for.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.13361.png", "numComments": 1, "submittedBy": {"_id": "64a627232944e255ef574dda", "avatarUrl": "/avatars/4c2fd5bf922013fe691c6a3e3fa138a2.svg", "fullname": "Hongjin Qian", "name": "TommyChien", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 12, "isUserFollowing": false}, "isAuthorParticipating": false}, {"paper": {"id": "2610.13832", "authors": [{"_id": "6accc7a50ee6ff34004fe224", "name": "Yuhong Liu", "hidden": false}, {"_id": "6accc7a50ee6ff34004fe225", "name": "Shenxi Wu", "hidden": false}, {"_id": "6accc7a50ee6ff34004fe226", "name": "Junyi Chi", "hidden": false}, {"_id": "6accc7a50ee6ff34004fe227", "name": "Beichen Zhang", "hidden": false}, {"_id": "6accc7a50ee6ff34004fe228", "name": "Xuanlang Dai", "hidden": false}, {"_id": "6accc7a50ee6ff34004fe229", "name": "Jiaqi Wang", "hidden": false}, {"_id": "6accc7a50ee6ff34004fe22a", "name": "Yuhang Zang", "hidden": false}, {"_id": "6accc7a50ee6ff34004fe22b", "name": "Dahua Lin", "hidden": false}], "publishedAt": "2026-10-09T00:00:00.000Z", "submittedOnDailyAt": "2026-10-13T00:00:00.000Z", "title": "SpatialASM: Internalizing Active Mentalization for Spatial Reasoning", "submittedOnDailyBy": {"_id": "6732e5afac0998d059757678", "avatarUrl": "/avatars/6e2ca76a6e94cfa7e2f16733118706a9.svg", "isPro": false, "fullname": "Yuhong Liu", "user": "YuhongLiu", "type": "user", "name": "YuhongLiu"}, "summary": "When solving complex spatial reasoning tasks, ordinary humans naturally revisit the scenes from task-relevant viewpoints and mentally reconstruct the spatial layouts from those viewpoints. But can Large Vision-Language Models (LVLMs) proactively think in the same way? We term this ability Active Spatial Mentalization (ASM), an intrinsic component of visual intelligence that remains substantially underdeveloped in current LVLMs. To bridge this gap, we introduce SpatialASM, a scalable framework to internalize ASM into LVLMs through training-time spatial simulation. SpatialASM employs an allocentric novel-view generator to ground hypothetical viewpoints in visual evidence and produces two complementary forms of supervision: i) explicit ASM trajectories that teach LVLMs when and how to adaptively invoke view planning and imagination during spatial reasoning, and ii) automatically-constructed perspective-taking tasks that further strengthens viewpoint-conditioned scene imagination. On seven benchmarks spanning relatively perception-oriented spatial understanding to more challenging tasks requiring multi-image, cross-view and viewpoint-transformation reasoning, SpatialASM yields performance gain on LVLMs of four LVLM backbones in spatial reasoning while retaining their original general vision capabilities. The experimental results demonstrate that our approach improves average accuracy across the seven spatial benchmarks. And the synthesis of ASM trajectories provides a scalable pathway to alleviate the scarcity of spatial Chain-of-Thought (CoT) supervision for eliciting active viewpoint exploration and mental scene simulation.", "upvotes": 13, "discussionId": "6accc7a50ee6ff34004fe22c", "githubRepo": "https://github.com/InternLM/SpatialASM", "githubRepoAddedBy": "user", "githubStars": 1, "organization": {"_id": "6a4fb75a1c66dbf208e7ddb6", "name": "Shanghai-AI-Laboratory", "fullname": "Shanghai AI Laboratory", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/65cd955637be1841d0b75397/Rao_Kq6NMtTVfSqLUIR4k.webp"}, "summary_zh": "<ul>\n    <li>\u666e\u901a\u4eba\u5728\u89e3\u51b3\u590d\u6742\u7a7a\u95f4\u63a8\u7406\u4efb\u52a1\u65f6\uff0c\u4f1a\u4ece\u76f8\u5173\u89c6\u89d2\u91cd\u65b0\u5ba1\u89c6\u573a\u666f\u5e76\u8fdb\u884c\u7a7a\u95f4\u5e03\u5c40\u7684\u5fc3\u7406\u91cd\u5efa\u3002</li>\n    <li>\u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u79cd\u53eb\u505a\u4e3b\u52a8\u7a7a\u95f4\u5fc3\u7406\u5316\uff08ASM\uff09\u7684\u80fd\u529b\uff0c\u8fd9\u5728\u5f53\u524d\u7684\u5927\u578b\u89c6\u89c9-\u8bed\u8a00\u6a21\u578b\uff08LVLMs\uff09\u4e2d\u5c1a\u672a\u5f97\u5230\u5145\u5206\u53d1\u5c55\u3002</li>\n    <li>\u4e3a\u4e86\u89e3\u51b3\u8fd9\u4e00\u95ee\u9898\uff0c\u6211\u4eec\u5f15\u5165\u4e86SpatialASM\u6846\u67b6\uff0c\u901a\u8fc7\u8bad\u7ec3\u65f6\u7684\u7a7a\u95f4\u6a21\u62df\u5c06ASM\u5185\u5316\u5230LVLM\u4e2d\u3002</li>\n    <li>SpatialASM\u4f7f\u7528\u4e00\u79cd\u65b0\u9896\u7684\u89c6\u89d2\u751f\u6210\u5668\uff0c\u5e76\u63d0\u4f9b\u4e24\u79cd\u76d1\u7763\u5f62\u5f0f\uff0c\u5e2e\u52a9LVLM\u5728\u7a7a\u95f4\u63a8\u7406\u4e2d\u66f4\u597d\u5730\u89c4\u5212\u548c\u60f3\u8c61\u89c6\u89d2\u3002</li>\n    <li>\u5728\u4e03\u4e2a\u57fa\u51c6\u6d4b\u8bd5\u4e2d\uff0cSpatialASM\u663e\u8457\u63d0\u9ad8\u4e86LVLM\u5728\u7a7a\u95f4\u63a8\u7406\u65b9\u9762\u7684\u8868\u73b0\uff0c\u540c\u65f6\u4fdd\u6301\u4e86\u5176\u539f\u6709\u7684\u89c6\u89c9\u80fd\u529b\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Humans use different viewpoints to understand complex spatial tasks, but current Large Vision-Language Models (LVLMs) struggle with this ability.</li>\n    <li>The study introduces a new method called SpatialASM to help LVLMs better understand spatial reasoning by simulating different viewpoints during training.</li>\n    <li>SpatialASM provides two types of learning: one teaches LVLMs how to plan views and imagine scenes, and the other creates tasks that improve their ability to take different perspectives.</li>\n    <li>The approach improves the performance of LVLMs on various spatial reasoning tests while keeping their general vision skills intact.</li>\n    <li>Overall, SpatialASM helps LVLMs think more like humans when it comes to understanding spatial layouts and improves their accuracy in multiple benchmarks.</li>\n</ul>"}, "publishedAt": "2026-10-08T20:00:00.000Z", "title": "SpatialASM: Internalizing Active Mentalization for Spatial Reasoning", "summary": "When solving complex spatial reasoning tasks, ordinary humans naturally revisit the scenes from task-relevant viewpoints and mentally reconstruct the spatial layouts from those viewpoints. But can Large Vision-Language Models (LVLMs) proactively think in the same way? We term this ability Active Spatial Mentalization (ASM), an intrinsic component of visual intelligence that remains substantially underdeveloped in current LVLMs. To bridge this gap, we introduce SpatialASM, a scalable framework to internalize ASM into LVLMs through training-time spatial simulation. SpatialASM employs an allocentric novel-view generator to ground hypothetical viewpoints in visual evidence and produces two complementary forms of supervision: i) explicit ASM trajectories that teach LVLMs when and how to adaptively invoke view planning and imagination during spatial reasoning, and ii) automatically-constructed perspective-taking tasks that further strengthens viewpoint-conditioned scene imagination. On seven benchmarks spanning relatively perception-oriented spatial understanding to more challenging tasks requiring multi-image, cross-view and viewpoint-transformation reasoning, SpatialASM yields performance gain on LVLMs of four LVLM backbones in spatial reasoning while retaining their original general vision capabilities. The experimental results demonstrate that our approach improves average accuracy across the seven spatial benchmarks. And the synthesis of ASM trajectories provides a scalable pathway to alleviate the scarcity of spatial Chain-of-Thought (CoT) supervision for eliciting active viewpoint exploration and mental scene simulation.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.13832.png", "numComments": 1, "submittedBy": {"_id": "6732e5afac0998d059757678", "avatarUrl": "/avatars/6e2ca76a6e94cfa7e2f16733118706a9.svg", "fullname": "Yuhong Liu", "name": "YuhongLiu", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "isUserFollowing": false}, "organization": {"_id": "6a4fb75a1c66dbf208e7ddb6", "name": "Shanghai-AI-Laboratory", "fullname": "Shanghai AI Laboratory", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/65cd955637be1841d0b75397/Rao_Kq6NMtTVfSqLUIR4k.webp"}, "isAuthorParticipating": false}, {"paper": {"id": "2609.39600", "authors": [{"_id": "6abf173c5ff0ac8de3b84ad0", "name": "Qize Yu", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84ad1", "name": "Lianrui Fan", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84ad2", "name": "Bowen Ping", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84ad3", "name": "Xini Ding", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84ad4", "name": "Zetian Song", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84ad5", "name": "Junbo Niu", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84ad6", "name": "Kaixuan Wang", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84ad7", "name": "Tianxing Chen", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84ad8", "name": "Yue Chen", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84ad9", "name": "Minghua He", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84ada", "name": "Yuran Wang", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84adb", "name": "Jie Huang", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84adc", "name": "Haojun Zhang", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84add", "name": "Min Chen", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84ade", "name": "Hao Li", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84adf", "name": "Wenxuan Song", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84ae0", "name": "Ruihai Wu", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84ae1", "name": "Xianming Liu", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84ae2", "name": "Shilong Liu", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84ae3", "name": "Shuchang Zhou", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84ae4", "name": "Ping Luo", "hidden": false}, {"_id": "6abf173c5ff0ac8de3b84ae5", "name": "Shiyu Huang", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/692fa5d17ff1da99eb783dfb/u2VM5EugKlW701Fw5br4X.mp4", "https://cdn-uploads.huggingface.co/production/uploads/692fa5d17ff1da99eb783dfb/yUmClbmSwlAruTfoDlN3Q.jpeg"], "publishedAt": "2026-09-30T00:00:00.000Z", "submittedOnDailyAt": "2026-10-13T00:00:00.000Z", "title": "GroundAnything: Reconciling Parallel Decoding with Precise Visual Grounding at Flash Speed", "submittedOnDailyBy": {"_id": "692fa5d17ff1da99eb783dfb", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/692fa5d17ff1da99eb783dfb/GZ2TD9ua-pigxz5kEHRYX.jpeg", "isPro": false, "fullname": "Qize Yu", "user": "Skywalker0410", "type": "user", "name": "Skywalker0410"}, "summary": "Autoregressive (AR) grounding models serialize spatial predictions, introducing sequential latency and imposing a causal order on output tokens. We view grounding as visual evidence extraction: objects, locations, and spatial relations are jointly constrained by the image and query, yet their dependencies do not imply an intrinsic left-to-right generation order. This distinction makes bidirectional diffusion a natural fit, allowing spatial hypotheses to emerge in parallel and be jointly refined through iterative denoising. We introduce GroundAnything, a 4B-parameter grounding foundation model that reconciles fast parallel decoding with precise localization through blockwise denoising. Training combines grounding pretraining from public datasets and dedicated data engines, direct AR-to-diffusion conversion with joint AR and diffusion objectives, supervised fine-tuning, and GRPO-based reinforcement post-training. Across 30 grounding benchmarks, our autoregressive variant, GroundAnything-VLM, establishes a new overall state of the art among similarly sized models at 72.42%, remaining competitive with GPT-6 Astra (71.35%). With entropy-guided decoding, GroundAnything also surpasses the prior state of the art at this scale, averaging 61.75% versus 53.32% for the fast MTP-based LocateAnything model. We further explore decoding strategies, showing that an optional self-speculative mode achieves a 4.51times speedup over the AR counterpart with a 0.74 percentage-point drop in COCO F1mIoU. Infrastructure experiments show that progressive inference optimizations translate parallel decoding into practical speedups. These support efficient visual grounding in latency-sensitive real-world systems.", "upvotes": 12, "discussionId": "6abf173d5ff0ac8de3b84ae9", "projectPage": "https://groundingpi.github.io/groundanything/", "githubRepo": "https://github.com/groundingpi/GroundAnything", "githubRepoAddedBy": "user", "githubStars": 20, "organization": {"_id": "6aa24a85fc727b9188a95572", "name": "XPENG-AI", "fullname": "XPENG AI", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/6406db5cd684369027166986/DAJtDU_HssW_R7WIw0USp.jpeg"}, "summary_zh": "<ul>\n    <li>\u63d0\u51fa\u4e86\u4e00\u79cd\u540d\u4e3aGroundAnything\u76844B\u53c2\u6570\u57fa\u7840\u6a21\u578b\uff0c\u7528\u4e8e\u7a7a\u95f4\u9884\u6d4b\u548c\u89c6\u89c9\u8bc1\u636e\u63d0\u53d6\u3002</li>\n    <li>\u8be5\u6a21\u578b\u7ed3\u5408\u4e86\u5feb\u901f\u5e76\u884c\u89e3\u7801\u548c\u7cbe\u786e\u5b9a\u4f4d\uff0c\u901a\u8fc7\u9010\u5757\u53bb\u566a\u5b9e\u73b0\u3002</li>\n    <li>\u572830\u4e2a\u57fa\u51c6\u6d4b\u8bd5\u4e2d\uff0cGroundAnything-VLM\u5728\u540c\u7c7b\u6a21\u578b\u4e2d\u8bbe\u7acb\u4e86\u65b0\u7684\u6700\u4f73\u6027\u80fd\uff0c\u8fbe\u523072.42%\u3002</li>\n    <li>\u91c7\u7528\u71b5\u5f15\u5bfc\u89e3\u7801\u7684GroundAnything\u6a21\u578b\u5728\u901f\u5ea6\u4e0a\u8d85\u8d8a\u4e86\u4e4b\u524d\u7684\u6700\u4f73\u6a21\u578b\u3002</li>\n    <li>\u57fa\u7840\u8bbe\u65bd\u5b9e\u9a8c\u8868\u660e\uff0c\u6e10\u8fdb\u63a8\u7406\u4f18\u5316\u53ef\u4ee5\u6709\u6548\u63d0\u5347\u5e76\u884c\u89e3\u7801\u7684\u901f\u5ea6\uff0c\u9002\u7528\u4e8e\u9700\u8981\u4f4e\u5ef6\u8fdf\u7684\u5b9e\u9645\u5e94\u7528\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Grounding models typically generate predictions in a sequence, causing delays and a fixed order for outputs.</li>\n    <li>The authors propose viewing grounding as extracting visual evidence, allowing for more flexible and parallel predictions.</li>\n    <li>They introduce GroundAnything, a new model that improves speed and accuracy in visual grounding by using advanced techniques like blockwise denoising.</li>\n    <li>GroundAnything achieves state-of-the-art performance on various benchmarks, outperforming similar models.</li>\n    <li>The model includes innovative decoding strategies that significantly speed up processing while maintaining high accuracy.</li>\n</ul>"}, "publishedAt": "2026-09-29T20:00:00.000Z", "title": "GroundAnything: Reconciling Parallel Decoding with Precise Visual Grounding at Flash Speed", "summary": "Autoregressive (AR) grounding models serialize spatial predictions, introducing sequential latency and imposing a causal order on output tokens. We view grounding as visual evidence extraction: objects, locations, and spatial relations are jointly constrained by the image and query, yet their dependencies do not imply an intrinsic left-to-right generation order. This distinction makes bidirectional diffusion a natural fit, allowing spatial hypotheses to emerge in parallel and be jointly refined through iterative denoising. We introduce GroundAnything, a 4B-parameter grounding foundation model that reconciles fast parallel decoding with precise localization through blockwise denoising. Training combines grounding pretraining from public datasets and dedicated data engines, direct AR-to-diffusion conversion with joint AR and diffusion objectives, supervised fine-tuning, and GRPO-based reinforcement post-training. Across 30 grounding benchmarks, our autoregressive variant, GroundAnything-VLM, establishes a new overall state of the art among similarly sized models at 72.42%, remaining competitive with GPT-6 Astra (71.35%). With entropy-guided decoding, GroundAnything also surpasses the prior state of the art at this scale, averaging 61.75% versus 53.32% for the fast MTP-based LocateAnything model. We further explore decoding strategies, showing that an optional self-speculative mode achieves a 4.51times speedup over the AR counterpart with a 0.74 percentage-point drop in COCO F1mIoU. Infrastructure experiments show that progressive inference optimizations translate parallel decoding into practical speedups. These support efficient visual grounding in latency-sensitive real-world systems.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/692fa5d17ff1da99eb783dfb/u2VM5EugKlW701Fw5br4X.mp4", "https://cdn-uploads.huggingface.co/production/uploads/692fa5d17ff1da99eb783dfb/yUmClbmSwlAruTfoDlN3Q.jpeg"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2609.39600.png", "numComments": 1, "submittedBy": {"_id": "692fa5d17ff1da99eb783dfb", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/692fa5d17ff1da99eb783dfb/GZ2TD9ua-pigxz5kEHRYX.jpeg", "fullname": "Qize Yu", "name": "Skywalker0410", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 5, "isUserFollowing": false}, "organization": {"_id": "6aa24a85fc727b9188a95572", "name": "XPENG-AI", "fullname": "XPENG AI", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/6406db5cd684369027166986/DAJtDU_HssW_R7WIw0USp.jpeg"}, "isAuthorParticipating": false}, {"paper": {"id": "2609.35965", "authors": [{"_id": "6accb30a0ee6ff34004fe118", "user": {"_id": "61875e14a7717cb375090c0e", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/61875e14a7717cb375090c0e/9m-j8ZTpcy4IKgE0GvsJ1.jpeg", "isPro": false, "fullname": "Yunzhe Xu", "user": "xyz9911", "type": "user", "name": "xyz9911"}, "name": "Yunzhe Xu", "status": "claimed_verified", "statusLastChangedAt": "2026-10-12T15:48:09.527Z", "hidden": false}, {"_id": "6accb30a0ee6ff34004fe119", "name": "Zhe Liu", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/61875e14a7717cb375090c0e/spgC7dAZBlWgvsjLzwfVj.mp4"], "publishedAt": "2026-10-07T00:00:00.000Z", "submittedOnDailyAt": "2026-10-13T00:00:00.000Z", "title": "Systematic Multi-Agent Vision-and-Language Navigation: Formulation, Benchmark, and Method", "submittedOnDailyBy": {"_id": "61875e14a7717cb375090c0e", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/61875e14a7717cb375090c0e/9m-j8ZTpcy4IKgE0GvsJ1.jpeg", "isPro": false, "fullname": "Yunzhe Xu", "user": "xyz9911", "type": "user", "name": "xyz9911"}, "summary": "Vision-and-Language Navigation (VLN) has largely focused on a single agent following a single instruction, yet many real-world applications require teams of robots to tackle tasks beyond the capabilities of any individual agent. We present Systematic Multi-Agent Vision-and-Language Navigation, providing, to our knowledge, the first systematic formalization of multi-agent VLN as a constrained coordination problem: each mission consists of subtasks carrying dependency and resource constraints (presence locks and holding chains). A verified four-stage crafting pipeline instantiates the task as MAVLN, comprising 11,724 episodes across 145 scenes with teams of up to four agents under three instruction regimes, accompanied by tailored constraint-aware metrics. We further present TRISS, a coordination-ready navigation system coupling an LLM-based subtask scheduler, a shared topological memory that turns each agent's exploration into team knowledge, and a conflict-aware execution mechanism that realizes simultaneous intentions as collision-free routes. Extensive experiments establish TRISS as a comprehensive baseline and reveal substantial room for improvement across scheduling, planning, and execution, highlighting the challenges of coordinating under MAVLN task constraints. Project page: https://xyz9911.github.io/mavln.", "upvotes": 9, "discussionId": "6accb30b0ee6ff34004fe11a", "projectPage": "https://xyz9911.github.io/mavln/", "githubRepo": "https://github.com/xyz9911/MA-VLN", "githubRepoAddedBy": "user", "githubStars": 5, "organization": {"_id": "63e5ef7bf2e9a8f22c515654", "name": "SJTU", "fullname": "Shanghai Jiao Tong University", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/1676013394657-63e5ee22b6a40bf941da0928.png"}, "summary_zh": "<ul>\n    <li>\u591a\u667a\u80fd\u4f53\u89c6\u89c9\u4e0e\u8bed\u8a00\u5bfc\u822a\uff08VLN\uff09\u5173\u6ce8\u591a\u4e2a\u673a\u5668\u4eba\u534f\u540c\u5b8c\u6210\u4efb\u52a1\uff0c\u800c\u4e0d\u662f\u5355\u4e2a\u667a\u80fd\u4f53\u3002</li>\n    <li>\u63d0\u51fa\u4e86\u4e00\u79cd\u7cfb\u7edf\u5316\u7684\u591a\u667a\u80fd\u4f53VLN\u65b9\u6cd5\uff0c\u5c06\u5176\u5f62\u5f0f\u5316\u4e3a\u4e00\u4e2a\u53d7\u7ea6\u675f\u7684\u534f\u8c03\u95ee\u9898\u3002</li>\n    <li>\u7814\u7a76\u4e2d\u5305\u542b11724\u4e2a\u6848\u4f8b\uff0c\u6d89\u53ca145\u4e2a\u573a\u666f\u548c\u6700\u591a\u56db\u4e2a\u667a\u80fd\u4f53\u7684\u56e2\u961f\u3002</li>\n    <li>\u5f00\u53d1\u4e86TRISS\u7cfb\u7edf\uff0c\u7ed3\u5408\u4e86\u5b50\u4efb\u52a1\u8c03\u5ea6\u3001\u5171\u4eab\u8bb0\u5fc6\u548c\u51b2\u7a81\u611f\u77e5\u6267\u884c\u673a\u5236\u3002</li>\n    <li>\u5b9e\u9a8c\u8868\u660eTRISS\u662f\u4e00\u4e2a\u5168\u9762\u7684\u57fa\u51c6\uff0c\u663e\u793a\u5728\u8c03\u5ea6\u3001\u89c4\u5212\u548c\u6267\u884c\u65b9\u9762\u8fd8\u6709\u5f88\u5927\u7684\u6539\u8fdb\u7a7a\u95f4\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Vision-and-Language Navigation (VLN) has mostly focused on single agents, but many tasks need teams of robots.</li>\n    <li>The study introduces a new approach called Systematic Multi-Agent Vision-and-Language Navigation (MAVLN) that organizes tasks into subtasks with specific dependencies and constraints.</li>\n    <li>A new system named TRISS helps coordinate these agents, using a subtask scheduler, shared memory, and a way to avoid conflicts during navigation.</li>\n    <li>Experiments show that TRISS is a strong starting point for multi-agent navigation but also highlights areas for improvement.</li>\n    <li>The project includes a large dataset with 11,724 episodes and provides a webpage for more information.</li>\n</ul>"}, "publishedAt": "2026-10-06T20:00:00.000Z", "title": "Systematic Multi-Agent Vision-and-Language Navigation: Formulation, Benchmark, and Method", "summary": "Vision-and-Language Navigation (VLN) has largely focused on a single agent following a single instruction, yet many real-world applications require teams of robots to tackle tasks beyond the capabilities of any individual agent. We present Systematic Multi-Agent Vision-and-Language Navigation, providing, to our knowledge, the first systematic formalization of multi-agent VLN as a constrained coordination problem: each mission consists of subtasks carrying dependency and resource constraints (presence locks and holding chains). A verified four-stage crafting pipeline instantiates the task as MAVLN, comprising 11,724 episodes across 145 scenes with teams of up to four agents under three instruction regimes, accompanied by tailored constraint-aware metrics. We further present TRISS, a coordination-ready navigation system coupling an LLM-based subtask scheduler, a shared topological memory that turns each agent's exploration into team knowledge, and a conflict-aware execution mechanism that realizes simultaneous intentions as collision-free routes. Extensive experiments establish TRISS as a comprehensive baseline and reveal substantial room for improvement across scheduling, planning, and execution, highlighting the challenges of coordinating under MAVLN task constraints. Project page: https://xyz9911.github.io/mavln.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/61875e14a7717cb375090c0e/spgC7dAZBlWgvsjLzwfVj.mp4"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2609.35965.png", "numComments": 1, "submittedBy": {"_id": "61875e14a7717cb375090c0e", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/61875e14a7717cb375090c0e/9m-j8ZTpcy4IKgE0GvsJ1.jpeg", "fullname": "Yunzhe Xu", "name": "xyz9911", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "isUserFollowing": false}, "organization": {"_id": "63e5ef7bf2e9a8f22c515654", "name": "SJTU", "fullname": "Shanghai Jiao Tong University", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/1676013394657-63e5ee22b6a40bf941da0928.png"}, "isAuthorParticipating": true}, {"paper": {"id": "2610.11765", "authors": [{"_id": "6acc51640ee6ff34004fde99", "user": {"_id": "68961040cd4db3f88477ba78", "avatarUrl": "/avatars/6a60246b35b885ad04da4b4c488ee68a.svg", "isPro": false, "fullname": "Dianqiao Lei", "user": "DianQiao", "type": "user", "name": "DianQiao"}, "name": "Dianqiao Lei", "status": "claimed_verified", "statusLastChangedAt": "2026-10-12T08:45:06.124Z", "hidden": false}, {"_id": "6acc51640ee6ff34004fde9a", "name": "Kevin Qinghong Lin", "hidden": false}, {"_id": "6acc51640ee6ff34004fde9b", "name": "Pan Lu", "hidden": false}, {"_id": "6acc51640ee6ff34004fde9c", "name": "Philip Torr", "hidden": false}, {"_id": "6acc51640ee6ff34004fde9d", "name": "James Zou", "hidden": false}], "publishedAt": "2026-10-08T00:00:00.000Z", "submittedOnDailyAt": "2026-10-13T00:00:00.000Z", "title": "Thinking Inertia: LLMs Keep Thinking When Told Not To", "submittedOnDailyBy": {"_id": "68961040cd4db3f88477ba78", "avatarUrl": "/avatars/6a60246b35b885ad04da4b4c488ee68a.svg", "isPro": false, "fullname": "Dianqiao Lei", "user": "DianQiao", "type": "user", "name": "DianQiao"}, "summary": "Large Language Models (LLMs) increasingly ship with explicit \"thinking modes\", yet their counterpart, \"no-thinking\", has received far less attention. We study LLMs' no-thinking behavior along two axes. a. How to measure no-thinking? Prior work typically defines no-thinking through proxies such as a disabled thinking mode or the absence of long traces. These proxies are unreliable: disabled thinking modes may still emit reasoning, while long traces may contain filler rather than genuine inference. We instead normalize each response into a pre-answer trace and final answer, and evaluate it at three levels: (i) Empty-Thinking Rate for strict answer-only compliance; (ii) instruction-aware Question-Pre-answer Relevance for similarity between the question and pre-answer trace; and (iii) LLM-as-judge Explicit Inference Rate for visible explicit inference. Together, these metrics distinguish answer-only output, relevant but non-inferential text, and explicit inference. b. How does no-thinking vary across tasks and models? We evaluate six prompting interventions on six LLMs across Boolean, multiple-choice, and open-ended questions. We find that explicit no-think controls cannot reliably eliminate visible inference. Models instead exhibit \"Thinking Inertia\": explicit inference persists even under strict controls and becomes more prevalent as the answer space opens. Accuracy remains stable on Boolean and multiple-choice tasks, whereas open-ended tasks reveal a trade-off between answer-only compliance and task accuracy. Rewriting the same questions across answer spaces shows that supplying candidate answers makes answer-only responses easier to produce. These findings establish no-thinking as a non-trivial capability: stopping explicit reasoning cannot be assumed from model settings or instructions alone and deserves systematic evaluation alongside reasoning ability.", "upvotes": 8, "discussionId": "6acc51650ee6ff34004fde9e", "projectPage": "https://thinking-inertia.github.io/", "githubRepo": "https://github.com/thinking-inertia/code", "githubRepoAddedBy": "user", "githubStars": 3, "organization": {"_id": "672c672dcf09d152f4da04c4", "name": "StanfordUniversity", "fullname": "Stanford University", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/68e396f2b5bb631e9b2fac9a/vJI0POlzGMXL2878t1vz2.jpeg"}, "summary_zh": "<ul>\n    <li>\u5927\u578b\u8bed\u8a00\u6a21\u578b\uff08LLMs\uff09\u6709\u660e\u786e\u7684\u201c\u601d\u8003\u6a21\u5f0f\u201d\uff0c\u4f46\u201c\u65e0\u601d\u8003\u201d\u6a21\u5f0f\u7684\u7814\u7a76\u8f83\u5c11\u3002</li>\n    <li>\u7814\u7a76\u901a\u8fc7\u4e09\u79cd\u6307\u6807\u8861\u91cf\u65e0\u601d\u8003\u884c\u4e3a\uff1a\u7a7a\u601d\u8003\u7387\u3001\u95ee\u9898-\u9884\u56de\u7b54\u76f8\u5173\u6027\u548c\u663e\u5f0f\u63a8\u7406\u7387\u3002</li>\n    <li>\u8bc4\u4f30\u516d\u79cd\u63d0\u793a\u5e72\u9884\u5728\u516d\u4e2aLLM\u4e0a\u7684\u8868\u73b0\uff0c\u53d1\u73b0\u65e0\u601d\u8003\u63a7\u5236\u4e0d\u80fd\u53ef\u9760\u6d88\u9664\u53ef\u89c1\u63a8\u7406\u3002</li>\n    <li>\u6a21\u578b\u8868\u73b0\u51fa\u201c\u601d\u7ef4\u60ef\u6027\u201d\uff0c\u5373\u5728\u4e25\u683c\u63a7\u5236\u4e0b\u4ecd\u4f1a\u51fa\u73b0\u663e\u5f0f\u63a8\u7406\uff0c\u4e14\u5728\u5f00\u653e\u5f0f\u4efb\u52a1\u4e2d\u66f4\u4e3a\u660e\u663e\u3002</li>\n    <li>\u65e0\u601d\u8003\u662f\u4e00\u79cd\u590d\u6742\u80fd\u529b\uff0c\u4e0d\u80fd\u4ec5\u901a\u8fc7\u6a21\u578b\u8bbe\u7f6e\u6216\u6307\u4ee4\u6765\u5047\u8bbe\uff0c\u503c\u5f97\u4e0e\u63a8\u7406\u80fd\u529b\u4e00\u8d77\u7cfb\u7edf\u8bc4\u4f30\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Large Language Models (LLMs) often have \"thinking modes,\" but less focus is on their \"no-thinking\" behavior.</li>\n    <li>The study introduces new ways to measure no-thinking, including checking for answer-only responses and relevance of pre-answers.</li>\n    <li>Research shows that no-thinking varies among tasks and models, with some still showing reasoning even when asked not to.</li>\n    <li>Explicit no-think controls do not completely remove reasoning, and reasoning tends to increase with more open-ended questions.</li>\n    <li>Providing answer choices helps models give simpler, answer-only responses, showing that no-thinking is a complex skill that needs careful evaluation.</li>\n</ul>"}, "publishedAt": "2026-10-07T20:00:00.000Z", "title": "Thinking Inertia: LLMs Keep Thinking When Told Not To", "summary": "Large Language Models (LLMs) increasingly ship with explicit \"thinking modes\", yet their counterpart, \"no-thinking\", has received far less attention. We study LLMs' no-thinking behavior along two axes. a. How to measure no-thinking? Prior work typically defines no-thinking through proxies such as a disabled thinking mode or the absence of long traces. These proxies are unreliable: disabled thinking modes may still emit reasoning, while long traces may contain filler rather than genuine inference. We instead normalize each response into a pre-answer trace and final answer, and evaluate it at three levels: (i) Empty-Thinking Rate for strict answer-only compliance; (ii) instruction-aware Question-Pre-answer Relevance for similarity between the question and pre-answer trace; and (iii) LLM-as-judge Explicit Inference Rate for visible explicit inference. Together, these metrics distinguish answer-only output, relevant but non-inferential text, and explicit inference. b. How does no-thinking vary across tasks and models? We evaluate six prompting interventions on six LLMs across Boolean, multiple-choice, and open-ended questions. We find that explicit no-think controls cannot reliably eliminate visible inference. Models instead exhibit \"Thinking Inertia\": explicit inference persists even under strict controls and becomes more prevalent as the answer space opens. Accuracy remains stable on Boolean and multiple-choice tasks, whereas open-ended tasks reveal a trade-off between answer-only compliance and task accuracy. Rewriting the same questions across answer spaces shows that supplying candidate answers makes answer-only responses easier to produce. These findings establish no-thinking as a non-trivial capability: stopping explicit reasoning cannot be assumed from model settings or instructions alone and deserves systematic evaluation alongside reasoning ability.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.11765.png", "numComments": 1, "submittedBy": {"_id": "68961040cd4db3f88477ba78", "avatarUrl": "/avatars/6a60246b35b885ad04da4b4c488ee68a.svg", "fullname": "Dianqiao Lei", "name": "DianQiao", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 2, "isUserFollowing": false}, "organization": {"_id": "672c672dcf09d152f4da04c4", "name": "StanfordUniversity", "fullname": "Stanford University", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/68e396f2b5bb631e9b2fac9a/vJI0POlzGMXL2878t1vz2.jpeg"}, "isAuthorParticipating": true}, {"paper": {"id": "2610.03308", "authors": [{"_id": "6ac8d1a6c4f21dbfd5982f3c", "user": {"_id": "66baccbfae3904951a909e9a", "avatarUrl": "/avatars/3a11fc0bf8fada0bbb02d4c0ee462ebb.svg", "isPro": false, "fullname": "atsuhiro noguchi", "user": "anogu", "type": "user", "name": "anogu"}, "name": "Atsuhiro Noguchi", "status": "claimed_verified", "statusLastChangedAt": "2026-10-09T13:19:45.825Z", "hidden": false}, {"_id": "6ac8d1a6c4f21dbfd5982f3d", "name": "Tianhan Xu", "hidden": false}, {"_id": "6ac8d1a6c4f21dbfd5982f3e", "name": "Yiming Liang", "hidden": false}, {"_id": "6ac8d1a6c4f21dbfd5982f3f", "name": "Yuta Kikuchi", "hidden": false}, {"_id": "6ac8d1a6c4f21dbfd5982f40", "name": "Masahiro Ishiyama", "hidden": false}, {"_id": "6ac8d1a6c4f21dbfd5982f41", "name": "Shintaro Takagi", "hidden": false}, {"_id": "6ac8d1a6c4f21dbfd5982f42", "name": "Hitoshi Murai", "hidden": false}, {"_id": "6ac8d1a6c4f21dbfd5982f43", "name": "Eiichi Matsumoto", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/66baccbfae3904951a909e9a/vBHbsHUpjBDqbFsaS4ceS.mp4"], "publishedAt": "2026-10-02T00:00:00.000Z", "submittedOnDailyAt": "2026-10-13T00:00:00.000Z", "title": "T3lescope: Arbitrary-Resolution High-Fidelity Generative Surface Reconstruction from Images", "submittedOnDailyBy": {"_id": "66baccbfae3904951a909e9a", "avatarUrl": "/avatars/3a11fc0bf8fada0bbb02d4c0ee462ebb.svg", "isPro": false, "fullname": "atsuhiro noguchi", "user": "anogu", "type": "user", "name": "anogu"}, "summary": "We reconstruct high-fidelity 3D scene meshes from posed multi-view images without per-scene optimization, across scales ranging from single objects to large outdoor scenes. Per-scene optimization methods lack the learned 3D prior needed when observations are sparse or surfaces are glossy or transparent. Existing generative methods leverage such priors to complete geometry in sparsely observed regions, but typically operate at a fixed resolution over a limited spatial extent, trading spatial coverage against detail. Reconstructing a large scene therefore often requires partitioning it into independently processed overlapping local regions, making it difficult to maintain global geometric consistency. To address these issues, we propose T3lescope, which applies a single fixed-resolution generator across scene scales in an inference-time coarse-to-fine cascade. A coarse level establishes the scene layout, and finer levels perturb and denoise geometry inherited from the coarser level within progressively finer spatial cells to recover surface detail. The model is trained on individual cells at multiple scales and shares its weights across all levels, so no hierarchy is fixed during training, and the number of levels, cell scales, and cell locations are determined at inference time. On indoor, outdoor, and city-scale scenes, T3lescope outperforms feed-forward and generative baselines, matches or surpasses per-scene optimization, and recovers fine structures as well as glossy and transparent surfaces. These results show that our method generalizes across diverse scenes, view counts, and image resolutions. Project page: https://pfnet-research.github.io/t3lescope/", "upvotes": 7, "discussionId": "6ac8d1a7c4f21dbfd5982f44", "projectPage": "https://pfnet-research.github.io/t3lescope/", "githubRepo": "https://github.com/pfnet-research/t3lescope", "githubRepoAddedBy": "user", "githubStars": 2, "organization": {"_id": "64c85a5a4515835c4d8603b0", "name": "pfnet", "fullname": "Preferred Networks, Inc.", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/6450a9625af3bded255f4a18/bpJ_gNonNHgiq-ycGFMWT.png"}, "summary_zh": "<ul>\n    <li>\u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u79cd\u540d\u4e3aT3lescope\u7684\u65b9\u6cd5\uff0c\u53ef\u4ee5\u4ece\u591a\u89c6\u89d2\u56fe\u50cf\u4e2d\u91cd\u5efa\u9ad8\u8d28\u91cf\u76843D\u573a\u666f\u7f51\u683c\uff0c\u9002\u7528\u4e8e\u4e0d\u540c\u89c4\u6a21\u7684\u573a\u666f\u3002</li>\n    <li>\u4f20\u7edf\u7684\u573a\u666f\u4f18\u5316\u65b9\u6cd5\u5728\u89c2\u5bdf\u7a00\u758f\u6216\u8868\u9762\u5149\u6ed1\u900f\u660e\u65f6\u6548\u679c\u4e0d\u4f73\uff0c\u800c\u6211\u4eec\u7684\u65b9\u6cd5\u80fd\u6709\u6548\u5904\u7406\u8fd9\u4e9b\u60c5\u51b5\u3002</li>\n    <li>T3lescope\u4f7f\u7528\u4e00\u4e2a\u56fa\u5b9a\u5206\u8fa8\u7387\u7684\u751f\u6210\u5668\uff0c\u901a\u8fc7\u7c97\u5230\u7ec6\u7684\u7ea7\u8054\u65b9\u5f0f\u8fdb\u884c\u63a8\u7406\uff0c\u9010\u6b65\u6062\u590d\u8868\u9762\u7ec6\u8282\u3002</li>\n    <li>\u8be5\u6a21\u578b\u5728\u591a\u4e2a\u5c3a\u5ea6\u7684\u72ec\u7acb\u5355\u5143\u4e0a\u8fdb\u884c\u8bad\u7ec3\uff0c\u4e14\u63a8\u7406\u65f6\u5404\u5c42\u7ea7\u5171\u4eab\u6743\u91cd\uff0c\u4e0d\u56fa\u5b9a\u5c42\u7ea7\u7ed3\u6784\u3002</li>\n    <li>\u5b9e\u9a8c\u7ed3\u679c\u8868\u660e\uff0cT3lescope\u5728\u5ba4\u5185\u3001\u5ba4\u5916\u548c\u57ce\u5e02\u89c4\u6a21\u7684\u573a\u666f\u4e2d\u8868\u73b0\u4f18\u4e8e\u73b0\u6709\u65b9\u6cd5\uff0c\u80fd\u591f\u6062\u590d\u7cbe\u7ec6\u7ed3\u6784\u548c\u5904\u7406\u5149\u6ed1\u3001\u900f\u660e\u8868\u9762\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>T3lescope reconstructs detailed 3D scenes from multiple images without needing specific adjustments for each scene.</li>\n    <li>It uses a single generator that works at different scales, improving scene layout and surface detail progressively.</li>\n    <li>The method is trained on small sections of scenes and adapts during use, allowing flexibility in processing.</li>\n    <li>T3lescope performs better than existing methods, maintaining high-quality results for various types of scenes and surfaces.</li>\n    <li>The approach shows strong generalization across different environments, views, and image qualities.</li>\n</ul>"}, "publishedAt": "2026-10-01T20:00:00.000Z", "title": "T3lescope: Arbitrary-Resolution High-Fidelity Generative Surface Reconstruction from Images", "summary": "We reconstruct high-fidelity 3D scene meshes from posed multi-view images without per-scene optimization, across scales ranging from single objects to large outdoor scenes. Per-scene optimization methods lack the learned 3D prior needed when observations are sparse or surfaces are glossy or transparent. Existing generative methods leverage such priors to complete geometry in sparsely observed regions, but typically operate at a fixed resolution over a limited spatial extent, trading spatial coverage against detail. Reconstructing a large scene therefore often requires partitioning it into independently processed overlapping local regions, making it difficult to maintain global geometric consistency. To address these issues, we propose T3lescope, which applies a single fixed-resolution generator across scene scales in an inference-time coarse-to-fine cascade. A coarse level establishes the scene layout, and finer levels perturb and denoise geometry inherited from the coarser level within progressively finer spatial cells to recover surface detail. The model is trained on individual cells at multiple scales and shares its weights across all levels, so no hierarchy is fixed during training, and the number of levels, cell scales, and cell locations are determined at inference time. On indoor, outdoor, and city-scale scenes, T3lescope outperforms feed-forward and generative baselines, matches or surpasses per-scene optimization, and recovers fine structures as well as glossy and transparent surfaces. These results show that our method generalizes across diverse scenes, view counts, and image resolutions. Project page: https://pfnet-research.github.io/t3lescope/", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/66baccbfae3904951a909e9a/vBHbsHUpjBDqbFsaS4ceS.mp4"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.03308.png", "numComments": 1, "submittedBy": {"_id": "66baccbfae3904951a909e9a", "avatarUrl": "/avatars/3a11fc0bf8fada0bbb02d4c0ee462ebb.svg", "fullname": "atsuhiro noguchi", "name": "anogu", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "isUserFollowing": false}, "organization": {"_id": "64c85a5a4515835c4d8603b0", "name": "pfnet", "fullname": "Preferred Networks, Inc.", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/6450a9625af3bded255f4a18/bpJ_gNonNHgiq-ycGFMWT.png"}, "isAuthorParticipating": true}, {"paper": {"id": "2610.09396", "authors": [{"_id": "6acd93a7ead72e0d3c44fd55", "name": "Yihao Hu", "hidden": false}, {"_id": "6acd93a7ead72e0d3c44fd56", "name": "Yanlin Feng", "hidden": false}, {"_id": "6acd93a7ead72e0d3c44fd57", "name": "Naoki Otani", "hidden": false}, {"_id": "6acd93a7ead72e0d3c44fd58", "name": "Nikita Bhutani", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/642f3e9ac953ca48ccd10927/F6S0UHbWPqd11mlDOA2G4.mp4"], "publishedAt": "2026-10-07T00:00:00.000Z", "submittedOnDailyAt": "2026-10-13T00:00:00.000Z", "title": "ARCS: Towards Precise Text-to-SQL via Structured Disambiguation", "submittedOnDailyBy": {"_id": "642f3e9ac953ca48ccd10927", "avatarUrl": "/avatars/eb6da3fce184aeb8cb9c2dfcd4235206.svg", "isPro": false, "fullname": "Yanlin Feng", "user": "yanlinf", "type": "user", "name": "yanlinf"}, "summary": "As text-to-SQL systems move beyond demonstrations toward real-world deployment, ambiguity in user questions becomes a primary source of errors. Such ambiguities are often subtle, domain- or data-specific, and can silently cause system outputs to deviate from the user's true intent. Ambiguity is traditionally addressed through conversational clarification, which is often inefficient, cognitively demanding, and poorly aligned with real-world user workflows. We propose structured disambiguation, a new paradigm in which ambiguity is resolved through explicit, constrained interactions rather than free-form dialogue. We construct ARCS (Ambiguity Resolution Corpus for SQL), the first text-to-SQL benchmark featuring naturally occurring, unconstrained ambiguities over real-world databases, with complete annotations of all valid ambiguity points, interpretations, and SQL queries. Experimental results show that text-to-SQL remains challenging in the presence of ambiguity: gpt-6-sol achieves only 51% end-to-end execution accuracy, and no open-source model exceeds 27%.", "upvotes": 3, "discussionId": "6acd93a8ead72e0d3c44fd59", "projectPage": "https://megagonlabs.github.io/tabulaflow/research/arcs/", "githubRepo": "https://github.com/megagonlabs/tabulaflow", "githubRepoAddedBy": "user", "githubStars": 5, "organization": {"_id": "6119fa21d3c7a4ea2d9c8b48", "name": "megagonlabs", "fullname": "Megagon Labs", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/1629092364615-6119f91344bc44eba1515e6b.png"}, "summary_zh": "<ul>\n    <li>\u6587\u672c\u5230SQL\u7cfb\u7edf\u5728\u5b9e\u9645\u5e94\u7528\u4e2d\uff0c\u7528\u6237\u95ee\u9898\u4e2d\u7684\u6a21\u7cca\u6027\u662f\u4e3b\u8981\u9519\u8bef\u6765\u6e90\u3002</li>\n    <li>\u6a21\u7cca\u6027\u901a\u5e38\u5f88\u5fae\u5999\uff0c\u4e0e\u7279\u5b9a\u9886\u57df\u6216\u6570\u636e\u76f8\u5173\uff0c\u53ef\u80fd\u5bfc\u81f4\u7cfb\u7edf\u8f93\u51fa\u504f\u79bb\u7528\u6237\u771f\u5b9e\u610f\u56fe\u3002</li>\n    <li>\u4f20\u7edf\u4e0a\u901a\u8fc7\u5bf9\u8bdd\u6f84\u6e05\u6a21\u7cca\u6027\uff0c\u4f46\u8fd9\u79cd\u65b9\u6cd5\u6548\u7387\u4f4e\u3001\u8ba4\u77e5\u8d1f\u62c5\u5927\uff0c\u4e0d\u7b26\u5408\u7528\u6237\u5b9e\u9645\u5de5\u4f5c\u6d41\u7a0b\u3002</li>\n    <li>\u6211\u4eec\u63d0\u51fa\u4e86\u201c\u7ed3\u6784\u5316\u6d88\u6b67\u201d\u7684\u65b0\u65b9\u6cd5\uff0c\u901a\u8fc7\u660e\u786e\u7684\u4e92\u52a8\u89e3\u51b3\u6a21\u7cca\u6027\uff0c\u800c\u4e0d\u662f\u81ea\u7531\u5bf9\u8bdd\u3002</li>\n    <li>\u6211\u4eec\u6784\u5efa\u4e86ARCS\uff08SQL\u6a21\u7cca\u6027\u89e3\u51b3\u8bed\u6599\u5e93\uff09\uff0c\u662f\u7b2c\u4e00\u4e2a\u5305\u542b\u771f\u5b9e\u6570\u636e\u5e93\u4e2d\u81ea\u7136\u53d1\u751f\u7684\u6a21\u7cca\u6027\u7684\u6587\u672c\u5230SQL\u57fa\u51c6\uff0c\u63d0\u4f9b\u4e86\u5b8c\u6574\u7684\u6a21\u7cca\u70b9\u3001\u89e3\u91ca\u548cSQL\u67e5\u8be2\u6ce8\u91ca\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Text-to-SQL systems often struggle with ambiguous user questions, leading to errors in understanding user intent.</li>\n    <li>Traditional methods to resolve ambiguity, like conversational clarification, can be inefficient and hard for users.</li>\n    <li>The authors propose a new method called structured disambiguation to handle ambiguity with clear, limited interactions.</li>\n    <li>They created a benchmark called ARCS that includes real-world examples of ambiguities in SQL queries, with detailed annotations.</li>\n    <li>Current models show low accuracy in handling ambiguous queries, with the best performing model achieving only 51% accuracy.</li>\n</ul>"}, "publishedAt": "2026-10-06T20:00:00.000Z", "title": "ARCS: Towards Precise Text-to-SQL via Structured Disambiguation", "summary": "As text-to-SQL systems move beyond demonstrations toward real-world deployment, ambiguity in user questions becomes a primary source of errors. Such ambiguities are often subtle, domain- or data-specific, and can silently cause system outputs to deviate from the user's true intent. Ambiguity is traditionally addressed through conversational clarification, which is often inefficient, cognitively demanding, and poorly aligned with real-world user workflows. We propose structured disambiguation, a new paradigm in which ambiguity is resolved through explicit, constrained interactions rather than free-form dialogue. We construct ARCS (Ambiguity Resolution Corpus for SQL), the first text-to-SQL benchmark featuring naturally occurring, unconstrained ambiguities over real-world databases, with complete annotations of all valid ambiguity points, interpretations, and SQL queries. Experimental results show that text-to-SQL remains challenging in the presence of ambiguity: gpt-6-sol achieves only 51% end-to-end execution accuracy, and no open-source model exceeds 27%.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/642f3e9ac953ca48ccd10927/F6S0UHbWPqd11mlDOA2G4.mp4"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.09396.png", "numComments": 1, "submittedBy": {"_id": "642f3e9ac953ca48ccd10927", "avatarUrl": "/avatars/eb6da3fce184aeb8cb9c2dfcd4235206.svg", "fullname": "Yanlin Feng", "name": "yanlinf", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 2, "isUserFollowing": false}, "organization": {"_id": "6119fa21d3c7a4ea2d9c8b48", "name": "megagonlabs", "fullname": "Megagon Labs", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/1629092364615-6119f91344bc44eba1515e6b.png"}, "isAuthorParticipating": false}],
    "week": [{"paper": {"id": "2610.10528", "authors": [{"_id": "6ac6fb044eb8005165aed391", "name": "Wei Huang", "hidden": false}, {"_id": "6ac6fb044eb8005165aed392", "name": "Bohan Zhang", "hidden": false}, {"_id": "6ac6fb044eb8005165aed393", "name": "Chenzhi Liu", "hidden": false}, {"_id": "6ac6fb044eb8005165aed394", "name": "Isabella Liu", "hidden": false}, {"_id": "6ac6fb044eb8005165aed395", "name": "Shuai Yang", "hidden": false}, {"_id": "6ac6fb044eb8005165aed396", "name": "Weian Mao", "hidden": false}, {"_id": "6ac6fb044eb8005165aed397", "name": "Luozhou Wang", "hidden": false}, {"_id": "6ac6fb044eb8005165aed398", "name": "Yicheng Xiao", "hidden": false}, {"_id": "6ac6fb044eb8005165aed399", "name": "Weifeng Lin", "hidden": false}, {"_id": "6ac6fb044eb8005165aed39a", "name": "Qixin Hu", "hidden": false}, {"_id": "6ac6fb044eb8005165aed39b", "name": "Bryan Chu", "hidden": false}, {"_id": "6ac6fb044eb8005165aed39c", "name": "Sifei Liu", "hidden": false}, {"_id": "6ac6fb044eb8005165aed39d", "name": "Linxi Fan", "hidden": false}, {"_id": "6ac6fb044eb8005165aed39e", "name": "Xiaojuan Qi", "hidden": false}, {"_id": "6ac6fb044eb8005165aed39f", "name": "Song Han", "hidden": false}, {"_id": "6ac6fb044eb8005165aed3a0", "name": "Yukang Chen", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/656db3f53dc1d277e5a64410/xydlSuXEJrwor5qFTZzvU.qt"], "publishedAt": "2026-10-07T00:00:00.000Z", "submittedOnDailyAt": "2026-10-08T00:00:00.000Z", "title": "Long-WAM: Scaling the Context of World-Action Models", "submittedOnDailyBy": {"_id": "656db3f53dc1d277e5a64410", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/656db3f53dc1d277e5a64410/9kiY2K3MCRcBDk7MrkTBK.png", "isPro": false, "fullname": "Wei Huang", "user": "AaronHuangWei", "type": "user", "name": "AaronHuangWei"}, "summary": "Real-time robot control demands enough visual history to infer motion and task progress, but processing that history can delay action. We present Long-WAM, a model-system framework for scaling the context of causal world-action models under real-time control constraints. Our central finding is that access to history is not the same as using it: longer histories pay off far more when the video foundation is pretrained autoregressively (AR). We first learn causal prediction from robot and egocentric videos without action labels, then preserve this history-to-future structure during world-action adaptation. On RoboCasa GR-1, increasing context from 0.0 to 19.2 seconds raises success from 63.3% to 78.7%, whereas a bidirectionally pretrained initialization shows no net gain; robot-domain AR pretraining further raises peak success on GR-1 and LIBERO-Long. Long-WAM also achieves the best results among compared methods on LIBERO-Long, RoboTwin 2.0, and DOMINO. Streaming observation encoding, asynchronous execution, and hardware-specific acceleration enable deployment on RTX 5090, DGX Spark, and Jetson AGX Thor without dropping future prediction; on RTX 5090, each action chunk, including future-video latent prediction, takes 107.4 ms. Real-time deployment on Unitree G1 and YAM supports dynamic and long-horizon manipulation, including 95% success on dynamic cup stacking, where Pi0.5 and Fast-WAM succeed in none of 20 trials. As a memory-informed executor, Long-WAM also complements higher-level planning in composite tasks.", "upvotes": 54, "discussionId": "6ac6fb044eb8005165aed3a1", "projectPage": "https://nvlabs.github.io/LongLive/Long-WAM/", "githubRepo": "https://github.com/NVlabs/LongLive", "githubRepoAddedBy": "user", "githubStars": 2662, "organization": {"_id": "60262b67268c201cdc8b7d43", "name": "nvidia", "fullname": "NVIDIA", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/65df9200dc3292a8983e5017/Vs5FPVCH-VZBipV3qKTuy.png"}, "summary_zh": "<ul>\n    <li>Long-WAM\u662f\u4e00\u4e2a\u7528\u4e8e\u5b9e\u65f6\u673a\u5668\u4eba\u63a7\u5236\u7684\u6a21\u578b\u7cfb\u7edf\u6846\u67b6\uff0c\u53ef\u4ee5\u5904\u7406\u8db3\u591f\u7684\u89c6\u89c9\u5386\u53f2\u4ee5\u63a8\u65ad\u8fd0\u52a8\u548c\u4efb\u52a1\u8fdb\u5c55\u3002</li>\n    <li>\u901a\u8fc7\u4f7f\u7528\u9884\u5148\u8bad\u7ec3\u7684\u81ea\u56de\u5f52\uff08AR\uff09\u89c6\u9891\u57fa\u7840\uff0c\u8f83\u957f\u7684\u5386\u53f2\u8bb0\u5f55\u80fd\u663e\u8457\u63d0\u9ad8\u6210\u529f\u7387\uff0c\u4ece63.3%\u63d0\u5347\u81f378.7%\u3002</li>\n    <li>\u5728\u591a\u4e2a\u673a\u5668\u4eba\u4efb\u52a1\u4e2d\uff0cLong-WAM\u7684\u8868\u73b0\u4f18\u4e8e\u5176\u4ed6\u65b9\u6cd5\uff0c\u5e76\u5728\u52a8\u6001\u676f\u5b50\u5806\u53e0\u4efb\u52a1\u4e2d\u5b9e\u73b0\u4e8695%\u7684\u6210\u529f\u7387\u3002</li>\n    <li>\u8be5\u7cfb\u7edf\u652f\u6301\u5728RTX 5090\u7b49\u786c\u4ef6\u4e0a\u5b9e\u65f6\u90e8\u7f72\uff0c\u80fd\u6709\u6548\u6267\u884c\u52a8\u6001\u548c\u957f\u671f\u64cd\u4f5c\u3002</li>\n    <li>Long-WAM\u4f5c\u4e3a\u4e00\u4e2a\u5185\u5b58\u9a71\u52a8\u7684\u6267\u884c\u5668\uff0c\u80fd\u591f\u4e0e\u66f4\u9ad8\u7ea7\u522b\u7684\u89c4\u5212\u76f8\u7ed3\u5408\uff0c\u63d0\u5347\u590d\u5408\u4efb\u52a1\u7684\u6267\u884c\u6548\u679c\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Long-WAM is a new system for controlling robots in real-time by effectively using visual history to improve motion and task progress.</li>\n    <li>Using longer visual histories is more beneficial when the video data is pre-trained in a specific way, which helps robots make better predictions.</li>\n    <li>Tests on a robot called RoboCasa GR-1 showed that increasing the visual history improved success rates from 63.3% to 78.7%.</li>\n    <li>Long-WAM achieved the best performance compared to other methods on various tasks, including dynamic cup stacking, where it had a 95% success rate.</li>\n    <li>The system is designed to work efficiently on advanced hardware without sacrificing performance, allowing for real-time actions and complex tasks.</li>\n</ul>"}, "publishedAt": "2026-10-06T20:00:00.000Z", "title": "Long-WAM: Scaling the Context of World-Action Models", "summary": "Real-time robot control demands enough visual history to infer motion and task progress, but processing that history can delay action. We present Long-WAM, a model-system framework for scaling the context of causal world-action models under real-time control constraints. Our central finding is that access to history is not the same as using it: longer histories pay off far more when the video foundation is pretrained autoregressively (AR). We first learn causal prediction from robot and egocentric videos without action labels, then preserve this history-to-future structure during world-action adaptation. On RoboCasa GR-1, increasing context from 0.0 to 19.2 seconds raises success from 63.3% to 78.7%, whereas a bidirectionally pretrained initialization shows no net gain; robot-domain AR pretraining further raises peak success on GR-1 and LIBERO-Long. Long-WAM also achieves the best results among compared methods on LIBERO-Long, RoboTwin 2.0, and DOMINO. Streaming observation encoding, asynchronous execution, and hardware-specific acceleration enable deployment on RTX 5090, DGX Spark, and Jetson AGX Thor without dropping future prediction; on RTX 5090, each action chunk, including future-video latent prediction, takes 107.4 ms. Real-time deployment on Unitree G1 and YAM supports dynamic and long-horizon manipulation, including 95% success on dynamic cup stacking, where Pi0.5 and Fast-WAM succeed in none of 20 trials. As a memory-informed executor, Long-WAM also complements higher-level planning in composite tasks.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/656db3f53dc1d277e5a64410/xydlSuXEJrwor5qFTZzvU.qt"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.10528.png", "numComments": 1, "submittedBy": {"_id": "656db3f53dc1d277e5a64410", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/656db3f53dc1d277e5a64410/9kiY2K3MCRcBDk7MrkTBK.png", "fullname": "Wei Huang", "name": "AaronHuangWei", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 19, "isUserFollowing": false}, "organization": {"_id": "60262b67268c201cdc8b7d43", "name": "nvidia", "fullname": "NVIDIA", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/65df9200dc3292a8983e5017/Vs5FPVCH-VZBipV3qKTuy.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.10524", "authors": [{"_id": "6ac6fef64eb8005165aed3e0", "name": "Jiyoung Kim", "hidden": false}, {"_id": "6ac6fef64eb8005165aed3e1", "name": "Paul Hyunbin Cho", "hidden": false}, {"_id": "6ac6fef64eb8005165aed3e2", "name": "Jisu Nam", "hidden": false}, {"_id": "6ac6fef64eb8005165aed3e3", "name": "Donghoon Lee", "hidden": false}, {"_id": "6ac6fef64eb8005165aed3e4", "name": "Hyunsung Go", "hidden": false}, {"_id": "6ac6fef64eb8005165aed3e5", "name": "Yeonkyeong Lee", "hidden": false}, {"_id": "6ac6fef64eb8005165aed3e6", "name": "Hansaem Kim", "hidden": false}, {"_id": "6ac6fef64eb8005165aed3e7", "name": "Seungryong Kim", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/65cb4ce4d5822659ec122119/vuLISuzr1b3izauYyA274.mp4"], "publishedAt": "2026-10-07T00:00:00.000Z", "submittedOnDailyAt": "2026-10-08T00:00:00.000Z", "title": "GRACE: Generation-aware latent compression for efficient video generation", "submittedOnDailyBy": {"_id": "65cb4ce4d5822659ec122119", "avatarUrl": "/avatars/b7e4b4c6914b32e097648dd5991dec26.svg", "isPro": true, "fullname": "jee0", "user": "chimaharicox", "type": "user", "name": "chimaharicox"}, "summary": "Highly compressed video autoencoders offer an effective way to accelerate video diffusion models, as the Diffusion Transformer (DiT) operates on far fewer tokens. However, such autoencoders are challenging to train, since a higher compression ratio degrades reconstruction quality and recovering it requires more channels, which is known to slow the convergence of the DiT. The compressed latent also differs from the one the DiT was trained on, so the pretrained DiT must be either retrained from scratch or adapted at considerable cost. Compressing the autoencoder the DiT was trained with appears to preserve compatibility, yet optimizing it for reconstruction alone still shifts the latent away from the distribution the DiT has learned. To address this, we propose Generation-Aware Latent Compression for Efficient Video Generation (GRACE), a two-stage framework that compresses a pretrained video autoencoder while keeping it compatible with the pretrained DiT. Specifically, we keep a frozen base latent from the pretrained encoder and learn a residual latent for the information lost under stronger compression, while aligning the compressed latent with the pretrained latent in the feature space of the frozen DiT so that the autoencoder is optimized for generation. We then adapt the DiT with lightweight fine-tuning and asymmetric denoising, where the base is denoised ahead of the residual. GRACE reduces the token count of Wan2.1-I2V-14B by 8x and its latency by 11.1x at 480x832x81, while matching the generation quality of the pretrained pipeline before compression on VBench.", "upvotes": 51, "discussionId": "6ac6fef64eb8005165aed3e8", "projectPage": "https://cvlab-kaist.github.io/GRACE/", "githubRepo": "https://github.com/cvlab-kaist/GRACE", "githubRepoAddedBy": "user", "githubStars": 12, "organization": {"_id": "6475760c33192631bad2bb38", "name": "kaist-ai", "fullname": "KAIST AI", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/6469949654873f0043b09c22/aaZFiyXe1qR-Dmy_xq67m.png"}, "summary_zh": "<ul>\n    <li>\u9ad8\u5ea6\u538b\u7f29\u7684\u89c6\u9891\u81ea\u7f16\u7801\u5668\u53ef\u4ee5\u52a0\u901f\u89c6\u9891\u6269\u6563\u6a21\u578b\uff0c\u4f46\u8bad\u7ec3\u56f0\u96be\u3002</li>\n    <li>\u66f4\u9ad8\u7684\u538b\u7f29\u6bd4\u4f1a\u964d\u4f4e\u91cd\u5efa\u8d28\u91cf\uff0c\u4e14\u9700\u8981\u66f4\u591a\u901a\u9053\uff0c\u8fd9\u4f1a\u51cf\u6162\u6a21\u578b\u6536\u655b\u3002</li>\n    <li>\u4e3a\u4e86\u4fdd\u6301\u517c\u5bb9\u6027\uff0c\u63d0\u51fa\u4e86\u4e00\u79cd\u540d\u4e3aGRACE\u7684\u4e24\u9636\u6bb5\u6846\u67b6\uff0c\u7528\u4e8e\u9ad8\u6548\u89c6\u9891\u751f\u6210\u3002</li>\n    <li>GRACE\u901a\u8fc7\u4fdd\u7559\u57fa\u7840\u6f5c\u5728\u53d8\u91cf\u5e76\u5b66\u4e60\u6b8b\u5dee\u6f5c\u5728\u53d8\u91cf\u6765\u4f18\u5316\u538b\u7f29\u8fc7\u7a0b\u3002</li>\n    <li>\u8be5\u65b9\u6cd5\u5b9e\u73b0\u4e868\u500d\u7684\u4ee4\u724c\u6570\u51cf\u5c11\u548c11.1\u500d\u7684\u5ef6\u8fdf\u964d\u4f4e\uff0c\u540c\u65f6\u4fdd\u6301\u751f\u6210\u8d28\u91cf\u3002</li>\n</ul>", "summary_simple": "<ul>\n  <li>Compressed video autoencoders can speed up video diffusion models by using fewer tokens.</li>\n  <li>Training these autoencoders is difficult because higher compression can lower video quality.</li>\n  <li>To solve this, the GRACE framework compresses a pretrained video autoencoder while keeping it compatible with the diffusion model.</li>\n  <li>GRACE learns an extra layer of information to improve video generation while maintaining quality.</li>\n  <li>This approach significantly reduces processing time and token count while delivering similar quality as the original model.</li>\n</ul>"}, "publishedAt": "2026-10-06T20:00:00.000Z", "title": "GRACE: Generation-aware latent compression for efficient video generation", "summary": "Highly compressed video autoencoders offer an effective way to accelerate video diffusion models, as the Diffusion Transformer (DiT) operates on far fewer tokens. However, such autoencoders are challenging to train, since a higher compression ratio degrades reconstruction quality and recovering it requires more channels, which is known to slow the convergence of the DiT. The compressed latent also differs from the one the DiT was trained on, so the pretrained DiT must be either retrained from scratch or adapted at considerable cost. Compressing the autoencoder the DiT was trained with appears to preserve compatibility, yet optimizing it for reconstruction alone still shifts the latent away from the distribution the DiT has learned. To address this, we propose Generation-Aware Latent Compression for Efficient Video Generation (GRACE), a two-stage framework that compresses a pretrained video autoencoder while keeping it compatible with the pretrained DiT. Specifically, we keep a frozen base latent from the pretrained encoder and learn a residual latent for the information lost under stronger compression, while aligning the compressed latent with the pretrained latent in the feature space of the frozen DiT so that the autoencoder is optimized for generation. We then adapt the DiT with lightweight fine-tuning and asymmetric denoising, where the base is denoised ahead of the residual. GRACE reduces the token count of Wan2.1-I2V-14B by 8x and its latency by 11.1x at 480x832x81, while matching the generation quality of the pretrained pipeline before compression on VBench.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/65cb4ce4d5822659ec122119/vuLISuzr1b3izauYyA274.mp4"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.10524.png", "numComments": 1, "submittedBy": {"_id": "65cb4ce4d5822659ec122119", "avatarUrl": "/avatars/b7e4b4c6914b32e097648dd5991dec26.svg", "fullname": "jee0", "name": "chimaharicox", "type": "user", "isPro": true, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 1, "isUserFollowing": false}, "organization": {"_id": "6475760c33192631bad2bb38", "name": "kaist-ai", "fullname": "KAIST AI", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/6469949654873f0043b09c22/aaZFiyXe1qR-Dmy_xq67m.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.12126", "authors": [{"_id": "6ac84bfc4364a3d18a5cc6c5", "name": "Jinkai Zhang", "hidden": false}, {"_id": "6ac84bfc4364a3d18a5cc6c6", "name": "Jingyi Xu", "hidden": false}, {"_id": "6ac84bfc4364a3d18a5cc6c7", "name": "Yuanhong Yu", "hidden": false}, {"_id": "6ac84bfc4364a3d18a5cc6c8", "name": "Jiarui Guo", "hidden": false}, {"_id": "6ac84bfc4364a3d18a5cc6c9", "name": "Ruizhen Hu", "hidden": false}, {"_id": "6ac84bfc4364a3d18a5cc6ca", "name": "Hujun Bao", "hidden": false}, {"_id": "6ac84bfc4364a3d18a5cc6cb", "name": "Xiaowei Zhou", "hidden": false}, {"_id": "6ac84bfc4364a3d18a5cc6cc", "name": "Sida Peng", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/653b560b025e5d01725dd1b0/LF5AsDNLDR1hcNX1oHoET.mp4", "https://cdn-uploads.huggingface.co/production/uploads/653b560b025e5d01725dd1b0/pUg84zM-QSVTHiLoMYbTI.mp4", "https://cdn-uploads.huggingface.co/production/uploads/653b560b025e5d01725dd1b0/6tod5HobhOHHMT7F6J8cK.mp4", "https://cdn-uploads.huggingface.co/production/uploads/653b560b025e5d01725dd1b0/4OTs3Bes8yxzVycKUH-qw.mp4", "https://cdn-uploads.huggingface.co/production/uploads/653b560b025e5d01725dd1b0/e5Zfn-bMFcxQ_ZQgftb-S.mp4"], "publishedAt": "2026-10-08T00:00:00.000Z", "submittedOnDailyAt": "2026-10-09T00:00:00.000Z", "title": "SuperNav: An Agentic Navigation System for Any Task in Any Scene", "submittedOnDailyBy": {"_id": "653b560b025e5d01725dd1b0", "avatarUrl": "/avatars/280b612c817caccc8086e2713398a705.svg", "isPro": false, "fullname": "yyh", "user": "yyh929", "type": "user", "name": "yyh929"}, "summary": "General-purpose service robots need navigation systems that can handle diverse human requests in unfamiliar environments, combining task generality with scene generality. Some existing methods fine-tune multimodal large language models (MLLMs) to predict navigation actions, making their behavior dependent on the coverage of navigation training data and potentially limiting generalization to new requests and environments. Our key insight is to let the MLLM focus on interpreting requests, understanding scenes, and making decisions while preserving its general-purpose capabilities and delegating motion execution to navigation tools. To realize this idea, we introduce SuperNav, which equips a pretrained MLLM with a specialized agent harness without navigation-specific fine-tuning of the MLLM. Our harness supports these decisions with Navigation Skills, agent-oriented Tools for physical interaction, and task-progress and context management. A unified visual-point interface connects decision-making to motion by allowing the model to specify destinations directly in images and revise its decisions from execution feedback. Together, these components support sustained navigation across different task requirements and environments. SuperNav outperforms four evaluated baselines on instance-level, multi-object, and demand-driven tasks. Category-level evaluation on HM3D and deployment on a real quadruped robot further demonstrate its applicability across environments. Project Page: https://zju3dv.github.io/SuperNav/", "upvotes": 46, "discussionId": "6ac84bfc4364a3d18a5cc6cd", "projectPage": "https://zju3dv.github.io/SuperNav/", "githubRepo": "https://github.com/zju3dv/SuperNav", "githubRepoAddedBy": "user", "githubStars": 10, "organization": {"_id": "642673e52a423daad52d5b86", "name": "zju3dv", "fullname": "zju3dv", "avatar": "https://www.gravatar.com/avatar/38d28859223ed13a997edb0e9911614a?d=retro&size=100"}, "summary_zh": "<ul>\n    <li>\u901a\u7528\u670d\u52a1\u673a\u5668\u4eba\u9700\u8981\u80fd\u591f\u5728\u964c\u751f\u73af\u5883\u4e2d\u5904\u7406\u5404\u79cd\u4eba\u7c7b\u8bf7\u6c42\u7684\u5bfc\u822a\u7cfb\u7edf\u3002</li>\n    <li>\u73b0\u6709\u65b9\u6cd5\u901a\u8fc7\u5fae\u8c03\u591a\u6a21\u6001\u5927\u578b\u8bed\u8a00\u6a21\u578b\uff08MLLM\uff09\u6765\u9884\u6d4b\u5bfc\u822a\u52a8\u4f5c\uff0c\u4f46\u53ef\u80fd\u9650\u5236\u5176\u5bf9\u65b0\u8bf7\u6c42\u548c\u73af\u5883\u7684\u9002\u5e94\u80fd\u529b\u3002</li>\n    <li>\u6211\u4eec\u63d0\u51faSuperNav\uff0c\u5b83\u4e0d\u9700\u8981\u5bf9MLLM\u8fdb\u884c\u5bfc\u822a\u7279\u5b9a\u7684\u5fae\u8c03\uff0c\u800c\u662f\u8ba9MLLM\u4e13\u6ce8\u4e8e\u7406\u89e3\u8bf7\u6c42\u548c\u573a\u666f\uff0c\u5e76\u505a\u51fa\u51b3\u7b56\u3002</li>\n    <li>SuperNav\u914d\u5907\u4e86\u652f\u6301\u51b3\u7b56\u7684\u5bfc\u822a\u6280\u80fd\u3001\u5de5\u5177\u548c\u4efb\u52a1\u7ba1\u7406\uff0c\u80fd\u591f\u4fc3\u8fdb\u4e0d\u540c\u4efb\u52a1\u8981\u6c42\u4e0b\u7684\u6301\u7eed\u5bfc\u822a\u3002</li>\n    <li>SuperNav\u5728\u591a\u9879\u4efb\u52a1\u4e2d\u8868\u73b0\u4f18\u4e8e\u56db\u4e2a\u8bc4\u4f30\u57fa\u7ebf\uff0c\u5e76\u5728\u771f\u5b9e\u56db\u8db3\u673a\u5668\u4eba\u4e0a\u5f97\u5230\u4e86\u9a8c\u8bc1\uff0c\u8bc1\u660e\u4e86\u5176\u5728\u4e0d\u540c\u73af\u5883\u4e2d\u7684\u9002\u7528\u6027\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>General-purpose service robots need good navigation systems for various human requests in new places.</li>\n    <li>Some existing methods rely on training large language models, which may not work well in all situations.</li>\n    <li>SuperNav allows a large language model to focus on understanding requests and scenes without extra training for navigation.</li>\n    <li>It includes tools for managing tasks and interactions, connecting decisions directly to actions through a visual interface.</li>\n    <li>SuperNav performs better than other methods in different tasks and works well on a real robot.</li>\n</ul>"}, "publishedAt": "2026-10-07T20:00:00.000Z", "title": "SuperNav: An Agentic Navigation System for Any Task in Any Scene", "summary": "General-purpose service robots need navigation systems that can handle diverse human requests in unfamiliar environments, combining task generality with scene generality. Some existing methods fine-tune multimodal large language models (MLLMs) to predict navigation actions, making their behavior dependent on the coverage of navigation training data and potentially limiting generalization to new requests and environments. Our key insight is to let the MLLM focus on interpreting requests, understanding scenes, and making decisions while preserving its general-purpose capabilities and delegating motion execution to navigation tools. To realize this idea, we introduce SuperNav, which equips a pretrained MLLM with a specialized agent harness without navigation-specific fine-tuning of the MLLM. Our harness supports these decisions with Navigation Skills, agent-oriented Tools for physical interaction, and task-progress and context management. A unified visual-point interface connects decision-making to motion by allowing the model to specify destinations directly in images and revise its decisions from execution feedback. Together, these components support sustained navigation across different task requirements and environments. SuperNav outperforms four evaluated baselines on instance-level, multi-object, and demand-driven tasks. Category-level evaluation on HM3D and deployment on a real quadruped robot further demonstrate its applicability across environments. Project Page: https://zju3dv.github.io/SuperNav/", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/653b560b025e5d01725dd1b0/LF5AsDNLDR1hcNX1oHoET.mp4", "https://cdn-uploads.huggingface.co/production/uploads/653b560b025e5d01725dd1b0/pUg84zM-QSVTHiLoMYbTI.mp4", "https://cdn-uploads.huggingface.co/production/uploads/653b560b025e5d01725dd1b0/6tod5HobhOHHMT7F6J8cK.mp4", "https://cdn-uploads.huggingface.co/production/uploads/653b560b025e5d01725dd1b0/4OTs3Bes8yxzVycKUH-qw.mp4", "https://cdn-uploads.huggingface.co/production/uploads/653b560b025e5d01725dd1b0/e5Zfn-bMFcxQ_ZQgftb-S.mp4"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.12126.png", "numComments": 1, "submittedBy": {"_id": "653b560b025e5d01725dd1b0", "avatarUrl": "/avatars/280b612c817caccc8086e2713398a705.svg", "fullname": "yyh", "name": "yyh929", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 5, "isUserFollowing": false}, "organization": {"_id": "642673e52a423daad52d5b86", "name": "zju3dv", "fullname": "zju3dv", "avatar": "https://www.gravatar.com/avatar/38d28859223ed13a997edb0e9911614a?d=retro&size=100"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.12242", "authors": [{"_id": "6ac8556c4364a3d18a5cc773", "name": "Tianyu Fu", "hidden": false}, {"_id": "6ac8556c4364a3d18a5cc774", "name": "Tengxuan Liu", "hidden": false}, {"_id": "6ac8556c4364a3d18a5cc775", "name": "Ruoxi Wang", "hidden": false}, {"_id": "6ac8556c4364a3d18a5cc776", "name": "Yixin Dong", "hidden": false}, {"_id": "6ac8556c4364a3d18a5cc777", "name": "Yi Ge", "hidden": false}, {"_id": "6ac8556c4364a3d18a5cc778", "name": "Yichen You", "hidden": false}, {"_id": "6ac8556c4364a3d18a5cc779", "name": "Yu Wang", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/6445fd9ba56444c355dcbcba/0OrTOp3ievhuQL9HFSKmJ.png"], "publishedAt": "2026-10-08T00:00:00.000Z", "submittedOnDailyAt": "2026-10-09T00:00:00.000Z", "title": "TokenRouter: Efficient Serving System for Token-Level LLM Routing", "submittedOnDailyBy": {"_id": "6445fd9ba56444c355dcbcba", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/6445fd9ba56444c355dcbcba/NCyRCD-MK-yA0_qY6I2y0.png", "isPro": false, "fullname": "Tianyu Fu", "user": "fuvty", "type": "user", "name": "fuvty"}, "summary": "Large language model (LLM) routing distributes inference work across different models, advancing the cost-quality Pareto frontier of LLM serving. While coarse-grained routing at the session or query level has been widely adopted in production systems, recent algorithmic work shows that fine-grained token-level routing can yield substantial efficiency and quality gains. However, efficiently serving token-level routed inference poses significant challenges to existing systems. Built on single-LLM assumptions, current systems suffer from severe step desynchronization and frequent batch admission delays under token-level routing, and they also impose high implementation complexity on developers. To address these challenges, we design TokenRouter, an efficient and developer-friendly serving system for token-level routed LLM inference. TokenRouter follows the principle of request-centric programming, model-centric execution: developers describe routing logic from the perspective of a single request, while the runtime launches a subserver for each LLM and dispatches requests asynchronously. Each subserver employs a delayed-batching scheduler, whose optimal hyperparameters are derived from a mathematical throughput model of the system. Across diverse routing algorithms, workloads, and model pairs, TokenRouter achieves 2.01-64.15x higher decoding throughput than existing systems, substantially advancing the serving efficiency of token-level LLM routing. Our code is available at https://github.com/thu-nics/TokenRouter.", "upvotes": 38, "discussionId": "6ac8556c4364a3d18a5cc77a", "projectPage": "https://fuvty.github.io/thinking_yard_project_page/projects/tokenrouter/", "githubRepo": "https://github.com/thu-nics/TokenRouter", "githubRepoAddedBy": "user", "githubStars": 4, "organization": {"_id": "64b74b5fb727f8771ab887f9", "name": "nics-efc", "fullname": "Tsinghua-NICS-EFC", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/641031b1a78453b8d96b8420/vmgxct2WsyHcKT2x2NAYT.jpeg"}, "summary_zh": "<ul>\n    <li>\u5927\u578b\u8bed\u8a00\u6a21\u578b\uff08LLM\uff09\u8def\u7531\u53ef\u4ee5\u5728\u4e0d\u540c\u6a21\u578b\u4e4b\u95f4\u5206\u914d\u63a8\u7406\u4efb\u52a1\uff0c\u63d0\u9ad8\u670d\u52a1\u7684\u6210\u672c\u548c\u8d28\u91cf\u3002</li>\n    <li>\u76ee\u524d\u666e\u904d\u4f7f\u7528\u7684\u5927\u7c92\u5ea6\u8def\u7531\u5b58\u5728\u6548\u7387\u4f4e\u4e0b\u7684\u95ee\u9898\uff0c\u7ec6\u7c92\u5ea6\u7684\u4ee4\u724c\u7ea7\u8def\u7531\u80fd\u663e\u8457\u63d0\u9ad8\u6548\u7387\u548c\u8d28\u91cf\u3002</li>\n    <li>\u73b0\u6709\u7cfb\u7edf\u5728\u5904\u7406\u4ee4\u724c\u7ea7\u8def\u7531\u65f6\u9762\u4e34\u4e25\u91cd\u7684\u540c\u6b65\u95ee\u9898\u548c\u9ad8\u590d\u6742\u6027\u3002</li>\n    <li>\u4e3a\u4e86\u89e3\u51b3\u8fd9\u4e9b\u95ee\u9898\uff0c\u6211\u4eec\u8bbe\u8ba1\u4e86TokenRouter\uff0c\u8fd9\u662f\u4e00\u4e2a\u9ad8\u6548\u4e14\u6613\u4e8e\u5f00\u53d1\u8005\u4f7f\u7528\u7684\u63a8\u7406\u7cfb\u7edf\u3002</li>\n    <li>TokenRouter\u5728\u5404\u79cd\u8def\u7531\u7b97\u6cd5\u548c\u6a21\u578b\u5bf9\u6bd4\u4e2d\uff0c\u89e3\u7801\u541e\u5410\u91cf\u6bd4\u73b0\u6709\u7cfb\u7edf\u9ad8\u51fa2.01\u523064.15\u500d\uff0c\u63d0\u9ad8\u4e86\u670d\u52a1\u6548\u7387\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>TokenRouter improves how large language models (LLMs) handle requests by using token-level routing instead of just session or query-level routing.</li>\n    <li>This new approach helps to make LLMs faster and of better quality, but existing systems struggle with implementation and efficiency.</li>\n    <li>TokenRouter simplifies development by allowing developers to focus on individual request logic while managing multiple LLMs in the background.</li>\n    <li>It uses a smart scheduling system to manage requests efficiently, significantly increasing processing speed compared to current systems.</li>\n    <li>The improved system can process requests 2 to 64 times faster, enhancing the overall performance of LLM routing.</li>\n</ul>"}, "publishedAt": "2026-10-07T20:00:00.000Z", "title": "TokenRouter: Efficient Serving System for Token-Level LLM Routing", "summary": "Large language model (LLM) routing distributes inference work across different models, advancing the cost-quality Pareto frontier of LLM serving. While coarse-grained routing at the session or query level has been widely adopted in production systems, recent algorithmic work shows that fine-grained token-level routing can yield substantial efficiency and quality gains. However, efficiently serving token-level routed inference poses significant challenges to existing systems. Built on single-LLM assumptions, current systems suffer from severe step desynchronization and frequent batch admission delays under token-level routing, and they also impose high implementation complexity on developers. To address these challenges, we design TokenRouter, an efficient and developer-friendly serving system for token-level routed LLM inference. TokenRouter follows the principle of request-centric programming, model-centric execution: developers describe routing logic from the perspective of a single request, while the runtime launches a subserver for each LLM and dispatches requests asynchronously. Each subserver employs a delayed-batching scheduler, whose optimal hyperparameters are derived from a mathematical throughput model of the system. Across diverse routing algorithms, workloads, and model pairs, TokenRouter achieves 2.01-64.15x higher decoding throughput than existing systems, substantially advancing the serving efficiency of token-level LLM routing. Our code is available at https://github.com/thu-nics/TokenRouter.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/6445fd9ba56444c355dcbcba/0OrTOp3ievhuQL9HFSKmJ.png"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.12242.png", "numComments": 1, "submittedBy": {"_id": "6445fd9ba56444c355dcbcba", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/6445fd9ba56444c355dcbcba/NCyRCD-MK-yA0_qY6I2y0.png", "fullname": "Tianyu Fu", "name": "fuvty", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 18, "isUserFollowing": false}, "organization": {"_id": "64b74b5fb727f8771ab887f9", "name": "nics-efc", "fullname": "Tsinghua-NICS-EFC", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/641031b1a78453b8d96b8420/vmgxct2WsyHcKT2x2NAYT.jpeg"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.10429", "authors": [{"_id": "6ac6fb414eb8005165aed3aa", "name": "Zihan Su", "hidden": false}, {"_id": "6ac6fb414eb8005165aed3ab", "name": "Junhao Zhuang", "hidden": false}, {"_id": "6ac6fb414eb8005165aed3ac", "name": "Yaowei Li", "hidden": false}, {"_id": "6ac6fb414eb8005165aed3ad", "name": "Siwen Lu", "hidden": false}, {"_id": "6ac6fb414eb8005165aed3ae", "name": "Haoran Li", "hidden": false}, {"_id": "6ac6fb414eb8005165aed3af", "name": "Lingen Li", "hidden": false}, {"_id": "6ac6fb414eb8005165aed3b0", "name": "Haoyu Wu", "hidden": false}, {"_id": "6ac6fb414eb8005165aed3b1", "name": "Weiyang Jin", "hidden": false}, {"_id": "6ac6fb414eb8005165aed3b2", "name": "Songchun Zhang", "hidden": false}, {"_id": "6ac6fb414eb8005165aed3b3", "name": "Haoyang Huang", "hidden": false}, {"_id": "6ac6fb414eb8005165aed3b4", "name": "Chun Yuan", "hidden": false}, {"_id": "6ac6fb414eb8005165aed3b5", "name": "Zeyue Xue", "hidden": false}, {"_id": "6ac6fb414eb8005165aed3b6", "name": "Nan Duan", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/648dca31385b84261811505d/NIpW_-KxWbuBhyx7QFi7Z.mp4"], "publishedAt": "2026-10-07T00:00:00.000Z", "submittedOnDailyAt": "2026-10-08T00:00:00.000Z", "title": "SGF+: Decoupling Gradient Flows for Autoregressive Video Generation", "submittedOnDailyBy": {"_id": "648dca31385b84261811505d", "avatarUrl": "/avatars/dfd124e3b5ffed8b0d3f429be0f7bdc0.svg", "isPro": false, "fullname": "Zihan Su", "user": "ZihanSu", "type": "user", "name": "ZihanSu"}, "summary": "Autoregressive video generation requires denoising the current frames while writing their key-value representations as context for future predictions. However, these two roles typically share parameters, and we find that their gradients exhibit distinct patterns and systematic negative alignment, hindering the joint optimization of visual quality and temporal consistency. We introduce Self Gradient Forcing Plus (SGF+), which assigns separate parameters to context writing and denoising while preserving their interaction through causal attention. Both roles are jointly optimized using the original generation objective without auxiliary losses, with context writing supervised through its contribution to future predictions. This simple change improves visual quality and long-horizon consistency over the evaluated baselines in both framewise and chunkwise generation, without additional video training data or a longer training horizon. Trained on only 5s rollouts, SGF+ supports continuous generation for up to 24 hours without long-video fine-tuning. These results highlight role-specific parameterization as an effective design principle for high-quality autoregressive video generation and native long-horizon extrapolation.", "upvotes": 38, "discussionId": "6ac6fb414eb8005165aed3b7", "projectPage": "https://zihan-su.github.io/self-gradient-forcing-plus/", "githubRepo": "https://github.com/Zihan-Su/Self_Gradient_Forcing_Plus", "githubRepoAddedBy": "user", "githubStars": 15, "summary_zh": "<ul>\n    <li>\u81ea\u56de\u5f52\u89c6\u9891\u751f\u6210\u9700\u8981\u5bf9\u5f53\u524d\u5e27\u8fdb\u884c\u53bb\u566a\uff0c\u5e76\u5c06\u5176\u5173\u952e\u503c\u8868\u793a\u4f5c\u4e3a\u672a\u6765\u9884\u6d4b\u7684\u4e0a\u4e0b\u6587\u3002</li>\n    <li>\u53bb\u566a\u548c\u4e0a\u4e0b\u6587\u5199\u5165\u901a\u5e38\u5171\u4eab\u53c2\u6570\uff0c\u4f46\u5b83\u4eec\u7684\u68af\u5ea6\u8868\u73b0\u51fa\u4e0d\u540c\u7684\u6a21\u5f0f\uff0c\u5f71\u54cd\u4e86\u89c6\u89c9\u8d28\u91cf\u548c\u65f6\u95f4\u4e00\u81f4\u6027\u7684\u4f18\u5316\u3002</li>\n    <li>\u63d0\u51fa\u4e86\u81ea\u68af\u5ea6\u5f3a\u5236\u52a0\uff08SGF+\uff09\uff0c\u4e3a\u4e0a\u4e0b\u6587\u5199\u5165\u548c\u53bb\u566a\u5206\u914d\u4e86\u72ec\u7acb\u53c2\u6570\uff0c\u901a\u8fc7\u56e0\u679c\u6ce8\u610f\u529b\u4fdd\u6301\u5b83\u4eec\u7684\u4ea4\u4e92\u3002</li>\n    <li>SGF+\u5728\u4e0d\u9700\u8981\u989d\u5916\u635f\u5931\u7684\u60c5\u51b5\u4e0b\u4f18\u5316\u8fd9\u4e24\u4e2a\u89d2\u8272\uff0c\u63d0\u9ad8\u4e86\u89c6\u89c9\u8d28\u91cf\u548c\u957f\u65f6\u95f4\u4e00\u81f4\u6027\u3002</li>\n    <li>\u53ea\u75285\u79d2\u7684\u8bad\u7ec3\u6570\u636e\uff0cSGF+\u53ef\u4ee5\u652f\u6301\u6700\u957f\u8fbe24\u5c0f\u65f6\u7684\u8fde\u7eed\u751f\u6210\uff0c\u65e0\u9700\u957f\u89c6\u9891\u7684\u5fae\u8c03\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Autoregressive video generation needs to balance denoising current frames and creating context for future predictions.</li>\n    <li>Sharing parameters between these two tasks causes issues, making it hard to optimize both visual quality and consistency.</li>\n    <li>The new method, Self Gradient Forcing Plus (SGF+), uses separate parameters for denoising and context writing while still allowing them to interact.</li>\n    <li>SGF+ improves video quality and consistency without needing extra training data or longer training times.</li>\n    <li>It can generate videos continuously for up to 24 hours after being trained on short clips, showing its effectiveness in video generation.</li>\n</ul>"}, "publishedAt": "2026-10-06T20:00:00.000Z", "title": "SGF+: Decoupling Gradient Flows for Autoregressive Video Generation", "summary": "Autoregressive video generation requires denoising the current frames while writing their key-value representations as context for future predictions. However, these two roles typically share parameters, and we find that their gradients exhibit distinct patterns and systematic negative alignment, hindering the joint optimization of visual quality and temporal consistency. We introduce Self Gradient Forcing Plus (SGF+), which assigns separate parameters to context writing and denoising while preserving their interaction through causal attention. Both roles are jointly optimized using the original generation objective without auxiliary losses, with context writing supervised through its contribution to future predictions. This simple change improves visual quality and long-horizon consistency over the evaluated baselines in both framewise and chunkwise generation, without additional video training data or a longer training horizon. Trained on only 5s rollouts, SGF+ supports continuous generation for up to 24 hours without long-video fine-tuning. These results highlight role-specific parameterization as an effective design principle for high-quality autoregressive video generation and native long-horizon extrapolation.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/648dca31385b84261811505d/NIpW_-KxWbuBhyx7QFi7Z.mp4"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.10429.png", "numComments": 1, "submittedBy": {"_id": "648dca31385b84261811505d", "avatarUrl": "/avatars/dfd124e3b5ffed8b0d3f429be0f7bdc0.svg", "fullname": "Zihan Su", "name": "ZihanSu", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 1, "isUserFollowing": false}, "isAuthorParticipating": false}, {"paper": {"id": "2610.08215", "authors": [{"_id": "6ac855944364a3d18a5cc77d", "name": "Yibo Li", "hidden": false}, {"_id": "6ac855944364a3d18a5cc77e", "name": "Jinhang Qiu", "hidden": false}, {"_id": "6ac855944364a3d18a5cc77f", "name": "Zhi Zheng", "hidden": false}, {"_id": "6ac855944364a3d18a5cc780", "name": "Qianyun Guo", "hidden": false}, {"_id": "6ac855944364a3d18a5cc781", "name": "Jiaying Wu", "hidden": false}, {"_id": "6ac855944364a3d18a5cc782", "name": "Shuo Ji", "hidden": false}, {"_id": "6ac855944364a3d18a5cc783", "name": "Bryan Hooi", "hidden": false}], "publishedAt": "2026-10-08T00:00:00.000Z", "submittedOnDailyAt": "2026-10-09T00:00:00.000Z", "title": "Learn2Play Bench: How Well Do LLM Agents Learn from Experience in Unfamiliar Environments?", "submittedOnDailyBy": {"_id": "67a1d21e33e92b4a1183f3bb", "avatarUrl": "/avatars/43f9dd3fcb7d58ddc69562fd1fc12957.svg", "isPro": false, "fullname": "Zhi Zheng", "user": "zz1358m", "type": "user", "name": "zz1358m"}, "summary": "Learning from experience is essential for LLM agents to adapt to unfamiliar and dynmaic environments. Evaluating this ability is therefore important for understanding how effectively agents acquire and use new knowledge. Existing benchmarks have sought to evaluate this ability, but they primarily evaluate tasks whose rules are provided in the instructions or already familiar to pretrained models, making it difficult to distinguish learning from interactions from reasoning with existing knowledge. To address this, we introduce Learn2Play Bench, a benchmark of newly designed text-based games, whose rules are novel or counterintuitive, requiring agents to acquire knowledge through interaction rather than rely solely on pretrained knowledge. These games provide reproducible feedback and automatic scoring, enabling controlled evaluation of learning across repeated attempts. We also vary game instances to test whether agents can apply what they have learned to new situations. Therefore, we evaluate how backbone models, self-evolving methods, and agent harnesses affect agents' learning ability, revealing three findings: (1) Experience retention: Retaining complete records of actions and feedback can support more effective learning than summarizing these experiences into rules or strategies. (2) Human agent gap: Top-performing human players achieve higher peak scores than the evaluated agents. Human explore more varied strategies, and repeat actions less. (3) Harness matters: With the backbone fixed, changing the harness can improve performance while reducing estimated inference cost. Together, these findings provide insights into how LLM agents learn from experience and suggest directions for future work to improve their learning ability. Project website: https://liushiliushi.github.io/learn2play-bench-website/", "upvotes": 32, "discussionId": "6ac855944364a3d18a5cc784", "projectPage": "https://liushiliushi.github.io/learn2play-bench-website/", "githubRepo": "https://github.com/liushiliushi/Learn2Play-Bench", "githubRepoAddedBy": "user", "githubStars": 0, "organization": {"_id": "6508ab2b349930913196378b", "name": "NationalUniversityofSingapore", "fullname": "National University of Singapore", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/630ca0817dacb93b33506ce7/ZYUmpSMsa5Whihw3me2Bw.png"}, "summary_zh": "<ul>\n    <li>\u5b66\u4e60\u7ecf\u9a8c\u5bf9\u5927\u578b\u8bed\u8a00\u6a21\u578b\uff08LLM\uff09\u4ee3\u7406\u5728\u4e0d\u719f\u6089\u548c\u52a8\u6001\u73af\u5883\u4e2d\u7684\u9002\u5e94\u81f3\u5173\u91cd\u8981\u3002</li>\n    <li>\u73b0\u6709\u8bc4\u4f30\u65b9\u6cd5\u4e3b\u8981\u57fa\u4e8e\u5df2\u77e5\u89c4\u5219\uff0c\u96be\u4ee5\u533a\u5206\u5b66\u4e60\u4e0e\u63a8\u7406\u3002</li>\n    <li>\u6211\u4eec\u5f15\u5165\u4e86Learn2Play Bench\uff0c\u4e00\u4e2a\u65b0\u7684\u6587\u672c\u6e38\u620f\u57fa\u51c6\uff0c\u89c4\u5219\u65b0\u9896\uff0c\u9700\u8981\u901a\u8fc7\u4e92\u52a8\u6765\u5b66\u4e60\u3002</li>\n    <li>\u7814\u7a76\u53d1\u73b0\uff1a\u4fdd\u7559\u5b8c\u6574\u7684\u884c\u52a8\u548c\u53cd\u9988\u8bb0\u5f55\u80fd\u66f4\u6709\u6548\u5730\u5b66\u4e60\uff1b\u9876\u7ea7\u4eba\u7c7b\u73a9\u5bb6\u8868\u73b0\u4f18\u4e8e\u4ee3\u7406\uff1b\u6539\u53d8\u4ee3\u7406\u7684\u7ed3\u6784\u53ef\u4ee5\u63d0\u9ad8\u6027\u80fd\u3002</li>\n    <li>\u8fd9\u4e9b\u53d1\u73b0\u4e3a\u5982\u4f55\u63d0\u5347LLM\u4ee3\u7406\u7684\u5b66\u4e60\u80fd\u529b\u63d0\u4f9b\u4e86\u89c1\u89e3\u4e0e\u672a\u6765\u7814\u7a76\u65b9\u5411\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Learning from experience is crucial for LLM agents to adapt to new and changing environments.</li>\n    <li>Current benchmarks mainly test familiar tasks, making it hard to see how agents learn from new interactions.</li>\n    <li>The Learn2Play Bench introduces new text-based games that require agents to learn by interacting, not just using prior knowledge.</li>\n    <li>Key findings include that keeping detailed records helps learning, humans perform better than agents, and changing the agent's harness can enhance performance.</li>\n    <li>These insights aim to improve how LLM agents learn from experience in the future.</li>\n</ul>"}, "publishedAt": "2026-10-07T20:00:00.000Z", "title": "Learn2Play Bench: How Well Do LLM Agents Learn from Experience in Unfamiliar Environments?", "summary": "Learning from experience is essential for LLM agents to adapt to unfamiliar and dynmaic environments. Evaluating this ability is therefore important for understanding how effectively agents acquire and use new knowledge. Existing benchmarks have sought to evaluate this ability, but they primarily evaluate tasks whose rules are provided in the instructions or already familiar to pretrained models, making it difficult to distinguish learning from interactions from reasoning with existing knowledge. To address this, we introduce Learn2Play Bench, a benchmark of newly designed text-based games, whose rules are novel or counterintuitive, requiring agents to acquire knowledge through interaction rather than rely solely on pretrained knowledge. These games provide reproducible feedback and automatic scoring, enabling controlled evaluation of learning across repeated attempts. We also vary game instances to test whether agents can apply what they have learned to new situations. Therefore, we evaluate how backbone models, self-evolving methods, and agent harnesses affect agents' learning ability, revealing three findings: (1) Experience retention: Retaining complete records of actions and feedback can support more effective learning than summarizing these experiences into rules or strategies. (2) Human agent gap: Top-performing human players achieve higher peak scores than the evaluated agents. Human explore more varied strategies, and repeat actions less. (3) Harness matters: With the backbone fixed, changing the harness can improve performance while reducing estimated inference cost. Together, these findings provide insights into how LLM agents learn from experience and suggest directions for future work to improve their learning ability. Project website: https://liushiliushi.github.io/learn2play-bench-website/", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.08215.png", "numComments": 1, "submittedBy": {"_id": "67a1d21e33e92b4a1183f3bb", "avatarUrl": "/avatars/43f9dd3fcb7d58ddc69562fd1fc12957.svg", "fullname": "Zhi Zheng", "name": "zz1358m", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 7, "isUserFollowing": false}, "organization": {"_id": "6508ab2b349930913196378b", "name": "NationalUniversityofSingapore", "fullname": "National University of Singapore", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/630ca0817dacb93b33506ce7/ZYUmpSMsa5Whihw3me2Bw.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.13166", "authors": [{"_id": "6acc50ce0ee6ff34004fde8d", "user": {"_id": "6901b520f8f20b9d7015a38d", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/6901b520f8f20b9d7015a38d/HIlNYBWGOI_XhI9aUJoAl.jpeg", "isPro": false, "fullname": "Shun Zou", "user": "shunzou05", "type": "user", "name": "shunzou05"}, "name": "Shun Zou", "status": "claimed_verified", "statusLastChangedAt": "2026-10-12T08:45:06.115Z", "hidden": false}, {"_id": "6acc50ce0ee6ff34004fde8e", "name": "Ziyu Ma", "hidden": false}, {"_id": "6acc50ce0ee6ff34004fde8f", "name": "Yi Zou", "hidden": false}, {"_id": "6acc50ce0ee6ff34004fde90", "name": "Yong Wang", "hidden": false}, {"_id": "6acc50ce0ee6ff34004fde91", "name": "Lin Chen", "hidden": false}, {"_id": "6acc50ce0ee6ff34004fde92", "name": "Zehui Chen", "hidden": false}, {"_id": "6acc50ce0ee6ff34004fde93", "name": "Guanhua Chen", "hidden": false}, {"_id": "6acc50ce0ee6ff34004fde94", "name": "Xiangxiang Chu", "hidden": false}, {"_id": "6acc50ce0ee6ff34004fde95", "name": "Feng Zhao", "hidden": false}], "publishedAt": "2026-10-09T00:00:00.000Z", "submittedOnDailyAt": "2026-10-13T00:00:00.000Z", "title": "Scaling Agentic Data for Long-Horizon Terminal Intelligence", "submittedOnDailyBy": {"_id": "64d1dc5273174cecdffc97d3", "avatarUrl": "/avatars/6564e6b68fee9673f75b6366adf39a3b.svg", "isPro": false, "fullname": "Wang Yong", "user": "seashell11", "type": "user", "name": "seashell11"}, "summary": "Terminal agents are moving beyond local operations toward completing real-world professional tasks. Short trajectories can demonstrate commands and tool calls, but they do not fully show how agents accumulate evidence through exploration, use it to inform judgments, continually adjust strategies based on feedback, and turn intermediate results into final deliverables. High-quality long-horizon trajectories capture these agentic behavioral patterns and their connections within a single problem-solving process, providing richer experience for sustained autonomous work. However, environment synthesis may complete or simplify the key work underlying these patterns in advance and thus remove the need for exploration, implementation, and verification that the agent was meant to perform. To address this, we introduce TerminalHorizon, a fully automated data synthesis engine for long-horizon terminal agents. Starting from real-world professional work, it uses independent execution to identify key work omitted during construction and uses the resulting evidence to guide environment reconstruction. To extend these patterns across stages, it progressively expands tasks under the same goal, introducing new requirements that build on prior results and call for further exploration and improvement. Using this engine, we construct 1.5K task environments and perform supervised fine-tuning of Qwen3.5-27B on the resulting dataset to obtain TerminalHorizon-27B. We achieve substantial performance gains on all 12 benchmarks spanning coding-agent tasks, agentic tasks in real-world production settings, and general reasoning. Multiple RSI case studies, each with a 12-hour research budget, further demonstrate the model's ability to continue experimenting beyond an initial solution, improve its methods based on feedback, and retain effective improvements in its final deliverables.", "upvotes": 31, "discussionId": "6acc50ce0ee6ff34004fde96", "projectPage": "https://zs1314.github.io/TerminalHorizon", "organization": {"_id": "68be41370a3fcebdcad6516a", "name": "alibabagroup", "fullname": "alibaba", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/68be3ab7e52df040b2cf80dc/li4G29u_EGswyTN1Sm_Kq.png"}, "summary_zh": "<ul>\n    <li>\u7ec8\u7aef\u4ee3\u7406\u6b63\u5728\u5411\u5b8c\u6210\u771f\u5b9e\u4e13\u4e1a\u4efb\u52a1\u53d1\u5c55\uff0c\u800c\u4e0d\u4ec5\u9650\u4e8e\u672c\u5730\u64cd\u4f5c\u3002</li>\n    <li>\u77ed\u671f\u8f68\u8ff9\u65e0\u6cd5\u5145\u5206\u5c55\u793a\u4ee3\u7406\u5982\u4f55\u901a\u8fc7\u63a2\u7d22\u79ef\u7d2f\u8bc1\u636e\u3001\u8c03\u6574\u7b56\u7565\u5e76\u8f6c\u5316\u4e2d\u95f4\u7ed3\u679c\u3002</li>\n    <li>TerminalHorizon\u662f\u4e00\u4e2a\u81ea\u52a8\u5316\u6570\u636e\u5408\u6210\u5f15\u64ce\uff0c\u65e8\u5728\u751f\u6210\u957f\u65f6\u95f4\u8303\u56f4\u7684\u4efb\u52a1\u73af\u5883\u3002</li>\n    <li>\u8be5\u5f15\u64ce\u901a\u8fc7\u72ec\u7acb\u6267\u884c\u8bc6\u522b\u5173\u952e\u5de5\u4f5c\uff0c\u5e76\u9010\u6b65\u6269\u5c55\u4efb\u52a1\u4ee5\u4fc3\u8fdb\u66f4\u6df1\u5165\u7684\u63a2\u7d22\u548c\u6539\u8fdb\u3002</li>\n    <li>\u4f7f\u7528TerminalHorizon\uff0c\u6784\u5efa\u4e861500\u4e2a\u4efb\u52a1\u73af\u5883\uff0c\u5e76\u5728\u591a\u4e2a\u57fa\u51c6\u6d4b\u8bd5\u4e2d\u663e\u8457\u63d0\u9ad8\u4e86\u6027\u80fd\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Terminal agents are evolving to handle complex real-world tasks beyond simple commands and tool usage.</li>\n    <li>Long-term task tracking is important for capturing how these agents gather evidence, adjust strategies, and produce final results.</li>\n    <li>Environment synthesis can sometimes oversimplify tasks, reducing the need for important exploration and verification by the agent.</li>\n    <li>TerminalHorizon is a new automated tool that helps create realistic long-term tasks for agents by identifying missing elements and guiding task development.</li>\n    <li>The use of TerminalHorizon significantly improved performance in various coding and reasoning tasks, showcasing the agent's ability to adapt and enhance its solutions over time.</li>\n</ul>"}, "publishedAt": "2026-10-08T20:00:00.000Z", "title": "Scaling Agentic Data for Long-Horizon Terminal Intelligence", "summary": "Terminal agents are moving beyond local operations toward completing real-world professional tasks. Short trajectories can demonstrate commands and tool calls, but they do not fully show how agents accumulate evidence through exploration, use it to inform judgments, continually adjust strategies based on feedback, and turn intermediate results into final deliverables. High-quality long-horizon trajectories capture these agentic behavioral patterns and their connections within a single problem-solving process, providing richer experience for sustained autonomous work. However, environment synthesis may complete or simplify the key work underlying these patterns in advance and thus remove the need for exploration, implementation, and verification that the agent was meant to perform. To address this, we introduce TerminalHorizon, a fully automated data synthesis engine for long-horizon terminal agents. Starting from real-world professional work, it uses independent execution to identify key work omitted during construction and uses the resulting evidence to guide environment reconstruction. To extend these patterns across stages, it progressively expands tasks under the same goal, introducing new requirements that build on prior results and call for further exploration and improvement. Using this engine, we construct 1.5K task environments and perform supervised fine-tuning of Qwen3.5-27B on the resulting dataset to obtain TerminalHorizon-27B. We achieve substantial performance gains on all 12 benchmarks spanning coding-agent tasks, agentic tasks in real-world production settings, and general reasoning. Multiple RSI case studies, each with a 12-hour research budget, further demonstrate the model's ability to continue experimenting beyond an initial solution, improve its methods based on feedback, and retain effective improvements in its final deliverables.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.13166.png", "numComments": 1, "submittedBy": {"_id": "64d1dc5273174cecdffc97d3", "avatarUrl": "/avatars/6564e6b68fee9673f75b6366adf39a3b.svg", "fullname": "Wang Yong", "name": "seashell11", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 1, "isUserFollowing": false}, "organization": {"_id": "68be41370a3fcebdcad6516a", "name": "alibabagroup", "fullname": "alibaba", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/68be3ab7e52df040b2cf80dc/li4G29u_EGswyTN1Sm_Kq.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.13630", "authors": [{"_id": "6acd8959ead72e0d3c44fd25", "name": "Xiaohan Qin", "hidden": false}, {"_id": "6acd8959ead72e0d3c44fd26", "name": "Xiangdong Zhang", "hidden": false}, {"_id": "6acd8959ead72e0d3c44fd27", "name": "Tuo Dai", "hidden": false}, {"_id": "6acd8959ead72e0d3c44fd28", "name": "Sunan Zou", "hidden": false}, {"_id": "6acd8959ead72e0d3c44fd29", "name": "Huaijin Wu", "hidden": false}, {"_id": "6acd8959ead72e0d3c44fd2a", "name": "Yebin Yang", "hidden": false}, {"_id": "6acd8959ead72e0d3c44fd2b", "name": "Zhuo Xia", "hidden": false}, {"_id": "6acd8959ead72e0d3c44fd2c", "name": "Lin Yao", "hidden": false}, {"_id": "6acd8959ead72e0d3c44fd2d", "name": "Yuliang Liu", "hidden": false}, {"_id": "6acd8959ead72e0d3c44fd2e", "name": "Junchi Yan", "hidden": false}], "publishedAt": "2026-10-09T00:00:00.000Z", "submittedOnDailyAt": "2026-10-13T00:00:00.000Z", "title": "Multi-Stream Attention Residuals", "submittedOnDailyBy": {"_id": "64452110e1fd8d65b2790bfc", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/64452110e1fd8d65b2790bfc/3NIsQFV9X44X88aLXR6eE.jpeg", "isPro": false, "fullname": "Xiaohan Qin (SJTU) & (SII)", "user": "galaxy-1", "type": "user", "name": "galaxy-1"}, "summary": "Attention Residuals (AttnRes) enables content-dependent retrieval over network depth, which can be viewed as single-stream softmax attention along the depth axis. Inspired by the success of multi-head attention along the sequence axis, we introduce Multi-Stream Attention Residuals (MSAR), an extension of AttnRes that generalizes this mechanism to multi-head depth attention, yielding substantial performance gains with minimal additional overhead. MSAR draws stream diversity from sequence context through multi-scale causal convolutions, allowing different heads to retrieve historical representations through distinct contextual views while preserving the integrity of the hidden representation. The retrieved streams are combined through lightweight adaptive mixing to generate the single-stream layer input. By retaining single-stream sources and expanding them on demand, MSAR supports multi-stream computation without requiring persistent multi-stream storage or communication. Across all 12 downstream benchmarks at the 18B and 28B MoE scales, MSAR consistently outperforms prior residual variants, including standard residual connections, manifold-constrained Hyper-Connections (mHC), and AttnRes. Scaling-law experiments yield an iso-loss compute speedup of 1.58times over the standard residual baseline, compared with 1.35times for AttnRes and 1.30times for mHC. These results make MSAR a promising residual architecture for large-scale pre-training.", "upvotes": 30, "discussionId": "6acd8959ead72e0d3c44fd2f", "githubRepo": "https://github.com/jianke0604/MSAR", "githubRepoAddedBy": "user", "githubStars": 2, "organization": {"_id": "63e5ef7bf2e9a8f22c515654", "name": "SJTU", "fullname": "Shanghai Jiao Tong University", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/1676013394657-63e5ee22b6a40bf941da0928.png"}, "summary_zh": "<ul>\n    <li>Attention Residuals (AttnRes) \u5141\u8bb8\u6839\u636e\u5185\u5bb9\u5728\u7f51\u7edc\u6df1\u5ea6\u4e0a\u8fdb\u884c\u68c0\u7d22\uff0c\u7c7b\u4f3c\u4e8e\u6cbf\u6df1\u5ea6\u8f74\u7684\u5355\u6d41\u8f6f\u6700\u5927\u6ce8\u610f\u529b\u3002</li>\n    <li>\u591a\u6d41\u6ce8\u610f\u529b\u6b8b\u5dee\uff08MSAR\uff09\u662f\u5bf9 AttnRes \u7684\u6269\u5c55\uff0c\u589e\u5f3a\u4e86\u591a\u5934\u6df1\u5ea6\u6ce8\u610f\u529b\u7684\u673a\u5236\uff0c\u6027\u80fd\u63d0\u5347\u663e\u8457\uff0c\u989d\u5916\u5f00\u9500\u5f88\u5c0f\u3002</li>\n    <li>MSAR \u901a\u8fc7\u591a\u5c3a\u5ea6\u56e0\u679c\u5377\u79ef\u5f15\u5165\u6d41\u7684\u591a\u6837\u6027\uff0c\u4f7f\u4e0d\u540c\u7684\u5934\u80fd\u591f\u901a\u8fc7\u4e0d\u540c\u7684\u4e0a\u4e0b\u6587\u89c6\u89d2\u68c0\u7d22\u5386\u53f2\u8868\u793a\u3002</li>\n    <li>\u68c0\u7d22\u7684\u6d41\u901a\u8fc7\u8f7b\u91cf\u7ea7\u81ea\u9002\u5e94\u6df7\u5408\u7ec4\u5408\uff0c\u751f\u6210\u5355\u6d41\u5c42\u8f93\u5165\uff0c\u652f\u6301\u591a\u6d41\u8ba1\u7b97\u800c\u65e0\u9700\u6301\u7eed\u5b58\u50a8\u6216\u901a\u4fe1\u3002</li>\n    <li>\u5728\u6240\u6709 12 \u4e2a\u4e0b\u6e38\u57fa\u51c6\u6d4b\u8bd5\u4e2d\uff0cMSAR \u7684\u8868\u73b0\u4f18\u4e8e\u4e4b\u524d\u7684\u6b8b\u5dee\u53d8\u4f53\uff0c\u5e76\u5728\u8ba1\u7b97\u901f\u5ea6\u4e0a\u5b9e\u73b0\u4e86\u663e\u8457\u52a0\u901f\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Attention Residuals (AttnRes) allows for flexible data retrieval in neural networks by using a single-stream softmax attention method.</li>\n    <li>Multi-Stream Attention Residuals (MSAR) is an advanced version that improves on AttnRes by using multi-head attention for deeper network layers.</li>\n    <li>MSAR uses multi-scale causal convolutions to ensure different attention heads can access various historical data while maintaining the original data's integrity.</li>\n    <li>It combines these different data streams efficiently without needing extra storage or complex communication between them.</li>\n    <li>MSAR shows better performance on multiple benchmarks, offering faster computation speeds compared to other residual connection methods.</li>\n</ul>"}, "publishedAt": "2026-10-08T20:00:00.000Z", "title": "Multi-Stream Attention Residuals", "summary": "Attention Residuals (AttnRes) enables content-dependent retrieval over network depth, which can be viewed as single-stream softmax attention along the depth axis. Inspired by the success of multi-head attention along the sequence axis, we introduce Multi-Stream Attention Residuals (MSAR), an extension of AttnRes that generalizes this mechanism to multi-head depth attention, yielding substantial performance gains with minimal additional overhead. MSAR draws stream diversity from sequence context through multi-scale causal convolutions, allowing different heads to retrieve historical representations through distinct contextual views while preserving the integrity of the hidden representation. The retrieved streams are combined through lightweight adaptive mixing to generate the single-stream layer input. By retaining single-stream sources and expanding them on demand, MSAR supports multi-stream computation without requiring persistent multi-stream storage or communication. Across all 12 downstream benchmarks at the 18B and 28B MoE scales, MSAR consistently outperforms prior residual variants, including standard residual connections, manifold-constrained Hyper-Connections (mHC), and AttnRes. Scaling-law experiments yield an iso-loss compute speedup of 1.58times over the standard residual baseline, compared with 1.35times for AttnRes and 1.30times for mHC. These results make MSAR a promising residual architecture for large-scale pre-training.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.13630.png", "numComments": 1, "submittedBy": {"_id": "64452110e1fd8d65b2790bfc", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/64452110e1fd8d65b2790bfc/3NIsQFV9X44X88aLXR6eE.jpeg", "fullname": "Xiaohan Qin (SJTU) & (SII)", "name": "galaxy-1", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 3, "isUserFollowing": false}, "organization": {"_id": "63e5ef7bf2e9a8f22c515654", "name": "SJTU", "fullname": "Shanghai Jiao Tong University", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/1676013394657-63e5ee22b6a40bf941da0928.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.13395", "authors": [{"_id": "6acc3a880ee6ff34004fdd6c", "name": "Chengyi Yang", "hidden": false}, {"_id": "6acc3a880ee6ff34004fdd6d", "name": "Renxu Bao", "hidden": false}, {"_id": "6acc3a880ee6ff34004fdd6e", "name": "Jue Hou", "hidden": false}, {"_id": "6acc3a880ee6ff34004fdd6f", "name": "Zongpei Teng", "hidden": false}, {"_id": "6acc3a880ee6ff34004fdd70", "name": "Ziheng Wang", "hidden": false}, {"_id": "6acc3a880ee6ff34004fdd71", "name": "Yujie Lin", "hidden": false}, {"_id": "6acc3a880ee6ff34004fdd72", "name": "Chengsong Huang", "hidden": false}, {"_id": "6acc3a880ee6ff34004fdd73", "name": "Junnan Zhu", "hidden": false}, {"_id": "6acc3a880ee6ff34004fdd74", "name": "Delai Qiu", "hidden": false}, {"_id": "6acc3a880ee6ff34004fdd75", "name": "Yining Wang", "hidden": false}, {"_id": "6acc3a880ee6ff34004fdd76", "name": "Shengping Liu", "hidden": false}, {"_id": "6acc3a880ee6ff34004fdd77", "name": "Fei Long", "hidden": false}, {"_id": "6acc3a880ee6ff34004fdd78", "name": "Jinsong Su", "hidden": false}], "publishedAt": "2026-10-09T00:00:00.000Z", "submittedOnDailyAt": "2026-10-12T00:00:00.000Z", "title": "ProgramGym: Scaling Training Environments for Long-Horizon Program Reproduction Agents", "submittedOnDailyBy": {"_id": "681ab9d3d7dbd87287875667", "avatarUrl": "/avatars/1a2785d7a250c4988b1c1c5cc78e53fc.svg", "isPro": false, "fullname": "ChengyiYang", "user": "ChengyiYang", "type": "user", "name": "ChengyiYang"}, "summary": "Coding agents are increasingly used to build programs from scratch as software engineers do rather than to resolve issues within a repository or to generate a repository from a given requirements document. However, scalable verifiable training environments that force agents to discover what is required and to decide how the system should be designed remain scarce. Moreover, existing agent workflows also cannot sustain long-horizon development in which the agent explores the reference program before implementation. To address these challenges, we introduce ProgramGym, a framework consisting of Program-Env and Program-Agent for scalable training environments of long-horizon program reproduction agents. Specifically, Program-Env constructs verifiable training environments from repositories through a feedback-driven loop that repairs runtime sandbox builds and the quality of black-box tests. Using this novel pipeline, we obtain 1,648 training environments spanning C, C++, Go, and Rust. Program-Agent combines a role-isolated workflow of analysis, implementation, and review with revision management for compilation checks and failure recovery. Experiments on ProgramBench show that both Program-Env and Program-Agent improve performance on program reproduction. Fine-tuning on trajectories with these constructed environments raises the performance of Qwen3.8-27B from 34.87% to 42.84%. Program-Agent further raises the base and SFT models to 55.71% and 56.25%, both exceeding some flagship models. We will release the ProgramGym to support further research on coding agents that build programs from scratch.", "upvotes": 27, "discussionId": "6acc3a890ee6ff34004fdd79", "projectPage": "https://programgym.github.io/", "githubRepo": "https://github.com/Acm1011/ProgramGym", "githubRepoAddedBy": "user", "githubStars": 1, "organization": {"_id": "6a71a45f584d1d33007a4f56", "name": "ProgramGym", "fullname": "ProgramGym", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/68676f9642df3fdd87e5d368/PZQwVyqoKPrpaVSqYk1E7.png"}, "summary_zh": "<ul>\n    <li>\u7a0b\u5e8f\u4ee3\u7406\uff08coding agents\uff09\u8d8a\u6765\u8d8a\u591a\u5730\u7528\u4e8e\u4ece\u5934\u6784\u5efa\u7a0b\u5e8f\uff0c\u800c\u4e0d\u4ec5\u4ec5\u662f\u89e3\u51b3\u5df2\u6709\u95ee\u9898\u3002</li>\n    <li>\u76ee\u524d\u7f3a\u4e4f\u53ef\u6269\u5c55\u7684\u3001\u53ef\u9a8c\u8bc1\u7684\u8bad\u7ec3\u73af\u5883\uff0c\u5c24\u5176\u662f\u5728\u957f\u65f6\u95f4\u5f00\u53d1\u4e2d\u3002</li>\n    <li>\u6211\u4eec\u63d0\u51fa\u4e86ProgramGym\u6846\u67b6\uff0c\u5305\u62ecProgram-Env\u548cProgram-Agent\uff0c\u65e8\u5728\u652f\u6301\u957f\u671f\u7a0b\u5e8f\u590d\u5236\u4ee3\u7406\u7684\u8bad\u7ec3\u3002</li>\n    <li>Program-Env\u901a\u8fc7\u53cd\u9988\u5faa\u73af\u6784\u5efa\u53ef\u9a8c\u8bc1\u7684\u8bad\u7ec3\u73af\u5883\uff0c\u6db5\u76d6\u591a\u79cd\u7f16\u7a0b\u8bed\u8a00\u3002</li>\n    <li>\u5b9e\u9a8c\u8868\u660e\uff0cProgramGym\u663e\u8457\u63d0\u9ad8\u4e86\u7a0b\u5e8f\u590d\u5236\u7684\u6027\u80fd\uff0c\u5e76\u5c06\u6a21\u578b\u8868\u73b0\u63d0\u5347\u5230\u8d85\u8fc7\u4e00\u4e9b\u9886\u5148\u6a21\u578b\u7684\u6c34\u5e73\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Coding agents are becoming more common for creating programs from the ground up, similar to how human software engineers work.</li>\n    <li>There is a need for better training environments that help these agents learn what to build and how to design systems effectively.</li>\n    <li>The new framework called ProgramGym includes a training environment (Program-Env) and an agent (Program-Agent), designed for long-term program development.</li>\n    <li>Program-Env creates 1,648 training environments for programming languages like C, C++, Go, and Rust, improving the quality of program testing.</li>\n    <li>Tests show that using ProgramGym significantly boosts the performance of coding agents, with some models outperforming leading existing models.</li>\n</ul>"}, "publishedAt": "2026-10-08T20:00:00.000Z", "title": "ProgramGym: Scaling Training Environments for Long-Horizon Program Reproduction Agents", "summary": "Coding agents are increasingly used to build programs from scratch as software engineers do rather than to resolve issues within a repository or to generate a repository from a given requirements document. However, scalable verifiable training environments that force agents to discover what is required and to decide how the system should be designed remain scarce. Moreover, existing agent workflows also cannot sustain long-horizon development in which the agent explores the reference program before implementation. To address these challenges, we introduce ProgramGym, a framework consisting of Program-Env and Program-Agent for scalable training environments of long-horizon program reproduction agents. Specifically, Program-Env constructs verifiable training environments from repositories through a feedback-driven loop that repairs runtime sandbox builds and the quality of black-box tests. Using this novel pipeline, we obtain 1,648 training environments spanning C, C++, Go, and Rust. Program-Agent combines a role-isolated workflow of analysis, implementation, and review with revision management for compilation checks and failure recovery. Experiments on ProgramBench show that both Program-Env and Program-Agent improve performance on program reproduction. Fine-tuning on trajectories with these constructed environments raises the performance of Qwen3.8-27B from 34.87% to 42.84%. Program-Agent further raises the base and SFT models to 55.71% and 56.25%, both exceeding some flagship models. We will release the ProgramGym to support further research on coding agents that build programs from scratch.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.13395.png", "numComments": 1, "submittedBy": {"_id": "681ab9d3d7dbd87287875667", "avatarUrl": "/avatars/1a2785d7a250c4988b1c1c5cc78e53fc.svg", "fullname": "ChengyiYang", "name": "ChengyiYang", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "isUserFollowing": false}, "organization": {"_id": "6a71a45f584d1d33007a4f56", "name": "ProgramGym", "fullname": "ProgramGym", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/68676f9642df3fdd87e5d368/PZQwVyqoKPrpaVSqYk1E7.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.12299", "authors": [{"_id": "6ac8603a4364a3d18a5cc821", "name": "Dahyun Chung", "hidden": false}, {"_id": "6ac8603a4364a3d18a5cc822", "name": "Siyoon Jin", "hidden": false}, {"_id": "6ac8603a4364a3d18a5cc823", "name": "Hyunwook Choi", "hidden": false}, {"_id": "6ac8603a4364a3d18a5cc824", "name": "Honggyu An", "hidden": false}, {"_id": "6ac8603a4364a3d18a5cc825", "name": "Junyoung Seo", "hidden": false}, {"_id": "6ac8603a4364a3d18a5cc826", "name": "Hyunsung Kim", "hidden": false}, {"_id": "6ac8603a4364a3d18a5cc827", "name": "Seung Wook Kim", "hidden": false}, {"_id": "6ac8603a4364a3d18a5cc828", "name": "Seungryong Kim", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/66f7a013380c9f89971c078d/ytSOECv7KP7z0f6FWQ4HL.mp4"], "publishedAt": "2026-10-08T00:00:00.000Z", "submittedOnDailyAt": "2026-10-09T00:00:00.000Z", "title": "Multi-Agent Egocentric World Model with Fine-Grained Embodied Interaction", "submittedOnDailyBy": {"_id": "66f7a013380c9f89971c078d", "avatarUrl": "/avatars/a01d393575aacd7f74a12c22fe43a30d.svg", "isPro": true, "fullname": "HyunWook Choi", "user": "enrue1893", "type": "user", "name": "enrue1893"}, "summary": "Egocentric world models predict first-person observations conditioned on an agent's actions, but most focus on a single agent. Real embodied settings often involve multiple agents that act and interact within a shared environment. Existing multi-agent world models rely on coarse actions like locomotion, camera control, or discrete commands, leaving fine-grained embodied interactions underexplored. We formulate multi-agent egocentric world modeling as synchronized ego-stream generation for multiple agents interacting through fine-grained actions in a shared world. This requires cross-view action consistency, shared-environment consistency, and consistent propagation of interaction-induced state updates. We propose Multi-agent Egocentric World Model (ME-World), which jointly denoises multiple ego streams in a shared token sequence, conditions each stream on all agents' target-view poses, and grounds generation with shared environment memory. We train and evaluate on real and synthetic multi-agent data and introduce shared-world consistency metrics for environment, update, and identity consistency. Experiments show ME-World improves shared-world consistency, action control, identity preservation, and video quality over existing methods.", "upvotes": 27, "discussionId": "6ac8603a4364a3d18a5cc829", "projectPage": "https://cvlab-kaist.github.io/ME-World/", "githubRepo": "https://github.com/cvlab-kaist/ME-World", "githubRepoAddedBy": "user", "githubStars": 14, "organization": {"_id": "6475760c33192631bad2bb38", "name": "kaist-ai", "fullname": "KAIST AI", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/6469949654873f0043b09c22/aaZFiyXe1qR-Dmy_xq67m.png"}, "summary_zh": "<ul>\n    <li>\u73b0\u6709\u7684\u81ea\u6211\u4e2d\u5fc3\u4e16\u754c\u6a21\u578b\u4e3b\u8981\u5173\u6ce8\u5355\u4e2a\u4ee3\u7406\uff0c\u4f46\u771f\u5b9e\u73af\u5883\u4e2d\u901a\u5e38\u6709\u591a\u4e2a\u4ee3\u7406\u76f8\u4e92\u4f5c\u7528\u3002</li>\n    <li>\u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u79cd\u591a\u4ee3\u7406\u81ea\u6211\u4e2d\u5fc3\u4e16\u754c\u6a21\u578b\uff08ME-World\uff09\uff0c\u53ef\u4ee5\u5904\u7406\u591a\u4e2a\u4ee3\u7406\u5728\u5171\u4eab\u73af\u5883\u4e2d\u7684\u7ec6\u7c92\u5ea6\u4e92\u52a8\u3002</li>\n    <li>\u8be5\u6a21\u578b\u9700\u8981\u786e\u4fdd\u4ee3\u7406\u4e4b\u95f4\u7684\u52a8\u4f5c\u4e00\u81f4\u6027\u548c\u73af\u5883\u4e00\u81f4\u6027\uff0c\u5e76\u6709\u6548\u4f20\u64ad\u4e92\u52a8\u5f15\u8d77\u7684\u72b6\u6001\u66f4\u65b0\u3002</li>\n    <li>ME-World\u901a\u8fc7\u8054\u5408\u53bb\u566a\u591a\u4e2a\u81ea\u6211\u6d41\uff0c\u4f7f\u7528\u5171\u4eab\u73af\u5883\u8bb0\u5fc6\u6765\u589e\u5f3a\u751f\u6210\u6548\u679c\u3002</li>\n    <li>\u5b9e\u9a8c\u8868\u660e\uff0cME-World\u5728\u5171\u4eab\u4e16\u754c\u4e00\u81f4\u6027\u3001\u52a8\u4f5c\u63a7\u5236\u3001\u8eab\u4efd\u4fdd\u7559\u548c\u89c6\u9891\u8d28\u91cf\u65b9\u9762\u4f18\u4e8e\u73b0\u6709\u65b9\u6cd5\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Most world models predict actions for a single agent, but real-life scenarios often involve multiple agents interacting together.</li>\n    <li>Current models focus on basic actions and don't address detailed interactions between agents.</li>\n    <li>The proposed Multi-agent Egocentric World Model (ME-World) generates synchronized observations for multiple agents in a shared environment using fine-grained interactions.</li>\n    <li>ME-World ensures consistency in actions and environment updates while tracking the identity of agents.</li>\n    <li>Tests show that ME-World outperforms previous methods in terms of consistency, control, identity tracking, and video quality. </li>\n</ul>"}, "publishedAt": "2026-10-07T20:00:00.000Z", "title": "Multi-Agent Egocentric World Model with Fine-Grained Embodied Interaction", "summary": "Egocentric world models predict first-person observations conditioned on an agent's actions, but most focus on a single agent. Real embodied settings often involve multiple agents that act and interact within a shared environment. Existing multi-agent world models rely on coarse actions like locomotion, camera control, or discrete commands, leaving fine-grained embodied interactions underexplored. We formulate multi-agent egocentric world modeling as synchronized ego-stream generation for multiple agents interacting through fine-grained actions in a shared world. This requires cross-view action consistency, shared-environment consistency, and consistent propagation of interaction-induced state updates. We propose Multi-agent Egocentric World Model (ME-World), which jointly denoises multiple ego streams in a shared token sequence, conditions each stream on all agents' target-view poses, and grounds generation with shared environment memory. We train and evaluate on real and synthetic multi-agent data and introduce shared-world consistency metrics for environment, update, and identity consistency. Experiments show ME-World improves shared-world consistency, action control, identity preservation, and video quality over existing methods.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/66f7a013380c9f89971c078d/ytSOECv7KP7z0f6FWQ4HL.mp4"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.12299.png", "numComments": 1, "submittedBy": {"_id": "66f7a013380c9f89971c078d", "avatarUrl": "/avatars/a01d393575aacd7f74a12c22fe43a30d.svg", "fullname": "HyunWook Choi", "name": "enrue1893", "type": "user", "isPro": true, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 1, "isUserFollowing": false}, "organization": {"_id": "6475760c33192631bad2bb38", "name": "kaist-ai", "fullname": "KAIST AI", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/6469949654873f0043b09c22/aaZFiyXe1qR-Dmy_xq67m.png"}, "isAuthorParticipating": false}],
    "month": [{"paper": {"id": "2609.17488", "authors": [{"_id": "6aaa0287f6668522fbb08046", "user": {"_id": "63440a1be01a38440ef25daa", "avatarUrl": "/avatars/622e8ca69f1867be7932d03b91eaf6e7.svg", "isPro": false, "fullname": "Xingxuan Zhang", "user": "xuange", "type": "user", "name": "xuange"}, "name": "Xingxuan Zhang", "status": "claimed_verified", "statusLastChangedAt": "2026-09-16T16:45:04.225Z", "hidden": false}, {"_id": "6aaa0287f6668522fbb08047", "name": "Gang Ren", "hidden": false}, {"_id": "6aaa0287f6668522fbb08048", "name": "Hao Yuan", "hidden": false}, {"_id": "6aaa0287f6668522fbb08049", "name": "Hao Zou", "hidden": false}, {"_id": "6aaa0287f6668522fbb0804a", "name": "Hongze Tan", "hidden": false}, {"_id": "6aaa0287f6668522fbb0804b", "name": "Hui Wang", "hidden": false}, {"_id": "6aaa0287f6668522fbb0804c", "name": "Jianhao Song", "hidden": false}, {"_id": "6aaa0287f6668522fbb0804d", "name": "Jiansheng Li", "hidden": false}, {"_id": "6aaa0287f6668522fbb0804e", "name": "Jiayao Zhang", "hidden": false}, {"_id": "6aaa0287f6668522fbb0804f", "name": "Jinghan Zhang", "hidden": false}, {"_id": "6aaa0287f6668522fbb08050", "name": "Kaifang Li", "hidden": false}, {"_id": "6aaa0287f6668522fbb08051", "name": "Lang Mo", "hidden": false}, {"_id": "6aaa0287f6668522fbb08052", "name": "Li Mao", "hidden": false}, {"_id": "6aaa0287f6668522fbb08053", "name": "Mingchao Hao", "hidden": false}, {"_id": "6aaa0287f6668522fbb08054", "name": "Nuo Xu", "hidden": false}, {"_id": "6aaa0287f6668522fbb08055", "name": "Rui Ding", "hidden": false}, {"_id": "6aaa0287f6668522fbb08056", "name": "Ruiji Zhang", "hidden": false}, {"_id": "6aaa0287f6668522fbb08057", "name": "Shuyang Li", "hidden": false}, {"_id": "6aaa0287f6668522fbb08058", "name": "Siyu Mei", "hidden": false}, {"_id": "6aaa0287f6668522fbb08059", "name": "Tianyang Zhang", "hidden": false}, {"_id": "6aaa0287f6668522fbb0805a", "name": "Weiyang Mu", "hidden": false}, {"_id": "6aaa0287f6668522fbb0805b", "name": "Yancheng Dong", "hidden": false}, {"_id": "6aaa0287f6668522fbb0805c", "name": "Yongxian Wei", "hidden": false}, {"_id": "6aaa0287f6668522fbb0805d", "name": "Yuan Xue", "hidden": false}, {"_id": "6aaa0287f6668522fbb0805e", "name": "Yuanrui Wang", "hidden": false}, {"_id": "6aaa0287f6668522fbb0805f", "name": "Yue He", "hidden": false}, {"_id": "6aaa0287f6668522fbb08060", "name": "Zijia Yang", "hidden": false}, {"_id": "6aaa0287f6668522fbb08061", "name": "Ziyun Li", "hidden": false}, {"_id": "6aaa0287f6668522fbb08062", "name": "Dongzhe Li", "hidden": false}, {"_id": "6aaa0287f6668522fbb08063", "name": "Fuqiang Wang", "hidden": false}, {"_id": "6aaa0287f6668522fbb08064", "name": "Jiandong Liu", "hidden": false}, {"_id": "6aaa0287f6668522fbb08065", "name": "Jiawei Chen", "hidden": false}, {"_id": "6aaa0287f6668522fbb08066", "name": "Jiaxin Du", "hidden": false}, {"_id": "6aaa0287f6668522fbb08067", "name": "Kaijie Cheng", "hidden": false}, {"_id": "6aaa0287f6668522fbb08068", "name": "Kehan Li", "hidden": false}, {"_id": "6aaa0287f6668522fbb08069", "name": "Lei Sun", "hidden": false}, {"_id": "6aaa0287f6668522fbb0806a", "name": "Linjun Zhou", "hidden": false}, {"_id": "6aaa0287f6668522fbb0806b", "name": "Ningbo Dai", "hidden": false}, {"_id": "6aaa0287f6668522fbb0806c", "name": "Qi Wang", "hidden": false}, {"_id": "6aaa0287f6668522fbb0806d", "name": "Renzhe Xu", "hidden": false}, {"_id": "6aaa0287f6668522fbb0806e", "name": "Shaoxing Du", "hidden": false}, {"_id": "6aaa0287f6668522fbb0806f", "name": "Shumeng Yang", "hidden": false}, {"_id": "6aaa0287f6668522fbb08070", "name": "Wang Lu", "hidden": false}, {"_id": "6aaa0287f6668522fbb08071", "name": "Wenjing Chu", "hidden": false}, {"_id": "6aaa0287f6668522fbb08072", "name": "Xiannan Huang", "hidden": false}, {"_id": "6aaa0287f6668522fbb08073", "name": "Xiaoyu Lin", "hidden": false}, {"_id": "6aaa0287f6668522fbb08074", "name": "Xing Ai", "hidden": false}, {"_id": "6aaa0287f6668522fbb08075", "name": "Xinyan Han", "hidden": false}, {"_id": "6aaa0287f6668522fbb08076", "name": "Xuanyue Li", "hidden": false}, {"_id": "6aaa0287f6668522fbb08077", "name": "Xuanyue Su", "hidden": false}, {"_id": "6aaa0287f6668522fbb08078", "name": "Xukun Zhang", "hidden": false}, {"_id": "6aaa0287f6668522fbb08079", "name": "Yan Lu", "hidden": false}, {"_id": "6aaa0287f6668522fbb0807a", "name": "Yaxin Zhang", "hidden": false}, {"_id": "6aaa0287f6668522fbb0807b", "name": "Yi Qin", "hidden": false}, {"_id": "6aaa0287f6668522fbb0807c", "name": "Yifei Huang", "hidden": false}, {"_id": "6aaa0287f6668522fbb0807d", "name": "Yihan Xu", "hidden": false}, {"_id": "6aaa0287f6668522fbb0807e", "name": "Yongle Lv", "hidden": false}, {"_id": "6aaa0287f6668522fbb0807f", "name": "Yuanyuan Jiang", "hidden": false}, {"_id": "6aaa0287f6668522fbb08080", "name": "Yushan Han", "hidden": false}, {"_id": "6aaa0287f6668522fbb08081", "name": "Peng Cui", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/63440a1be01a38440ef25daa/82Td574Ji7ShkZWIF58uf.mp4"], "publishedAt": "2026-09-15T00:00:00.000Z", "submittedOnDailyAt": "2026-09-17T00:00:00.000Z", "title": "LimiX-2: A Contextual Mechanism Network Towards General Structured-Data Intelligence", "submittedOnDailyBy": {"_id": "63440a1be01a38440ef25daa", "avatarUrl": "/avatars/622e8ca69f1867be7932d03b91eaf6e7.svg", "isPro": false, "fullname": "Xingxuan Zhang", "user": "xuange", "type": "user", "name": "xuange"}, "summary": "We introduce LimiX-2, a new model in the LimiX family, developed through model and data scaling guided by our previously established scaling laws. LimiX-2 adopts the Contextual Mechanism Networks (CMNs) paradigm and is pretrained with Context-Conditional Masked Modeling (CCMM). CMNs shifts the organizing principle of in-context learning from target-centric prediction to mechanism-oriented joint modeling. Rather than centering the network on the p(y mid x, D_{context}) objective of conventional tabular PFNs, it is designed around learning p(x, y mid D_{context}), a context-dependent representation of the joint structure underlying data generation. Pretraining uses synthetic datasets generated by structural causal models (SCMs) spanning diverse graph structures, functional mechanisms, and observation processes. Evaluations on TabArena, TALENT, and BCCO show that LimiX-2 outperforms current dataset-specific models and tabular foundation models. Beyond predictive performance, the CMN paradigm also promotes causal awareness in LimiX-2: its feature attention encodes direct causal relationships, enabling accurate causal skeleton recovery.", "upvotes": 126, "discussionId": "6aaa0288f6668522fbb08082", "projectPage": "https://www.limix.ai/", "githubRepo": "https://github.com/limix-ldm-ai/LimiX", "githubRepoAddedBy": "user", "githubStars": 4195, "organization": {"_id": "6911d3dc57d393d3cfe628bf", "name": "stable-ai", "fullname": "Stable AI", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/68aa772042ec888900da6a6b/ykANVIVEnhVZ1fdsEz7BQ.png"}, "summary_zh": "<ul>\n    <li>\u4ecb\u7ecd\u4e86LimiX-2\uff0c\u8fd9\u662fLimiX\u7cfb\u5217\u7684\u65b0\u6a21\u578b\uff0c\u57fa\u4e8e\u4e4b\u524d\u7684\u7f29\u653e\u89c4\u5f8b\u8fdb\u884c\u6a21\u578b\u548c\u6570\u636e\u7684\u6269\u5c55\u3002</li>\n    <li>LimiX-2\u91c7\u7528\u4e86\u4e0a\u4e0b\u6587\u673a\u5236\u7f51\u7edc\uff08CMNs\uff09\u65b9\u6cd5\uff0c\u5e76\u901a\u8fc7\u4e0a\u4e0b\u6587\u6761\u4ef6\u63a9\u7801\u5efa\u6a21\uff08CCMM\uff09\u8fdb\u884c\u9884\u8bad\u7ec3\u3002</li>\n    <li>CMNs\u5c06\u4e0a\u4e0b\u6587\u5b66\u4e60\u7684\u91cd\u70b9\u4ece\u76ee\u6807\u9884\u6d4b\u8f6c\u5411\u673a\u5236\u5bfc\u5411\u7684\u8054\u5408\u5efa\u6a21\u3002</li>\n    <li>\u9884\u8bad\u7ec3\u4f7f\u7528\u7531\u7ed3\u6784\u56e0\u679c\u6a21\u578b\uff08SCMs\uff09\u751f\u6210\u7684\u5408\u6210\u6570\u636e\u96c6\uff0c\u6db5\u76d6\u591a\u79cd\u56fe\u7ed3\u6784\u548c\u89c2\u5bdf\u8fc7\u7a0b\u3002</li>\n    <li>\u5728\u591a\u4e2a\u8bc4\u4f30\u5e73\u53f0\u4e0a\uff0cLimiX-2\u7684\u8868\u73b0\u8d85\u8fc7\u4e86\u73b0\u6709\u7684\u6570\u636e\u96c6\u7279\u5b9a\u6a21\u578b\u548c\u8868\u683c\u57fa\u7840\u6a21\u578b\uff0c\u5e76\u4e14\u589e\u5f3a\u4e86\u56e0\u679c\u610f\u8bc6\u3002 </li>\n</ul>", "summary_simple": "<ul>\n    <li>LimiX-2 is a new model that improves upon previous models in the LimiX family, using advanced scaling methods.</li>\n    <li>It uses a new approach called Contextual Mechanism Networks (CMNs) to improve how it learns from data.</li>\n    <li>The model is trained on synthetic datasets created from various structural causal models to enhance its understanding of data relationships.</li>\n    <li>LimiX-2 outperforms existing models on several evaluation benchmarks, showing better predictive capabilities.</li>\n    <li>It also has improved causal awareness, meaning it can identify and recover causal relationships in data more effectively.</li>\n</ul>"}, "publishedAt": "2026-09-14T20:00:00.000Z", "title": "LimiX-2: A Contextual Mechanism Network Towards General Structured-Data Intelligence", "summary": "We introduce LimiX-2, a new model in the LimiX family, developed through model and data scaling guided by our previously established scaling laws. LimiX-2 adopts the Contextual Mechanism Networks (CMNs) paradigm and is pretrained with Context-Conditional Masked Modeling (CCMM). CMNs shifts the organizing principle of in-context learning from target-centric prediction to mechanism-oriented joint modeling. Rather than centering the network on the p(y mid x, D_{context}) objective of conventional tabular PFNs, it is designed around learning p(x, y mid D_{context}), a context-dependent representation of the joint structure underlying data generation. Pretraining uses synthetic datasets generated by structural causal models (SCMs) spanning diverse graph structures, functional mechanisms, and observation processes. Evaluations on TabArena, TALENT, and BCCO show that LimiX-2 outperforms current dataset-specific models and tabular foundation models. Beyond predictive performance, the CMN paradigm also promotes causal awareness in LimiX-2: its feature attention encodes direct causal relationships, enabling accurate causal skeleton recovery.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/63440a1be01a38440ef25daa/82Td574Ji7ShkZWIF58uf.mp4"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2609.17488.png", "numComments": 4, "submittedBy": {"_id": "63440a1be01a38440ef25daa", "avatarUrl": "/avatars/622e8ca69f1867be7932d03b91eaf6e7.svg", "fullname": "Xingxuan Zhang", "name": "xuange", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 3, "isUserFollowing": false}, "organization": {"_id": "6911d3dc57d393d3cfe628bf", "name": "stable-ai", "fullname": "Stable AI", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/68aa772042ec888900da6a6b/ykANVIVEnhVZ1fdsEz7BQ.png"}, "isAuthorParticipating": true}, {"paper": {"id": "2609.31620", "authors": [{"_id": "6ab9c761356575bf2ab7a854", "user": {"_id": "667230de876f9f27d6b097ea", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/667230de876f9f27d6b097ea/hhz4nfTUdAAMIPXw3A342.jpeg", "isPro": false, "fullname": "Hongyang Du", "user": "Hongyang-Du", "type": "user", "name": "Hongyang-Du"}, "name": "Hongyang Du", "status": "claimed_verified", "statusLastChangedAt": "2026-09-28T14:59:32.932Z", "hidden": false}, {"_id": "6ab9c761356575bf2ab7a855", "name": "Yunfei Xie", "hidden": false}, {"_id": "6ab9c761356575bf2ab7a856", "name": "Junjie Ye", "hidden": false}, {"_id": "6ab9c761356575bf2ab7a857", "name": "Jiawei Yang", "hidden": false}, {"_id": "6ab9c761356575bf2ab7a858", "name": "Xiaoyan Cong", "hidden": false}, {"_id": "6ab9c761356575bf2ab7a859", "name": "Haodong Zhang", "hidden": false}, {"_id": "6ab9c761356575bf2ab7a85a", "name": "Yongchao Huang", "hidden": false}, {"_id": "6ab9c761356575bf2ab7a85b", "user": {"_id": "6530b49cb50285938b63d6a5", "avatarUrl": "/avatars/fc5e6b52693b35ae0948265686b56b05.svg", "isPro": false, "fullname": "Haiyu Wu", "user": "BooBooWu", "type": "user", "name": "BooBooWu"}, "name": "Haiyu Wu", "status": "claimed_verified", "statusLastChangedAt": "2026-09-28T08:45:05.268Z", "hidden": false}, {"_id": "6ab9c761356575bf2ab7a85c", "name": "Zongxia Li", "hidden": false}, {"_id": "6ab9c761356575bf2ab7a85d", "name": "Shihang Gui", "hidden": false}, {"_id": "6ab9c761356575bf2ab7a85e", "name": "Dawei Liu", "hidden": false}, {"_id": "6ab9c761356575bf2ab7a85f", "name": "Runhao Li", "hidden": false}, {"_id": "6ab9c761356575bf2ab7a860", "name": "Jingcheng Ni", "hidden": false}, {"_id": "6ab9c761356575bf2ab7a861", "name": "Chen Wei", "hidden": false}, {"_id": "6ab9c761356575bf2ab7a862", "name": "Randall Balestriero", "hidden": false}, {"_id": "6ab9c761356575bf2ab7a863", "name": "Yue Wang", "hidden": false}], "publishedAt": "2026-09-25T00:00:00.000Z", "submittedOnDailyAt": "2026-09-28T00:00:00.000Z", "title": "FuseReg: Regularizing Layer Fusion Mitigates the Reconstruction-Generation Gap in Representation Autoencoders", "submittedOnDailyBy": {"_id": "667230de876f9f27d6b097ea", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/667230de876f9f27d6b097ea/hhz4nfTUdAAMIPXw3A342.jpeg", "isPro": false, "fullname": "Hongyang Du", "user": "Hongyang-Du", "type": "user", "name": "Hongyang-Du"}, "summary": "Representation autoencoders (RAEs) reuse features from a pretrained visual encoder as reconstruction and diffusion latents, integrating strong visual representations into image generation. However, RAEs still need to decide which encoder layers form the shared latent space for the generator and pixel decoder. This choice involves a trade-off. Shallower layers tend to preserve fine pixel details better, while deeper layers tend to yield better generation metrics. A fixed heuristic layer fusion therefore couples two stages that benefit from different information. We introduce FuseReg, which replaces heuristic feature selection with training over random subsets of encoder layers. We theoretically analyze the underlying mechanism: subset sampling explicitly penalizes sensitivity to cross-layer disagreement. On ImageNet-256 with DINOv3-L, a single FuseReg decoder reconstructs from full, sparse, and single-layer fusions without retraining, achieving higher PSNR than decoders specialized to fixed fusions. This flexibility also benefits generation: decoder replacement alone reduces unguided gFID by 27% with an unchanged RAEv2 DiT-XL generator. The same regularization principle extends to diffusion training, with joint regularization of both stages reducing unguided gFID by 29% on DiT-Base. These results show that training downstream models for layer-fusion robustness narrows the reconstruction-generation gap without modifying the pretrained encoder.", "upvotes": 116, "discussionId": "6ab9c762356575bf2ab7a864", "projectPage": "https://hongyang-du.github.io/FuseReg/", "githubRepo": "https://github.com/Hongyang-Du/FuseReg", "githubRepoAddedBy": "user", "githubStars": 13, "organization": {"_id": "66eb6cd5d10fdbc179fa6a20", "name": "USC-PSI-Lab", "fullname": "USC Physical Superintelligence (PSI) Lab", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/6552aa185138c382d3228761/vXpouU0ojcyCalAB0bgde.png"}, "summary_zh": "<ul>\n    <li>\u8868\u793a\u81ea\u7f16\u7801\u5668\uff08RAEs\uff09\u5229\u7528\u9884\u8bad\u7ec3\u7684\u89c6\u89c9\u7f16\u7801\u5668\u7279\u5f81\u6765\u8fdb\u884c\u56fe\u50cf\u751f\u6210\u3002</li>\n    <li>\u9009\u62e9\u5171\u4eab\u6f5c\u5728\u7a7a\u95f4\u7684\u7f16\u7801\u5668\u5c42\u6d89\u53ca\u6743\u8861\uff1a\u6d45\u5c42\u4fdd\u7559\u7ec6\u8282\uff0c\u6df1\u5c42\u751f\u6210\u6548\u679c\u66f4\u597d\u3002</li>\n    <li>FuseReg \u901a\u8fc7\u8bad\u7ec3\u968f\u673a\u9009\u62e9\u7684\u7f16\u7801\u5668\u5c42\u66ff\u4ee3\u56fa\u5b9a\u7684\u542f\u53d1\u5f0f\u7279\u5f81\u9009\u62e9\u3002</li>\n    <li>\u5728 ImageNet-256 \u4e0a\uff0cFuseReg \u89e3\u7801\u5668\u5728\u4e0d\u540c\u878d\u5408\u65b9\u5f0f\u4e0b\u8868\u73b0\u66f4\u597d\uff0cPSNR \u9ad8\u4e8e\u4f20\u7edf\u89e3\u7801\u5668\u3002</li>\n    <li>\u8fd9\u79cd\u65b9\u6cd5\u8fd8\u6539\u5584\u4e86\u751f\u6210\u6548\u679c\uff0c\u964d\u4f4e\u4e86 unguided gFID\uff0c\u5e76\u4e14\u4e0d\u9700\u8981\u4fee\u6539\u9884\u8bad\u7ec3\u7684\u7f16\u7801\u5668\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Representation autoencoders (RAEs) use features from a pretrained visual encoder for image generation.</li>\n    <li>Choosing which layers of the encoder to use for generating images is a trade-off between detail and quality.</li>\n    <li>FuseReg is a new method that improves layer selection by training on random subsets, which helps avoid issues from mixed layer information.</li>\n    <li>This new method showed better image reconstruction and generation results without needing to retrain the encoder.</li>\n    <li>The approach also improves performance in diffusion training, further reducing generation gaps.</li>\n</ul>"}, "publishedAt": "2026-09-24T20:00:00.000Z", "title": "FuseReg: Regularizing Layer Fusion Mitigates the Reconstruction-Generation Gap in Representation Autoencoders", "summary": "Representation autoencoders (RAEs) reuse features from a pretrained visual encoder as reconstruction and diffusion latents, integrating strong visual representations into image generation. However, RAEs still need to decide which encoder layers form the shared latent space for the generator and pixel decoder. This choice involves a trade-off. Shallower layers tend to preserve fine pixel details better, while deeper layers tend to yield better generation metrics. A fixed heuristic layer fusion therefore couples two stages that benefit from different information. We introduce FuseReg, which replaces heuristic feature selection with training over random subsets of encoder layers. We theoretically analyze the underlying mechanism: subset sampling explicitly penalizes sensitivity to cross-layer disagreement. On ImageNet-256 with DINOv3-L, a single FuseReg decoder reconstructs from full, sparse, and single-layer fusions without retraining, achieving higher PSNR than decoders specialized to fixed fusions. This flexibility also benefits generation: decoder replacement alone reduces unguided gFID by 27% with an unchanged RAEv2 DiT-XL generator. The same regularization principle extends to diffusion training, with joint regularization of both stages reducing unguided gFID by 29% on DiT-Base. These results show that training downstream models for layer-fusion robustness narrows the reconstruction-generation gap without modifying the pretrained encoder.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2609.31620.png", "numComments": 3, "submittedBy": {"_id": "667230de876f9f27d6b097ea", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/667230de876f9f27d6b097ea/hhz4nfTUdAAMIPXw3A342.jpeg", "fullname": "Hongyang Du", "name": "Hongyang-Du", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "isUserFollowing": false}, "organization": {"_id": "66eb6cd5d10fdbc179fa6a20", "name": "USC-PSI-Lab", "fullname": "USC Physical Superintelligence (PSI) Lab", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/6552aa185138c382d3228761/vXpouU0ojcyCalAB0bgde.png"}, "isAuthorParticipating": true}, {"paper": {"id": "2609.19134", "authors": [{"_id": "6aab567a1d9cc4dec7962470", "name": "Hejia Geng", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962471", "name": "Zesen Huang", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962472", "name": "Haoyang Li", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962473", "name": "Wenbin Li", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962474", "user": {"_id": "674d191fc406e58320e21dc0", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/674d191fc406e58320e21dc0/3WUBoDbpGxOu5-OJq0bxS.png", "isPro": false, "fullname": "Koutian Wu", "user": "ktwu01", "type": "user", "name": "ktwu01"}, "name": "Koutian Wu", "status": "claimed_verified", "statusLastChangedAt": "2026-09-18T00:45:04.765Z", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962475", "name": "Zihan Zhou", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962476", "name": "Yuanbo Pang", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962477", "name": "Weihao Liu", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962478", "name": "Zigong Xu", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962479", "name": "Zhiping Li", "hidden": false}, {"_id": "6aab567a1d9cc4dec796247a", "user": {"_id": "662768ede39da75ea99950a2", "avatarUrl": "/avatars/adee194925148d6a0753c064a49549c1.svg", "isPro": false, "fullname": "Zhang Zongzheng", "user": "Zzz0918", "type": "user", "name": "Zzz0918"}, "name": "Zongzheng Zhang", "status": "claimed_verified", "statusLastChangedAt": "2026-09-17T08:45:04.484Z", "hidden": false}, {"_id": "6aab567a1d9cc4dec796247b", "name": "Chuanfei Dong", "hidden": false}, {"_id": "6aab567a1d9cc4dec796247c", "name": "Jiankai Sun", "hidden": false}, {"_id": "6aab567a1d9cc4dec796247d", "name": "Tianzhe Zheng", "hidden": false}, {"_id": "6aab567a1d9cc4dec796247e", "name": "Fengyu Xie", "hidden": false}, {"_id": "6aab567a1d9cc4dec796247f", "name": "Yue Ma", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962480", "name": "Yueheng Shi", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962481", "name": "Tong Xie", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962482", "name": "Zonglin Di", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962483", "name": "Xianrong Liu", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962484", "name": "Qucheng Gao", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962485", "user": {"_id": "646fd64f9ba7aeaacb269cba", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/646fd64f9ba7aeaacb269cba/HJSlvkP5Crbi5CbOcFD2y.png", "isPro": false, "fullname": "Yimin Liu", "user": "yiminn", "type": "user", "name": "yiminn"}, "name": "Yimin Liu", "status": "claimed_verified", "statusLastChangedAt": "2026-09-17T08:45:04.493Z", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962486", "name": "Jiaming Pan", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962487", "name": "Sheng Huang", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962488", "name": "Xiao-Han Ma", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962489", "name": "Lanqing Yuan", "hidden": false}, {"_id": "6aab567a1d9cc4dec796248a", "name": "Zhenlin Zhu", "hidden": false}, {"_id": "6aab567a1d9cc4dec796248b", "name": "Ziang Liu", "hidden": false}, {"_id": "6aab567a1d9cc4dec796248c", "name": "Ziyang Xu", "hidden": false}, {"_id": "6aab567a1d9cc4dec796248d", "name": "Junkai Wang", "hidden": false}, {"_id": "6aab567a1d9cc4dec796248e", "name": "Kangkai Liang", "hidden": false}, {"_id": "6aab567a1d9cc4dec796248f", "name": "Jiayi Xian", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962490", "name": "Zehong Zhao", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962491", "name": "Liuwei Xu", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962492", "name": "Jingxu Xie", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962493", "name": "Peijin Zhang", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962494", "name": "Qiang Gao", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962495", "name": "Chengyi Xing", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962496", "name": "Zhe Zhao", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962497", "name": "Xi Wang", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962498", "name": "Yaopeng Xing", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962499", "name": "Xing Meng", "hidden": false}, {"_id": "6aab567a1d9cc4dec796249a", "name": "Zhenfei Yin", "hidden": false}, {"_id": "6aab567a1d9cc4dec796249b", "name": "Yingcheng Wu", "hidden": false}, {"_id": "6aab567a1d9cc4dec796249c", "name": "Ling Yang", "hidden": false}], "publishedAt": "2026-09-16T00:00:00.000Z", "submittedOnDailyAt": "2026-09-17T00:00:00.000Z", "title": "ScienceIDE: Turning World's Scientific Codebase into Agent Learnable Environments", "submittedOnDailyBy": {"_id": "64fde4e252e82dd432b74ce9", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/64fde4e252e82dd432b74ce9/-CQZbBP7FsPPyawYrsi4z.jpeg", "isPro": false, "fullname": "Ling Yang", "user": "Lingaaaaaaa", "type": "user", "name": "Lingaaaaaaa"}, "summary": "Scientific code repositories encode decades of human knowledge in executable models, methods, and tools. Yet fragmented toolchains, implicit domain conventions, and specialized correctness criteria make this knowledge difficult to convert into reliable learning experience-a challenge we call the scientific experience bottleneck. We introduce ScienceIDE, infrastructure for turning the world's scientific code into programmable environments for scientific agents. Guided by expert-defined scientific cases and acceptance criteria, agents transform repositories into executable environments that support task generation, execution, and scientific verification. These environments provide a shared foundation for supervised fine-tuning, reinforcement learning, and evaluation. Using verified interaction trajectories, we train PhAI-IDE-72B, PhAI-IDE-9B, and PhAI-IDE-4B. The model family shows gains in held-out scientific-code repair and across selected general-purpose benchmarks in code, reasoning, and knowledge, providing evidence of positive transfer from scientific experience to broader capabilities. ScienceIDE lays the foundation for an integrated workspace for agent learning and scientific practice, making humanity's scientific software a shared substrate for developing scientific intelligence. Code: https://github.com/aitofound/ScienceIDE", "upvotes": 71, "discussionId": "6aab567a1d9cc4dec796249d", "projectPage": "https://huggingface.co/collections/AItonomy/scienceide-model-series", "githubRepo": "https://github.com/aitofound/ScienceIDE", "githubRepoAddedBy": "user", "githubStars": 27, "organization": {"_id": "6aab7c097e5721f5e005ff0a", "name": "PhAILabs", "fullname": "PhAI Labs", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/64fde4e252e82dd432b74ce9/5-hyYwAMko5JVJz5qWxEj.png"}, "summary_zh": "<ul>\n    <li>\u79d1\u5b66\u4ee3\u7801\u5e93\u5305\u542b\u4e86\u51e0\u5341\u5e74\u7684\u77e5\u8bc6\uff0c\u4f46\u7531\u4e8e\u5de5\u5177\u94fe\u788e\u7247\u5316\u548c\u9886\u57df\u7ea6\u5b9a\u4e0d\u660e\u786e\uff0c\u96be\u4ee5\u5c06\u8fd9\u4e9b\u77e5\u8bc6\u8f6c\u5316\u4e3a\u53ef\u9760\u7684\u5b66\u4e60\u4f53\u9a8c\u3002</li>\n    <li>\u6211\u4eec\u63d0\u51fa\u4e86ScienceIDE\uff0c\u65e8\u5728\u5c06\u79d1\u5b66\u4ee3\u7801\u8f6c\u53d8\u4e3a\u53ef\u7f16\u7a0b\u7684\u73af\u5883\uff0c\u4ee5\u652f\u6301\u79d1\u5b66\u4ee3\u7406\u7684\u5b66\u4e60\u548c\u9a8c\u8bc1\u3002</li>\n    <li>\u901a\u8fc7\u4e13\u5bb6\u5b9a\u4e49\u7684\u79d1\u5b66\u6848\u4f8b\u548c\u63a5\u53d7\u6807\u51c6\uff0c\u8fd9\u4e9b\u73af\u5883\u53ef\u4ee5\u751f\u6210\u548c\u6267\u884c\u4efb\u52a1\uff0c\u5e76\u8fdb\u884c\u79d1\u5b66\u9a8c\u8bc1\u3002</li>\n    <li>\u6211\u4eec\u4f7f\u7528\u7ecf\u8fc7\u9a8c\u8bc1\u7684\u4ea4\u4e92\u8f68\u8ff9\u8bad\u7ec3\u4e86\u591a\u4e2a\u6a21\u578b\uff0c\u8fd9\u4e9b\u6a21\u578b\u5728\u79d1\u5b66\u4ee3\u7801\u4fee\u590d\u548c\u5176\u4ed6\u901a\u7528\u57fa\u51c6\u4e0a\u8868\u73b0\u826f\u597d\u3002</li>\n    <li>ScienceIDE\u4e3a\u4ee3\u7406\u5b66\u4e60\u548c\u79d1\u5b66\u5b9e\u8df5\u63d0\u4f9b\u4e86\u4e00\u4e2a\u7efc\u5408\u5de5\u4f5c\u7a7a\u95f4\uff0c\u4fc3\u8fdb\u4e86\u79d1\u5b66\u667a\u80fd\u7684\u53d1\u5c55\u3002</li>\n</ul>", "summary_simple": "<ul>\n  <li>Scientific code contains valuable knowledge, but it is hard to use because of complex tools and rules.</li>\n  <li>ScienceIDE is a new system that helps turn scientific code into environments for AI agents to learn and work in.</li>\n  <li>These environments help generate tasks, execute them, and verify scientific results based on expert criteria.</li>\n  <li>The system trains models (PhAI-IDE-72B, PhAI-IDE-9B, and PhAI-IDE-4B) that improve their ability to fix code and perform various tasks.</li>\n  <li>ScienceIDE aims to create a unified space for AI learning and scientific work, using existing scientific software to develop smarter AI.</li>\n</ul>"}, "publishedAt": "2026-09-15T20:00:00.000Z", "title": "ScienceIDE: Turning World's Scientific Codebase into Agent Learnable Environments", "summary": "Scientific code repositories encode decades of human knowledge in executable models, methods, and tools. Yet fragmented toolchains, implicit domain conventions, and specialized correctness criteria make this knowledge difficult to convert into reliable learning experience-a challenge we call the scientific experience bottleneck. We introduce ScienceIDE, infrastructure for turning the world's scientific code into programmable environments for scientific agents. Guided by expert-defined scientific cases and acceptance criteria, agents transform repositories into executable environments that support task generation, execution, and scientific verification. These environments provide a shared foundation for supervised fine-tuning, reinforcement learning, and evaluation. Using verified interaction trajectories, we train PhAI-IDE-72B, PhAI-IDE-9B, and PhAI-IDE-4B. The model family shows gains in held-out scientific-code repair and across selected general-purpose benchmarks in code, reasoning, and knowledge, providing evidence of positive transfer from scientific experience to broader capabilities. ScienceIDE lays the foundation for an integrated workspace for agent learning and scientific practice, making humanity's scientific software a shared substrate for developing scientific intelligence. Code: https://github.com/aitofound/ScienceIDE", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2609.19134.png", "numComments": 3, "submittedBy": {"_id": "64fde4e252e82dd432b74ce9", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/64fde4e252e82dd432b74ce9/-CQZbBP7FsPPyawYrsi4z.jpeg", "fullname": "Ling Yang", "name": "Lingaaaaaaa", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 18, "isUserFollowing": false}, "organization": {"_id": "6aab7c097e5721f5e005ff0a", "name": "PhAILabs", "fullname": "PhAI Labs", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/64fde4e252e82dd432b74ce9/5-hyYwAMko5JVJz5qWxEj.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.06100", "authors": [{"_id": "6ac4b70a9eb4ee6bd77a9766", "user": {"_id": "65c1d1bda2239cf479ecf573", "avatarUrl": "/avatars/70483a134b3236d690fc4d9409f1ecad.svg", "isPro": true, "fullname": "Long", "user": "Quanyu001", "type": "user", "name": "Quanyu001"}, "name": "Quanyu Long", "status": "claimed_verified", "statusLastChangedAt": "2026-10-06T09:20:03.874Z", "hidden": false}, {"_id": "6ac4b70a9eb4ee6bd77a9767", "user": {"_id": "64969bccf590e76c93938582", "avatarUrl": "/avatars/363598cba9e9496852e60144694b2f1c.svg", "isPro": false, "fullname": "shawncchen", "user": "chrisCCC", "type": "user", "name": "chrisCCC"}, "name": "Xiao Chen", "status": "claimed_verified", "statusLastChangedAt": "2026-10-07T08:07:49.844Z", "hidden": false}, {"_id": "6ac4b70a9eb4ee6bd77a9768", "name": "Jianda Chen", "hidden": false}, {"_id": "6ac4b70a9eb4ee6bd77a9769", "name": "Haozhen Zhang", "hidden": false}, {"_id": "6ac4b70a9eb4ee6bd77a976a", "name": "Qisheng Hu", "hidden": false}, {"_id": "6ac4b70a9eb4ee6bd77a976b", "name": "Jianzhu Bao", "hidden": false}, {"_id": "6ac4b70a9eb4ee6bd77a976c", "name": "Wenya Wang", "hidden": false}], "publishedAt": "2026-10-05T00:00:00.000Z", "submittedOnDailyAt": "2026-10-09T00:00:00.000Z", "title": "From Traces to Agentic Worlds: Agentic Language World Models for Interactive Environment Simulation", "submittedOnDailyBy": {"_id": "65c1d1bda2239cf479ecf573", "avatarUrl": "/avatars/70483a134b3236d690fc4d9409f1ecad.svg", "isPro": true, "fullname": "Long", "user": "Quanyu001", "type": "user", "name": "Quanyu001"}, "summary": "Realistic environment replicas are increasingly valuable for training and evaluating LLM agents, yet the original systems may be inaccessible or impractical to reproduce. We explore agentic language world modeling: rather than rebuilding an executable environment, a world model agent serves as the environment for a task agent and supports faithful and stateful simulation. We instantiate this paradigm with Trace2Env, a learning-free framework for settings where the original system is unavailable but historical interaction traces remain accessible. Trace2Env reconstructs these traces into a reusable environment worldbook containing environment schemas, grounded evidence, and induced behavioral knowledge. At runtime, the world model agent actively consults the worldbook together with persistent episodic state to infer each action's observation and lasting state effects. Across nine environments, Trace2Env improves both next-observation fidelity and long-horizon interaction consistency over conventional prompt-based LWMs. In multi-turn interaction, task agent actions generated against Trace2Env remain valid more often when replayed in the real environment, indicating that its simulated dynamics better preserve the consequences of earlier actions across successive turns. These results establish agentic language world modeling as an alternative direction for building realistic environment replicas without reconstructing the original executable system.", "upvotes": 64, "discussionId": "6ac4b70a9eb4ee6bd77a976d", "projectPage": "https://quanyulong.net/trace2env/", "githubRepo": "https://github.com/ruyue0001/trace2env", "githubRepoAddedBy": "user", "githubStars": 17, "organization": {"_id": "6371470aafbe42caa5a76208", "name": "nanyang-technological-university-singapore", "fullname": "Nanyang Technological University Singapore", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/637146c5afbe42caa5a75e1b/sZyHSA1AQaAS4nrGan682.png"}, "summary_zh": "<ul>\n    <li>\u4e3a\u4e86\u8bad\u7ec3\u548c\u8bc4\u4f30\u5927\u578b\u8bed\u8a00\u6a21\u578b\uff08LLM\uff09\u4ee3\u7406\uff0c\u521b\u5efa\u771f\u5b9e\u7684\u73af\u5883\u590d\u5236\u54c1\u53d8\u5f97\u8d8a\u6765\u8d8a\u91cd\u8981\uff0c\u4f46\u539f\u59cb\u7cfb\u7edf\u53ef\u80fd\u65e0\u6cd5\u8bbf\u95ee\u6216\u96be\u4ee5\u91cd\u5efa\u3002</li>\n    <li>\u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u79cd\u65b0\u7684\u65b9\u6cd5\uff0c\u79f0\u4e3a\u4ee3\u7406\u8bed\u8a00\u4e16\u754c\u5efa\u6a21\uff0c\u901a\u8fc7\u4f7f\u7528\u4e16\u754c\u6a21\u578b\u4ee3\u7406\u6765\u4ee3\u66ff\u91cd\u5efa\u53ef\u6267\u884c\u73af\u5883\u3002</li>\n    <li>Trace2Env\u662f\u4e00\u4e2a\u65e0\u5b66\u4e60\u6846\u67b6\uff0c\u5b83\u5229\u7528\u5386\u53f2\u4ea4\u4e92\u8bb0\u5f55\u91cd\u5efa\u73af\u5883\uff0c\u4ee5\u521b\u5efa\u53ef\u91cd\u590d\u4f7f\u7528\u7684\u4e16\u754c\u4e66\u3002</li>\n    <li>\u5728\u4e5d\u4e2a\u73af\u5883\u4e2d\uff0cTrace2Env\u5728\u89c2\u5bdf\u7cbe\u786e\u5ea6\u548c\u957f\u671f\u4ea4\u4e92\u4e00\u81f4\u6027\u65b9\u9762\u4f18\u4e8e\u4f20\u7edf\u7684\u57fa\u4e8e\u63d0\u793a\u7684\u8bed\u8a00\u6a21\u578b\u3002</li>\n    <li>\u5b9e\u9a8c\u7ed3\u679c\u8868\u660e\uff0cTrace2Env\u80fd\u66f4\u597d\u5730\u4fdd\u7559\u591a\u8f6e\u4ea4\u4e92\u4e2d\u65e9\u671f\u884c\u52a8\u7684\u540e\u679c\uff0c\u63d0\u4f9b\u4e86\u4e00\u79cd\u65e0\u9700\u91cd\u5efa\u539f\u59cb\u7cfb\u7edf\u7684\u73b0\u5b9e\u73af\u5883\u590d\u5236\u65b9\u6cd5\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Realistic environment replicas help train and evaluate language model agents but can be hard to create from original systems.</li>\n    <li>Agentic language world modeling uses a world model agent instead of rebuilding the original environment.</li>\n    <li>Trace2Env is a framework that turns historical interaction traces into a reusable environment worldbook.</li>\n    <li>This framework improves the accuracy of actions and consistency across multiple interactions compared to traditional methods.</li>\n    <li>Overall, agentic language world modeling offers a new way to create realistic environments without needing the original systems.</li>\n</ul>"}, "publishedAt": "2026-10-04T20:00:00.000Z", "title": "From Traces to Agentic Worlds: Agentic Language World Models for Interactive Environment Simulation", "summary": "Realistic environment replicas are increasingly valuable for training and evaluating LLM agents, yet the original systems may be inaccessible or impractical to reproduce. We explore agentic language world modeling: rather than rebuilding an executable environment, a world model agent serves as the environment for a task agent and supports faithful and stateful simulation. We instantiate this paradigm with Trace2Env, a learning-free framework for settings where the original system is unavailable but historical interaction traces remain accessible. Trace2Env reconstructs these traces into a reusable environment worldbook containing environment schemas, grounded evidence, and induced behavioral knowledge. At runtime, the world model agent actively consults the worldbook together with persistent episodic state to infer each action's observation and lasting state effects. Across nine environments, Trace2Env improves both next-observation fidelity and long-horizon interaction consistency over conventional prompt-based LWMs. In multi-turn interaction, task agent actions generated against Trace2Env remain valid more often when replayed in the real environment, indicating that its simulated dynamics better preserve the consequences of earlier actions across successive turns. These results establish agentic language world modeling as an alternative direction for building realistic environment replicas without reconstructing the original executable system.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.06100.png", "numComments": 1, "submittedBy": {"_id": "65c1d1bda2239cf479ecf573", "avatarUrl": "/avatars/70483a134b3236d690fc4d9409f1ecad.svg", "fullname": "Long", "name": "Quanyu001", "type": "user", "isPro": true, "isHf": false, "isHfAdmin": false, "isMod": false, "isUserFollowing": false}, "organization": {"_id": "6371470aafbe42caa5a76208", "name": "nanyang-technological-university-singapore", "fullname": "Nanyang Technological University Singapore", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/637146c5afbe42caa5a75e1b/sZyHSA1AQaAS4nrGan682.png"}, "isAuthorParticipating": true}, {"paper": {"id": "2609.18708", "authors": [{"_id": "6aab88ba1d9cc4dec79625a4", "user": {"_id": "6785e04ce63a669874f166e9", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/6785e04ce63a669874f166e9/xSUEAmRm-KadDNOYiOZew.jpeg", "isPro": false, "fullname": "dodojorid", "user": "yizhuoli", "type": "user", "name": "yizhuoli"}, "name": "Yizhuo Li", "status": "claimed_verified", "statusLastChangedAt": "2026-09-17T09:09:42.043Z", "hidden": false}, {"_id": "6aab88ba1d9cc4dec79625a5", "name": "Jianhao Yan", "hidden": false}, {"_id": "6aab88ba1d9cc4dec79625a6", "name": "Yun Luo", "hidden": false}, {"_id": "6aab88ba1d9cc4dec79625a7", "name": "Zhi Wang", "hidden": false}, {"_id": "6aab88ba1d9cc4dec79625a8", "name": "Futing Wang", "hidden": false}, {"_id": "6aab88ba1d9cc4dec79625a9", "name": "Rong-Xi Tan", "hidden": false}, {"_id": "6aab88ba1d9cc4dec79625aa", "name": "Kanghui Tian", "hidden": false}, {"_id": "6aab88ba1d9cc4dec79625ab", "name": "Ganqu Cui", "hidden": false}, {"_id": "6aab88ba1d9cc4dec79625ac", "name": "Ning Ding", "hidden": false}, {"_id": "6aab88ba1d9cc4dec79625ad", "name": "Peilin Zhao", "hidden": false}, {"_id": "6aab88ba1d9cc4dec79625ae", "name": "Yafu Li", "hidden": false}, {"_id": "6aab88ba1d9cc4dec79625af", "name": "Yu Cheng", "hidden": false}], "publishedAt": "2026-09-16T00:00:00.000Z", "submittedOnDailyAt": "2026-09-17T00:00:00.000Z", "title": "Rethinking Critic Learning in PPO: Understanding and Mitigating Value Flattening", "submittedOnDailyBy": {"_id": "644915c5e87a77e872e61350", "avatarUrl": "/avatars/46ba7bdf04ad4c1b0ad79155010dc684.svg", "isPro": false, "fullname": "Luo", "user": "ramiroluo", "type": "user", "name": "ramiroluo"}, "summary": "In reinforcement learning for large language models, Proximal Policy Optimization (PPO) commonly uses a critic to estimate state values and reduce the variance of policy updates. However, we uncover a systematic failure mode in PPO critics, which we call Value Flattening: state values, estimated from multiple Monte Carlo continuations, change sharply across intermediate states while critic predictions remain comparatively flat. We further observe this phenomenon in a controlled FrozenLake environment and find that it becomes more pronounced as the state space grows. Our theoretical and empirical analyses relate Value Flattening to an implicit variance penalty in the critic loss and redundant updates from temporally correlated states with similar gradients. Motivated by these findings, we introduce SParse Proximal Policy Optimization (SP^3O), which applies the value loss to only a few well-separated states in each response to mitigate both effects. Experiments on Qwen3-Base show that SP^3O with only three states supervised per response can mitigate Value Flattening and consistently improve the learned policy across model sizes and evaluation suites. Together, our results identify Value Flattening as an important yet overlooked failure mode of critic learning in standard PPO and show that a simple sparse supervision strategy can mitigate it.", "upvotes": 60, "discussionId": "6aab88ba1d9cc4dec79625b0", "projectPage": "https://dodojordi.github.io/SP3O/", "githubRepo": "https://github.com/Dodojordi/SP3O", "githubRepoAddedBy": "user", "githubStars": 15, "organization": {"_id": "6a4fb75a1c66dbf208e7ddb6", "name": "Shanghai-AI-Laboratory", "fullname": "Shanghai AI Laboratory", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/65cd955637be1841d0b75397/Rao_Kq6NMtTVfSqLUIR4k.webp"}, "summary_zh": "<ul>\n    <li>\u5728\u5f3a\u5316\u5b66\u4e60\u4e2d\uff0cPPO\u5e38\u7528\u4e00\u4e2a\u8bc4\u8bba\u8005\u6765\u4f30\u8ba1\u72b6\u6001\u503c\u5e76\u51cf\u5c11\u7b56\u7565\u66f4\u65b0\u7684\u65b9\u5dee\u3002</li>\n    <li>\u6211\u4eec\u53d1\u73b0PPO\u8bc4\u8bba\u8005\u5b58\u5728\u4e00\u4e2a\u7cfb\u7edf\u6027\u95ee\u9898\uff0c\u79f0\u4e3a\u72b6\u6001\u503c\u5e73\u5766\u5316\uff0c\u5373\u72b6\u6001\u503c\u5728\u4e2d\u95f4\u72b6\u6001\u95f4\u53d8\u5316\u5267\u70c8\uff0c\u800c\u8bc4\u8bba\u8005\u7684\u9884\u6d4b\u5374\u76f8\u5bf9\u5e73\u5766\u3002</li>\n    <li>\u8fd9\u79cd\u73b0\u8c61\u5728\u53d7\u63a7\u7684FrozenLake\u73af\u5883\u4e2d\u89c2\u5bdf\u5230\uff0c\u968f\u7740\u72b6\u6001\u7a7a\u95f4\u7684\u6269\u5927\u95ee\u9898\u66f4\u52a0\u660e\u663e\u3002</li>\n    <li>\u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u79cd\u65b0\u7684\u65b9\u6cd5\uff0c\u79f0\u4e3a\u7a00\u758f\u8fd1\u7aef\u7b56\u7565\u4f18\u5316\uff08SP^3O\uff09\uff0c\u5176\u53ea\u5bf9\u6bcf\u4e2a\u54cd\u5e94\u4e2d\u7684\u5c11\u6570\u51e0\u4e2a\u5206\u79bb\u72b6\u6001\u5e94\u7528\u503c\u635f\u5931\uff0c\u4ee5\u51cf\u8f7b\u5e73\u5766\u5316\u6548\u5e94\u3002</li>\n    <li>\u5b9e\u9a8c\u8868\u660e\uff0cSP^3O\u5728\u6bcf\u4e2a\u54cd\u5e94\u4e2d\u53ea\u76d1\u7763\u4e09\u4e2a\u72b6\u6001\uff0c\u80fd\u591f\u6709\u6548\u51cf\u8f7b\u72b6\u6001\u503c\u5e73\u5766\u5316\uff0c\u5e76\u5728\u4e0d\u540c\u6a21\u578b\u89c4\u6a21\u548c\u8bc4\u4f30\u5957\u4ef6\u4e2d\u6301\u7eed\u6539\u5584\u5b66\u4e60\u7b56\u7565\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Proximal Policy Optimization (PPO) uses a critic to estimate state values, but we found a problem called Value Flattening, where state value predictions do not change much even when they should.</li>\n    <li>Value Flattening is more noticeable in larger state spaces and affects how PPO learns from experiences.</li>\n    <li>This issue is linked to a penalty in the critic's loss function and repetitive updates from similar states that have the same influence on learning.</li>\n    <li>We propose a new method called SParse Proximal Policy Optimization (SP^3O) that only applies value updates to a few distinct states to reduce these problems.</li>\n    <li>Tests show that SP^3O can improve the learning process and address Value Flattening effectively, even with minimal supervision during training.</li>\n</ul>"}, "publishedAt": "2026-09-15T20:00:00.000Z", "title": "Rethinking Critic Learning in PPO: Understanding and Mitigating Value Flattening", "summary": "In reinforcement learning for large language models, Proximal Policy Optimization (PPO) commonly uses a critic to estimate state values and reduce the variance of policy updates. However, we uncover a systematic failure mode in PPO critics, which we call Value Flattening: state values, estimated from multiple Monte Carlo continuations, change sharply across intermediate states while critic predictions remain comparatively flat. We further observe this phenomenon in a controlled FrozenLake environment and find that it becomes more pronounced as the state space grows. Our theoretical and empirical analyses relate Value Flattening to an implicit variance penalty in the critic loss and redundant updates from temporally correlated states with similar gradients. Motivated by these findings, we introduce SParse Proximal Policy Optimization (SP^3O), which applies the value loss to only a few well-separated states in each response to mitigate both effects. Experiments on Qwen3-Base show that SP^3O with only three states supervised per response can mitigate Value Flattening and consistently improve the learned policy across model sizes and evaluation suites. Together, our results identify Value Flattening as an important yet overlooked failure mode of critic learning in standard PPO and show that a simple sparse supervision strategy can mitigate it.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2609.18708.png", "numComments": 2, "submittedBy": {"_id": "644915c5e87a77e872e61350", "avatarUrl": "/avatars/46ba7bdf04ad4c1b0ad79155010dc684.svg", "fullname": "Luo", "name": "ramiroluo", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 2, "isUserFollowing": false}, "organization": {"_id": "6a4fb75a1c66dbf208e7ddb6", "name": "Shanghai-AI-Laboratory", "fullname": "Shanghai AI Laboratory", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/65cd955637be1841d0b75397/Rao_Kq6NMtTVfSqLUIR4k.webp"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.10528", "authors": [{"_id": "6ac6fb044eb8005165aed391", "name": "Wei Huang", "hidden": false}, {"_id": "6ac6fb044eb8005165aed392", "name": "Bohan Zhang", "hidden": false}, {"_id": "6ac6fb044eb8005165aed393", "name": "Chenzhi Liu", "hidden": false}, {"_id": "6ac6fb044eb8005165aed394", "name": "Isabella Liu", "hidden": false}, {"_id": "6ac6fb044eb8005165aed395", "name": "Shuai Yang", "hidden": false}, {"_id": "6ac6fb044eb8005165aed396", "name": "Weian Mao", "hidden": false}, {"_id": "6ac6fb044eb8005165aed397", "name": "Luozhou Wang", "hidden": false}, {"_id": "6ac6fb044eb8005165aed398", "name": "Yicheng Xiao", "hidden": false}, {"_id": "6ac6fb044eb8005165aed399", "name": "Weifeng Lin", "hidden": false}, {"_id": "6ac6fb044eb8005165aed39a", "name": "Qixin Hu", "hidden": false}, {"_id": "6ac6fb044eb8005165aed39b", "name": "Bryan Chu", "hidden": false}, {"_id": "6ac6fb044eb8005165aed39c", "name": "Sifei Liu", "hidden": false}, {"_id": "6ac6fb044eb8005165aed39d", "name": "Linxi Fan", "hidden": false}, {"_id": "6ac6fb044eb8005165aed39e", "name": "Xiaojuan Qi", "hidden": false}, {"_id": "6ac6fb044eb8005165aed39f", "name": "Song Han", "hidden": false}, {"_id": "6ac6fb044eb8005165aed3a0", "name": "Yukang Chen", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/656db3f53dc1d277e5a64410/xydlSuXEJrwor5qFTZzvU.qt"], "publishedAt": "2026-10-07T00:00:00.000Z", "submittedOnDailyAt": "2026-10-08T00:00:00.000Z", "title": "Long-WAM: Scaling the Context of World-Action Models", "submittedOnDailyBy": {"_id": "656db3f53dc1d277e5a64410", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/656db3f53dc1d277e5a64410/9kiY2K3MCRcBDk7MrkTBK.png", "isPro": false, "fullname": "Wei Huang", "user": "AaronHuangWei", "type": "user", "name": "AaronHuangWei"}, "summary": "Real-time robot control demands enough visual history to infer motion and task progress, but processing that history can delay action. We present Long-WAM, a model-system framework for scaling the context of causal world-action models under real-time control constraints. Our central finding is that access to history is not the same as using it: longer histories pay off far more when the video foundation is pretrained autoregressively (AR). We first learn causal prediction from robot and egocentric videos without action labels, then preserve this history-to-future structure during world-action adaptation. On RoboCasa GR-1, increasing context from 0.0 to 19.2 seconds raises success from 63.3% to 78.7%, whereas a bidirectionally pretrained initialization shows no net gain; robot-domain AR pretraining further raises peak success on GR-1 and LIBERO-Long. Long-WAM also achieves the best results among compared methods on LIBERO-Long, RoboTwin 2.0, and DOMINO. Streaming observation encoding, asynchronous execution, and hardware-specific acceleration enable deployment on RTX 5090, DGX Spark, and Jetson AGX Thor without dropping future prediction; on RTX 5090, each action chunk, including future-video latent prediction, takes 107.4 ms. Real-time deployment on Unitree G1 and YAM supports dynamic and long-horizon manipulation, including 95% success on dynamic cup stacking, where Pi0.5 and Fast-WAM succeed in none of 20 trials. As a memory-informed executor, Long-WAM also complements higher-level planning in composite tasks.", "upvotes": 54, "discussionId": "6ac6fb044eb8005165aed3a1", "projectPage": "https://nvlabs.github.io/LongLive/Long-WAM/", "githubRepo": "https://github.com/NVlabs/LongLive", "githubRepoAddedBy": "user", "githubStars": 2662, "organization": {"_id": "60262b67268c201cdc8b7d43", "name": "nvidia", "fullname": "NVIDIA", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/65df9200dc3292a8983e5017/Vs5FPVCH-VZBipV3qKTuy.png"}, "summary_zh": "<ul>\n    <li>Long-WAM\u662f\u4e00\u4e2a\u7528\u4e8e\u5b9e\u65f6\u673a\u5668\u4eba\u63a7\u5236\u7684\u6a21\u578b\u7cfb\u7edf\u6846\u67b6\uff0c\u53ef\u4ee5\u5904\u7406\u8db3\u591f\u7684\u89c6\u89c9\u5386\u53f2\u4ee5\u63a8\u65ad\u8fd0\u52a8\u548c\u4efb\u52a1\u8fdb\u5c55\u3002</li>\n    <li>\u901a\u8fc7\u4f7f\u7528\u9884\u5148\u8bad\u7ec3\u7684\u81ea\u56de\u5f52\uff08AR\uff09\u89c6\u9891\u57fa\u7840\uff0c\u8f83\u957f\u7684\u5386\u53f2\u8bb0\u5f55\u80fd\u663e\u8457\u63d0\u9ad8\u6210\u529f\u7387\uff0c\u4ece63.3%\u63d0\u5347\u81f378.7%\u3002</li>\n    <li>\u5728\u591a\u4e2a\u673a\u5668\u4eba\u4efb\u52a1\u4e2d\uff0cLong-WAM\u7684\u8868\u73b0\u4f18\u4e8e\u5176\u4ed6\u65b9\u6cd5\uff0c\u5e76\u5728\u52a8\u6001\u676f\u5b50\u5806\u53e0\u4efb\u52a1\u4e2d\u5b9e\u73b0\u4e8695%\u7684\u6210\u529f\u7387\u3002</li>\n    <li>\u8be5\u7cfb\u7edf\u652f\u6301\u5728RTX 5090\u7b49\u786c\u4ef6\u4e0a\u5b9e\u65f6\u90e8\u7f72\uff0c\u80fd\u6709\u6548\u6267\u884c\u52a8\u6001\u548c\u957f\u671f\u64cd\u4f5c\u3002</li>\n    <li>Long-WAM\u4f5c\u4e3a\u4e00\u4e2a\u5185\u5b58\u9a71\u52a8\u7684\u6267\u884c\u5668\uff0c\u80fd\u591f\u4e0e\u66f4\u9ad8\u7ea7\u522b\u7684\u89c4\u5212\u76f8\u7ed3\u5408\uff0c\u63d0\u5347\u590d\u5408\u4efb\u52a1\u7684\u6267\u884c\u6548\u679c\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Long-WAM is a new system for controlling robots in real-time by effectively using visual history to improve motion and task progress.</li>\n    <li>Using longer visual histories is more beneficial when the video data is pre-trained in a specific way, which helps robots make better predictions.</li>\n    <li>Tests on a robot called RoboCasa GR-1 showed that increasing the visual history improved success rates from 63.3% to 78.7%.</li>\n    <li>Long-WAM achieved the best performance compared to other methods on various tasks, including dynamic cup stacking, where it had a 95% success rate.</li>\n    <li>The system is designed to work efficiently on advanced hardware without sacrificing performance, allowing for real-time actions and complex tasks.</li>\n</ul>"}, "publishedAt": "2026-10-06T20:00:00.000Z", "title": "Long-WAM: Scaling the Context of World-Action Models", "summary": "Real-time robot control demands enough visual history to infer motion and task progress, but processing that history can delay action. We present Long-WAM, a model-system framework for scaling the context of causal world-action models under real-time control constraints. Our central finding is that access to history is not the same as using it: longer histories pay off far more when the video foundation is pretrained autoregressively (AR). We first learn causal prediction from robot and egocentric videos without action labels, then preserve this history-to-future structure during world-action adaptation. On RoboCasa GR-1, increasing context from 0.0 to 19.2 seconds raises success from 63.3% to 78.7%, whereas a bidirectionally pretrained initialization shows no net gain; robot-domain AR pretraining further raises peak success on GR-1 and LIBERO-Long. Long-WAM also achieves the best results among compared methods on LIBERO-Long, RoboTwin 2.0, and DOMINO. Streaming observation encoding, asynchronous execution, and hardware-specific acceleration enable deployment on RTX 5090, DGX Spark, and Jetson AGX Thor without dropping future prediction; on RTX 5090, each action chunk, including future-video latent prediction, takes 107.4 ms. Real-time deployment on Unitree G1 and YAM supports dynamic and long-horizon manipulation, including 95% success on dynamic cup stacking, where Pi0.5 and Fast-WAM succeed in none of 20 trials. As a memory-informed executor, Long-WAM also complements higher-level planning in composite tasks.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/656db3f53dc1d277e5a64410/xydlSuXEJrwor5qFTZzvU.qt"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.10528.png", "numComments": 1, "submittedBy": {"_id": "656db3f53dc1d277e5a64410", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/656db3f53dc1d277e5a64410/9kiY2K3MCRcBDk7MrkTBK.png", "fullname": "Wei Huang", "name": "AaronHuangWei", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 19, "isUserFollowing": false}, "organization": {"_id": "60262b67268c201cdc8b7d43", "name": "nvidia", "fullname": "NVIDIA", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/65df9200dc3292a8983e5017/Vs5FPVCH-VZBipV3qKTuy.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.04299", "authors": [{"_id": "6ac445589eb4ee6bd77a9345", "name": "Jinyuan Li", "hidden": false}, {"_id": "6ac445589eb4ee6bd77a9346", "name": "Chengsong Huang", "hidden": false}, {"_id": "6ac445589eb4ee6bd77a9347", "name": "Langlin Huang", "hidden": false}, {"_id": "6ac445589eb4ee6bd77a9348", "name": "Donghong Cai", "hidden": false}, {"_id": "6ac445589eb4ee6bd77a9349", "name": "Shiping Gao", "hidden": false}, {"_id": "6ac445589eb4ee6bd77a934a", "name": "Yuyi Yang", "hidden": false}, {"_id": "6ac445589eb4ee6bd77a934b", "name": "Jiaxin Huang", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/64fc20d899123d7698a30e61/jETbBtAg6-jnVU4RPRvZb.mp4"], "publishedAt": "2026-10-03T00:00:00.000Z", "submittedOnDailyAt": "2026-10-08T00:00:00.000Z", "title": "Questioning the Questions: Sustaining Self-Evolution in Reasoning Models", "submittedOnDailyBy": {"_id": "64fc20d899123d7698a30e61", "avatarUrl": "/avatars/9231982cf70a0689f50accedf1004702.svg", "isPro": false, "fullname": "Jinyuan Li", "user": "jinyuan222", "type": "user", "name": "jinyuan222"}, "summary": "Self-evolving reasoning models learn from their own generated questions, yet repeated self-training can lead to performance collapse. In this paper, we investigate why performance deteriorates over successive rounds and how to sustain self-evolution. Our analysis identifies two recurring quality problems in self-generated questions: invalid questions and repeated variants of the same mathematical questions. First, invalid questions become more prevalent across rounds, and answer-consistency filtering further increases their proportion in training data. Second, existing question diversity controls based on lexical similarity can miss mathematically equivalent questions expressed in different ways, which leads to question diversity collapse in later training rounds. Building on these findings, we introduce R-Quest, which uses question validity and novelty feedback to guide self-evolution. We first train the solver to recognize and reject invalid questions, then use its judgments to guide questioner rewards and filter solver training data. To avoid question repetition, we use a frozen base model to compare sampled question pairs and provide novelty feedback. Empirically, our method consistently achieves the highest average performance on 12 benchmarks in mathematical reasoning, general-domain reasoning, and code generation across two model families. Additionally, R-Quest maintains stable performance gains over ten rounds of self-evolution, peaking in the final round and outperforming R-Zero by 17.32 points.", "upvotes": 52, "discussionId": "6ac445589eb4ee6bd77a934c", "projectPage": "https://jinyuanli0012.github.io/R-Quest/", "githubRepo": "https://github.com/JinYuanLi0012/R-Quest", "githubRepoAddedBy": "user", "githubStars": 1, "organization": {"_id": "670035f24055c4569f7dd024", "name": "HINT-lab", "fullname": "Huang's INTelligence lab", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/64efbf39b3610349e84db417/tbNZtAX3vJeGo2Rag_7ZN.png"}, "summary_zh": "<ul>\n    <li>\u81ea\u6211\u8fdb\u5316\u7684\u63a8\u7406\u6a21\u578b\u901a\u8fc7\u751f\u6210\u7684\u95ee\u9898\u8fdb\u884c\u5b66\u4e60\uff0c\u4f46\u91cd\u590d\u81ea\u6211\u8bad\u7ec3\u53ef\u80fd\u5bfc\u81f4\u6027\u80fd\u4e0b\u964d\u3002</li>\n    <li>\u672c\u6587\u7814\u7a76\u4e86\u6027\u80fd\u4e0b\u964d\u7684\u539f\u56e0\uff0c\u4ee5\u53ca\u5982\u4f55\u4fdd\u6301\u81ea\u6211\u8fdb\u5316\u7684\u6709\u6548\u6027\u3002</li>\n    <li>\u53d1\u73b0\u81ea\u751f\u6210\u95ee\u9898\u5b58\u5728\u4e24\u4e2a\u4e3b\u8981\u8d28\u91cf\u95ee\u9898\uff1a\u65e0\u6548\u95ee\u9898\u548c\u91cd\u590d\u53d8\u4f53\u3002</li>\n    <li>\u63d0\u51faR-Quest\u65b9\u6cd5\uff0c\u901a\u8fc7\u95ee\u9898\u6709\u6548\u6027\u548c\u65b0\u9896\u6027\u53cd\u9988\u6765\u6307\u5bfc\u81ea\u6211\u8fdb\u5316\u3002</li>\n    <li>R-Quest\u572812\u4e2a\u57fa\u51c6\u6d4b\u8bd5\u4e2d\u8868\u73b0\u4f18\u5f02\uff0c\u5341\u8f6e\u81ea\u6211\u8fdb\u5316\u540e\u6027\u80fd\u4fdd\u6301\u7a33\u5b9a\uff0c\u6700\u7ec8\u8d85\u8d8aR-Zero\u3002 </li>\n</ul>", "summary_simple": "<ul>\n    <li>Self-evolving reasoning models learn by asking and answering their own questions, but can lose performance over time.</li>\n    <li>Problems arise from two main issues: an increase in invalid questions and repeated similar questions in training.</li>\n    <li>To improve this, the new method R-Quest helps filter out bad questions and encourage more unique ones.</li>\n    <li>R-Quest trains models to spot invalid questions and uses feedback to improve question quality.</li>\n    <li>This approach shows better performance in various tasks, maintaining improvements over multiple training rounds.</li>\n</ul>"}, "publishedAt": "2026-10-02T20:00:00.000Z", "title": "Questioning the Questions: Sustaining Self-Evolution in Reasoning Models", "summary": "Self-evolving reasoning models learn from their own generated questions, yet repeated self-training can lead to performance collapse. In this paper, we investigate why performance deteriorates over successive rounds and how to sustain self-evolution. Our analysis identifies two recurring quality problems in self-generated questions: invalid questions and repeated variants of the same mathematical questions. First, invalid questions become more prevalent across rounds, and answer-consistency filtering further increases their proportion in training data. Second, existing question diversity controls based on lexical similarity can miss mathematically equivalent questions expressed in different ways, which leads to question diversity collapse in later training rounds. Building on these findings, we introduce R-Quest, which uses question validity and novelty feedback to guide self-evolution. We first train the solver to recognize and reject invalid questions, then use its judgments to guide questioner rewards and filter solver training data. To avoid question repetition, we use a frozen base model to compare sampled question pairs and provide novelty feedback. Empirically, our method consistently achieves the highest average performance on 12 benchmarks in mathematical reasoning, general-domain reasoning, and code generation across two model families. Additionally, R-Quest maintains stable performance gains over ten rounds of self-evolution, peaking in the final round and outperforming R-Zero by 17.32 points.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/64fc20d899123d7698a30e61/jETbBtAg6-jnVU4RPRvZb.mp4"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.04299.png", "numComments": 1, "submittedBy": {"_id": "64fc20d899123d7698a30e61", "avatarUrl": "/avatars/9231982cf70a0689f50accedf1004702.svg", "fullname": "Jinyuan Li", "name": "jinyuan222", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 3, "isUserFollowing": false}, "organization": {"_id": "670035f24055c4569f7dd024", "name": "HINT-lab", "fullname": "Huang's INTelligence lab", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/64efbf39b3610349e84db417/tbNZtAX3vJeGo2Rag_7ZN.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.10524", "authors": [{"_id": "6ac6fef64eb8005165aed3e0", "name": "Jiyoung Kim", "hidden": false}, {"_id": "6ac6fef64eb8005165aed3e1", "name": "Paul Hyunbin Cho", "hidden": false}, {"_id": "6ac6fef64eb8005165aed3e2", "name": "Jisu Nam", "hidden": false}, {"_id": "6ac6fef64eb8005165aed3e3", "name": "Donghoon Lee", "hidden": false}, {"_id": "6ac6fef64eb8005165aed3e4", "name": "Hyunsung Go", "hidden": false}, {"_id": "6ac6fef64eb8005165aed3e5", "name": "Yeonkyeong Lee", "hidden": false}, {"_id": "6ac6fef64eb8005165aed3e6", "name": "Hansaem Kim", "hidden": false}, {"_id": "6ac6fef64eb8005165aed3e7", "name": "Seungryong Kim", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/65cb4ce4d5822659ec122119/vuLISuzr1b3izauYyA274.mp4"], "publishedAt": "2026-10-07T00:00:00.000Z", "submittedOnDailyAt": "2026-10-08T00:00:00.000Z", "title": "GRACE: Generation-aware latent compression for efficient video generation", "submittedOnDailyBy": {"_id": "65cb4ce4d5822659ec122119", "avatarUrl": "/avatars/b7e4b4c6914b32e097648dd5991dec26.svg", "isPro": true, "fullname": "jee0", "user": "chimaharicox", "type": "user", "name": "chimaharicox"}, "summary": "Highly compressed video autoencoders offer an effective way to accelerate video diffusion models, as the Diffusion Transformer (DiT) operates on far fewer tokens. However, such autoencoders are challenging to train, since a higher compression ratio degrades reconstruction quality and recovering it requires more channels, which is known to slow the convergence of the DiT. The compressed latent also differs from the one the DiT was trained on, so the pretrained DiT must be either retrained from scratch or adapted at considerable cost. Compressing the autoencoder the DiT was trained with appears to preserve compatibility, yet optimizing it for reconstruction alone still shifts the latent away from the distribution the DiT has learned. To address this, we propose Generation-Aware Latent Compression for Efficient Video Generation (GRACE), a two-stage framework that compresses a pretrained video autoencoder while keeping it compatible with the pretrained DiT. Specifically, we keep a frozen base latent from the pretrained encoder and learn a residual latent for the information lost under stronger compression, while aligning the compressed latent with the pretrained latent in the feature space of the frozen DiT so that the autoencoder is optimized for generation. We then adapt the DiT with lightweight fine-tuning and asymmetric denoising, where the base is denoised ahead of the residual. GRACE reduces the token count of Wan2.1-I2V-14B by 8x and its latency by 11.1x at 480x832x81, while matching the generation quality of the pretrained pipeline before compression on VBench.", "upvotes": 51, "discussionId": "6ac6fef64eb8005165aed3e8", "projectPage": "https://cvlab-kaist.github.io/GRACE/", "githubRepo": "https://github.com/cvlab-kaist/GRACE", "githubRepoAddedBy": "user", "githubStars": 12, "organization": {"_id": "6475760c33192631bad2bb38", "name": "kaist-ai", "fullname": "KAIST AI", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/6469949654873f0043b09c22/aaZFiyXe1qR-Dmy_xq67m.png"}, "summary_zh": "<ul>\n    <li>\u9ad8\u5ea6\u538b\u7f29\u7684\u89c6\u9891\u81ea\u7f16\u7801\u5668\u53ef\u4ee5\u52a0\u901f\u89c6\u9891\u6269\u6563\u6a21\u578b\uff0c\u4f46\u8bad\u7ec3\u56f0\u96be\u3002</li>\n    <li>\u66f4\u9ad8\u7684\u538b\u7f29\u6bd4\u4f1a\u964d\u4f4e\u91cd\u5efa\u8d28\u91cf\uff0c\u4e14\u9700\u8981\u66f4\u591a\u901a\u9053\uff0c\u8fd9\u4f1a\u51cf\u6162\u6a21\u578b\u6536\u655b\u3002</li>\n    <li>\u4e3a\u4e86\u4fdd\u6301\u517c\u5bb9\u6027\uff0c\u63d0\u51fa\u4e86\u4e00\u79cd\u540d\u4e3aGRACE\u7684\u4e24\u9636\u6bb5\u6846\u67b6\uff0c\u7528\u4e8e\u9ad8\u6548\u89c6\u9891\u751f\u6210\u3002</li>\n    <li>GRACE\u901a\u8fc7\u4fdd\u7559\u57fa\u7840\u6f5c\u5728\u53d8\u91cf\u5e76\u5b66\u4e60\u6b8b\u5dee\u6f5c\u5728\u53d8\u91cf\u6765\u4f18\u5316\u538b\u7f29\u8fc7\u7a0b\u3002</li>\n    <li>\u8be5\u65b9\u6cd5\u5b9e\u73b0\u4e868\u500d\u7684\u4ee4\u724c\u6570\u51cf\u5c11\u548c11.1\u500d\u7684\u5ef6\u8fdf\u964d\u4f4e\uff0c\u540c\u65f6\u4fdd\u6301\u751f\u6210\u8d28\u91cf\u3002</li>\n</ul>", "summary_simple": "<ul>\n  <li>Compressed video autoencoders can speed up video diffusion models by using fewer tokens.</li>\n  <li>Training these autoencoders is difficult because higher compression can lower video quality.</li>\n  <li>To solve this, the GRACE framework compresses a pretrained video autoencoder while keeping it compatible with the diffusion model.</li>\n  <li>GRACE learns an extra layer of information to improve video generation while maintaining quality.</li>\n  <li>This approach significantly reduces processing time and token count while delivering similar quality as the original model.</li>\n</ul>"}, "publishedAt": "2026-10-06T20:00:00.000Z", "title": "GRACE: Generation-aware latent compression for efficient video generation", "summary": "Highly compressed video autoencoders offer an effective way to accelerate video diffusion models, as the Diffusion Transformer (DiT) operates on far fewer tokens. However, such autoencoders are challenging to train, since a higher compression ratio degrades reconstruction quality and recovering it requires more channels, which is known to slow the convergence of the DiT. The compressed latent also differs from the one the DiT was trained on, so the pretrained DiT must be either retrained from scratch or adapted at considerable cost. Compressing the autoencoder the DiT was trained with appears to preserve compatibility, yet optimizing it for reconstruction alone still shifts the latent away from the distribution the DiT has learned. To address this, we propose Generation-Aware Latent Compression for Efficient Video Generation (GRACE), a two-stage framework that compresses a pretrained video autoencoder while keeping it compatible with the pretrained DiT. Specifically, we keep a frozen base latent from the pretrained encoder and learn a residual latent for the information lost under stronger compression, while aligning the compressed latent with the pretrained latent in the feature space of the frozen DiT so that the autoencoder is optimized for generation. We then adapt the DiT with lightweight fine-tuning and asymmetric denoising, where the base is denoised ahead of the residual. GRACE reduces the token count of Wan2.1-I2V-14B by 8x and its latency by 11.1x at 480x832x81, while matching the generation quality of the pretrained pipeline before compression on VBench.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/65cb4ce4d5822659ec122119/vuLISuzr1b3izauYyA274.mp4"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.10524.png", "numComments": 1, "submittedBy": {"_id": "65cb4ce4d5822659ec122119", "avatarUrl": "/avatars/b7e4b4c6914b32e097648dd5991dec26.svg", "fullname": "jee0", "name": "chimaharicox", "type": "user", "isPro": true, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 1, "isUserFollowing": false}, "organization": {"_id": "6475760c33192631bad2bb38", "name": "kaist-ai", "fullname": "KAIST AI", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/6469949654873f0043b09c22/aaZFiyXe1qR-Dmy_xq67m.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2609.37200", "authors": [{"_id": "6abf0f835ff0ac8de3b84a22", "name": "Songlin Yang", "hidden": false}, {"_id": "6abf0f835ff0ac8de3b84a23", "name": "Xiaotong Zhao", "hidden": false}, {"_id": "6abf0f835ff0ac8de3b84a24", "name": "Jiacheng Zhang", "hidden": false}, {"_id": "6abf0f835ff0ac8de3b84a25", "name": "Zhe Wang", "hidden": false}, {"_id": "6abf0f835ff0ac8de3b84a26", "name": "Toyota Li", "hidden": false}, {"_id": "6abf0f835ff0ac8de3b84a27", "name": "Eric Liu", "hidden": false}, {"_id": "6abf0f835ff0ac8de3b84a28", "name": "Alan Zhao", "hidden": false}, {"_id": "6abf0f835ff0ac8de3b84a29", "name": "Anyi Rao", "hidden": false}], "publishedAt": "2026-09-29T00:00:00.000Z", "submittedOnDailyAt": "2026-10-02T00:00:00.000Z", "title": "Adaptive Reward Routing: Dynamic Multi-Reward Optimization for Joint Audio-Video Diffusion via Forward-Process RL", "submittedOnDailyBy": {"_id": "66f64956ad4fe83c91776459", "avatarUrl": "/avatars/2014de658ac12413754dcf70bc34333e.svg", "isPro": false, "fullname": "Eddie", "user": "EddieYang428", "type": "user", "name": "EddieYang428"}, "summary": "Multi-reward guided reinforcement learning (i.e., RL) offers a promising way to improve joint audio-video diffusion models along several complementary objectives, including modality-specific quality, cross-modal semantic alignment, and temporal synchronization. Its effectiveness, however, depends on two quantities that change during training: where reward-driven updates should act, and how competing rewards should be combined. Existing methods tend to rely on fixed routing and reward weights, failing to track evolving model functions. To address these limitations, we propose Adaptive Reward Routing to jointly adapt update locations and reward coordination during forward-process RL (i.e., DiffusionNFT) of joint audio-video diffusion models. Our method consists of two components. (i) Cross-Modal Influence-Guided Routing (Localizing Updates): We use bidirectional cross-attention responses as an efficient proxy for evolving cross-modal influence, dynamically reweighting token-aware losses and scaling gradients across cross-modal layers without additional model interventions. (ii) Preference-Preserving Modality-Aware Reweighting (Coordinating Rewards): We preserve predefined weights as preference priors and use branch-specific reward-gradient interactions as residual corrections after warm-up. This resolves evolving conflicts without letting dominant rewards suppress weak but essential objectives. Extensive experiments demonstrate consistent improvements in modality quality, semantic consistency, and audio-video synchronization over strong RL baselines. Ablations and mechanism analyses further validate the complementary benefits of adaptive update routing and reward coordination.", "upvotes": 49, "discussionId": "6abf0f835ff0ac8de3b84a2a", "organization": {"_id": "66543b6e420092799d2f625c", "name": "tencent", "fullname": "Tencent", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/5dd96eb166059660ed1ee413/Lp3m-XLpjQGwBItlvn69q.png"}, "summary_zh": "<ul>\n    <li>\u591a\u5956\u52b1\u5f15\u5bfc\u7684\u5f3a\u5316\u5b66\u4e60\u53ef\u4ee5\u63d0\u9ad8\u97f3\u9891-\u89c6\u9891\u6269\u6563\u6a21\u578b\u7684\u591a\u4e2a\u76ee\u6807\uff0c\u5305\u62ec\u7279\u5b9a\u6a21\u6001\u8d28\u91cf\u548c\u8de8\u6a21\u6001\u8bed\u4e49\u5bf9\u9f50\u3002</li>\n    <li>\u73b0\u6709\u65b9\u6cd5\u4f9d\u8d56\u56fa\u5b9a\u7684\u66f4\u65b0\u548c\u5956\u52b1\u6743\u91cd\uff0c\u65e0\u6cd5\u9002\u5e94\u6a21\u578b\u5728\u8bad\u7ec3\u4e2d\u7684\u53d8\u5316\u3002</li>\n    <li>\u6211\u4eec\u63d0\u51fa\u4e86\u81ea\u9002\u5e94\u5956\u52b1\u8def\u7531\uff0c\u80fd\u591f\u5728\u97f3\u9891-\u89c6\u9891\u6269\u6563\u6a21\u578b\u7684\u524d\u5411\u8fc7\u7a0b\u5f3a\u5316\u5b66\u4e60\u4e2d\u52a8\u6001\u8c03\u6574\u66f4\u65b0\u4f4d\u7f6e\u548c\u5956\u52b1\u534f\u8c03\u3002</li>\n    <li>\u8be5\u65b9\u6cd5\u5305\u62ec\u4e24\u4e2a\u90e8\u5206\uff1a\u4f7f\u7528\u53cc\u5411\u8de8\u6ce8\u610f\u529b\u54cd\u5e94\u6765\u52a8\u6001\u8c03\u6574\u635f\u5931\u6743\u91cd\uff0c\u4ee5\u53ca\u4fdd\u7559\u9884\u5b9a\u4e49\u6743\u91cd\u4ee5\u534f\u8c03\u5956\u52b1\u3002</li>\n    <li>\u5b9e\u9a8c\u7ed3\u679c\u8868\u660e\uff0c\u8be5\u65b9\u6cd5\u5728\u6a21\u6001\u8d28\u91cf\u3001\u8bed\u4e49\u4e00\u81f4\u6027\u548c\u97f3\u89c6\u9891\u540c\u6b65\u65b9\u9762\u4f18\u4e8e\u73b0\u6709\u5f3a\u5316\u5b66\u4e60\u57fa\u7ebf\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Multi-reward guided reinforcement learning can enhance audio-video models by improving quality, alignment, and timing.</li>\n    <li>Current methods struggle because they use fixed strategies for updates and reward combinations that don\u2019t adapt as the model learns.</li>\n    <li>We introduce Adaptive Reward Routing, which adjusts both where to apply updates and how to combine rewards during training.</li>\n    <li>The method includes dynamic updates based on cross-modal interactions and maintains a balance between different reward influences.</li>\n    <li>Our experiments show that this approach leads to better quality, consistency, and synchronization in audio and video compared to existing methods.</li>\n</ul>"}, "publishedAt": "2026-09-28T20:00:00.000Z", "title": "Adaptive Reward Routing: Dynamic Multi-Reward Optimization for Joint Audio-Video Diffusion via Forward-Process RL", "summary": "Multi-reward guided reinforcement learning (i.e., RL) offers a promising way to improve joint audio-video diffusion models along several complementary objectives, including modality-specific quality, cross-modal semantic alignment, and temporal synchronization. Its effectiveness, however, depends on two quantities that change during training: where reward-driven updates should act, and how competing rewards should be combined. Existing methods tend to rely on fixed routing and reward weights, failing to track evolving model functions. To address these limitations, we propose Adaptive Reward Routing to jointly adapt update locations and reward coordination during forward-process RL (i.e., DiffusionNFT) of joint audio-video diffusion models. Our method consists of two components. (i) Cross-Modal Influence-Guided Routing (Localizing Updates): We use bidirectional cross-attention responses as an efficient proxy for evolving cross-modal influence, dynamically reweighting token-aware losses and scaling gradients across cross-modal layers without additional model interventions. (ii) Preference-Preserving Modality-Aware Reweighting (Coordinating Rewards): We preserve predefined weights as preference priors and use branch-specific reward-gradient interactions as residual corrections after warm-up. This resolves evolving conflicts without letting dominant rewards suppress weak but essential objectives. Extensive experiments demonstrate consistent improvements in modality quality, semantic consistency, and audio-video synchronization over strong RL baselines. Ablations and mechanism analyses further validate the complementary benefits of adaptive update routing and reward coordination.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2609.37200.png", "numComments": 1, "submittedBy": {"_id": "66f64956ad4fe83c91776459", "avatarUrl": "/avatars/2014de658ac12413754dcf70bc34333e.svg", "fullname": "Eddie", "name": "EddieYang428", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "isUserFollowing": false}, "organization": {"_id": "66543b6e420092799d2f625c", "name": "tencent", "fullname": "Tencent", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/5dd96eb166059660ed1ee413/Lp3m-XLpjQGwBItlvn69q.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2609.17708", "authors": [{"_id": "6aab84f51d9cc4dec796258e", "name": "Caiqi Zhang", "hidden": false}, {"_id": "6aab84f51d9cc4dec796258f", "name": "Xiaochen Zhu", "hidden": false}, {"_id": "6aab84f51d9cc4dec7962590", "name": "Chengzu Li", "hidden": false}, {"_id": "6aab84f51d9cc4dec7962591", "name": "Yulong Chen", "hidden": false}, {"_id": "6aab84f51d9cc4dec7962592", "name": "Dharshan Kumaran", "hidden": false}, {"_id": "6aab84f51d9cc4dec7962593", "name": "Nigel Collier", "hidden": false}], "publishedAt": "2026-09-15T00:00:00.000Z", "submittedOnDailyAt": "2026-09-17T00:00:00.000Z", "title": "Confidence Comes from Experience: Experiential Confidence Estimation from Reasoning to Agents", "submittedOnDailyBy": {"_id": "63920dfac47e36ddeb8f1864", "avatarUrl": "/avatars/c36cbf7b084d62368312e5c9292e4260.svg", "isPro": false, "fullname": "Caiqi Zhang", "user": "caiqizh", "type": "user", "name": "caiqizh"}, "summary": "Reliable confidence estimation is increasingly central to the trustworthy deployment of language models: a calibrated estimate of the probability that an output is correct decides what to ship, what to escalate, and what to retry. Existing confidence estimators, however, share one design premise: they only read the current inference process, either by introspecting on it, scoring its token probabilities, or resampling it. We argue that the current inference is not a sufficient basis for confidence. We propose XConf (eXperiential Confidence): estimating confidence together with the model's accumulated experience. The experience is stored as a record of the model's own graded past episodes, each holding the task, the model's reflection, its stated confidence, the outcome, and a lesson written once the grade arrived. Given a new task, XConf's Recall stage retrieves past episodes on similar tasks met with a similar stated confidence, and reads off their historical success rate; its Reflect stage shows the model this record, has it name its recurring failure mode, and restate a confidence now informed by its own track records. Our estimator is format-general, requiring no logit access or weight updates, and costs only one answer generation. Across nine benchmarks spanning reasoning, coding, multimodal QA, and interactive agents, and four models from three families, XConf beats or matches ten-sample self-consistency in discrimination (AUROC) on 23 of 24 comparisons, with much lower calibration error (ECE), at a tenth of the generation cost. Used for selective prediction, abstaining on the 10% least-confident episodes raises the delivered success rate by up to 8.7 points on agent tasks. We therefore see experiential confidence estimation as a new paradigm for future general-purpose confidence estimation.", "upvotes": 49, "discussionId": "6aab84f61d9cc4dec7962594", "projectPage": "https://caiqizh.github.io/xconf/", "githubRepo": "https://github.com/caiqizh/xconf", "githubRepoAddedBy": "user", "githubStars": 1, "organization": {"_id": "65f9e02087d1c912d985eebf", "name": "CambUni", "fullname": "University of Cambridge", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/noauth/gdCou-0KoYsLPYqPrz6xn.png"}, "summary_zh": "<ul>\n    <li>\u53ef\u9760\u7684\u4fe1\u5fc3\u4f30\u8ba1\u5bf9\u8bed\u8a00\u6a21\u578b\u7684\u4fe1\u4efb\u90e8\u7f72\u975e\u5e38\u91cd\u8981\uff0c\u5e2e\u52a9\u51b3\u5b9a\u54ea\u4e9b\u7ed3\u679c\u53ef\u4ee5\u53d1\u5e03\u3001\u54ea\u4e9b\u9700\u8981\u5347\u7ea7\u6216\u91cd\u8bd5\u3002</li>\n    <li>\u73b0\u6709\u7684\u4fe1\u5fc3\u4f30\u8ba1\u65b9\u6cd5\u53ea\u5173\u6ce8\u5f53\u524d\u63a8\u7406\u8fc7\u7a0b\uff0c\u8ba4\u4e3a\u8fd9\u4e0d\u8db3\u4ee5\u63d0\u4f9b\u8db3\u591f\u7684\u4fe1\u5fc3\u4f9d\u636e\u3002</li>\n    <li>\u6211\u4eec\u63d0\u51fa\u4e86XConf\uff08\u7ecf\u9a8c\u4fe1\u5fc3\uff09\uff0c\u901a\u8fc7\u8bb0\u5f55\u6a21\u578b\u7684\u8fc7\u53bb\u7ecf\u9a8c\u6765\u4f30\u8ba1\u4fe1\u5fc3\uff0c\u5305\u62ec\u4efb\u52a1\u3001\u6a21\u578b\u53cd\u601d\u3001\u4fe1\u5fc3\u58f0\u660e\u548c\u7ed3\u679c\u7b49\u3002</li>\n    <li>XConf\u901a\u8fc7\u56de\u5fc6\u76f8\u4f3c\u4efb\u52a1\u7684\u6210\u529f\u7387\u548c\u53cd\u601d\u6a21\u5f0f\u6765\u66f4\u65b0\u4fe1\u5fc3\uff0c\u4e14\u4e0d\u9700\u8981\u8bbf\u95ee\u6a21\u578b\u6743\u91cd\u6216\u66f4\u65b0\u3002</li>\n    <li>\u5728\u591a\u4e2a\u57fa\u51c6\u6d4b\u8bd5\u4e2d\uff0cXConf\u5728\u4fe1\u5fc3\u5224\u65ad\u4e0a\u8868\u73b0\u4f18\u4e8e\u5176\u4ed6\u65b9\u6cd5\uff0c\u5e76\u663e\u8457\u63d0\u9ad8\u4e86\u6210\u529f\u7387\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Confidence estimation is important for using language models reliably and deciding on their outputs.</li>\n    <li>Current methods only consider the immediate task, but this is not enough for accurate confidence estimation.</li>\n    <li>The proposed method, XConf (eXperiential Confidence), uses the model's past experiences to improve confidence estimates.</li>\n    <li>XConf analyzes past tasks and their outcomes to inform current confidence levels and identifies recurring issues.</li>\n    <li>Tests show XConf performs better than traditional methods, with lower error rates and improved success rates on tasks.</li>\n</ul>"}, "publishedAt": "2026-09-14T20:00:00.000Z", "title": "Confidence Comes from Experience: Experiential Confidence Estimation from Reasoning to Agents", "summary": "Reliable confidence estimation is increasingly central to the trustworthy deployment of language models: a calibrated estimate of the probability that an output is correct decides what to ship, what to escalate, and what to retry. Existing confidence estimators, however, share one design premise: they only read the current inference process, either by introspecting on it, scoring its token probabilities, or resampling it. We argue that the current inference is not a sufficient basis for confidence. We propose XConf (eXperiential Confidence): estimating confidence together with the model's accumulated experience. The experience is stored as a record of the model's own graded past episodes, each holding the task, the model's reflection, its stated confidence, the outcome, and a lesson written once the grade arrived. Given a new task, XConf's Recall stage retrieves past episodes on similar tasks met with a similar stated confidence, and reads off their historical success rate; its Reflect stage shows the model this record, has it name its recurring failure mode, and restate a confidence now informed by its own track records. Our estimator is format-general, requiring no logit access or weight updates, and costs only one answer generation. Across nine benchmarks spanning reasoning, coding, multimodal QA, and interactive agents, and four models from three families, XConf beats or matches ten-sample self-consistency in discrimination (AUROC) on 23 of 24 comparisons, with much lower calibration error (ECE), at a tenth of the generation cost. Used for selective prediction, abstaining on the 10% least-confident episodes raises the delivered success rate by up to 8.7 points on agent tasks. We therefore see experiential confidence estimation as a new paradigm for future general-purpose confidence estimation.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2609.17708.png", "numComments": 2, "submittedBy": {"_id": "63920dfac47e36ddeb8f1864", "avatarUrl": "/avatars/c36cbf7b084d62368312e5c9292e4260.svg", "fullname": "Caiqi Zhang", "name": "caiqizh", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "isUserFollowing": false}, "organization": {"_id": "65f9e02087d1c912d985eebf", "name": "CambUni", "fullname": "University of Cambridge", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/noauth/gdCou-0KoYsLPYqPrz6xn.png"}, "isAuthorParticipating": false}]
};
